\section*{Applications}

\subsection*{Groupoids}
We denote by $\mathrm{Gpd}$ the $1$-category of small groupoids and by $\mathrm{Gpd}_2$ the $\infty$-category associated to the $(2,1)$-category of groupoids in which the $2$-morphisms are natural transformations. The category $\mathrm{Gpd}$ admits a simplicial model structure in which the equivalences are equivalences of categories and the cofibrations are functors that are injective on the set of objects. In this model structure all objects are cofibrant and fibrant, compare \cite{Casacuberta}. Furthermore if we denote by $\mathrm{Gpd}^\omega$ the full subcategory on groupoids with at most countable many morphisms then $\mathrm{Gpd}^\omega$ inherits the structure of a cofibration category.

The following lemma is a well known fact, but we had difficulties finding a clear reference for this so we state it as an extra lemma.
\begin{Lemma}\label{lemma3}
The canonical map $\mathrm{N}\mathrm{Gpd}[w^{-1}] \to \mathrm{Gpd}_2$ is an equivalence of $\infty$-categories.
\end{Lemma}
\begin{proof}
This follows from the description of the $\infty$-category associated to a simplicial model category, see \cite[Theorem 1.3.4.20]{LurieHA}, as being the the homotopy coherent nerve of the simplicial category of cofibrant and fibrant objects.
\end{proof}



\begin{Cor}\label{groupoids1}
Let $\c$ be an $\infty$-category. Then the canonical map $\mathrm{N} c\:\!\mathrm{Gpd} \to \mathrm{Grp}_2 $ induces an equivalence
\begin{tikzeq*}
  \matrix[diagram]
  {
    |(2)| \mathrm{Fun}(\mathrm{Gpd}_2,\c) & |(i)| \mathrm{Fun}^w(\mathrm{N} c\:\!\mathrm{Gpd},\c) \\
  };

  \draw[->] (2) to node[above] {$\simeq$} (i);
\end{tikzeq*}
where the superscript $w$ refers to functors that send equivalences of groupoids to equivalences in $\c$.
\end{Cor}
\begin{proof}
Since the canonical map  $\mathrm{N}\mathrm{Gpd}[w^{-1}] \to \mathrm{Gpd}_2$ is an equivalence by \cref{lemma3}, this is a direct application of \cref{main theorem}.
\end{proof}

The following corollary of Proposition \ref{prop} implies that in the approach to assembly maps discussed in \cite[section 2]{DavisLueck} one can directly restrict to functors from groupoids to spectra that are only defined for maps of groupoids that are injective on objects. This resolves the issues illustrated in \cite[Remark 2.3]{DavisLueck}.
\begin{Cor}\label{groupoidscor2}
Let $\mathrm{Sp}$ be any of the categories of spectra. Then every functor $F: c\:\!\mathrm{Gpd} \to \mathrm{Sp}$ which sends equivalences of groupoids to weak equivalences in $\mathrm{Sp}$ extends uniquely (in the sense of Proposition \ref{prop}) to a functor 
$\widehat{F}: \mathrm{Gpd} \to \mathrm{Sp}$ which also sends weak equivalences of groupoids to weak equivalences of spectra.
\end{Cor}
\begin{Rmk}
The statements of \cref{groupoids1} and \cref{groupoidscor2} remain  true if we replace $\mathrm{Gpd}$ by $\mathrm{Gpd}^\omega$. Furthermore \cref{groupoidscor2} does not depend on the exact choice of model category of spectra as long as it is Quillen equivalent to a combinatorial model category. 
\end{Rmk}


Next we want to demonstrate how to apply these results by \emph{functorially} constructing $C^*$-algebras and topological $K$-theory spectra associated to groupoids. This discussion is similar to the one given in \cite[section 3]{Joachim2} but we use our main theorem to obtain full functoriality instead of an explicit construction.
\begin{Def}\label{groupoid algebra}
Let $\mathcal{G}$ be a groupoid.
We let $\mathbb{C}\mathcal{G}$ be the $\mathbb{C}$-linearization of the set of morphisms of $\mathcal{G}$. This is a $\mathbb{C}$-algebra by linearization of the multiplication on morphisms given by
\[ f\cdot g = \begin{cases} f\circ g & \text{ if $f$ and $g$ are composable} \\ 0 & \text{ else.} \end{cases} \] 
We remark that $\mathbb{C}\mathcal{G}$ is unital if and only if the set of objects of $\mathcal{G}$ is finite.
Then we complete $\mathbb{C}\mathcal{G}$ in a universal way, like for the full group $C^*$-algebra, to obtain a $C^*$-algebra $C^*\mathcal{G}$. More precisely, the norm is given by the supremum over all norms of representations of $\mathbb{C}\mathcal{G}$ on a separable Hilbert space.
This is isomorphic to the $C^*$-algebra associated to the maximal groupoid $C^*$-category of \cite[Definition 3.16]{DellAmbrogio2} using the construction $\mathcal{C} \mapsto A_\mathcal{C}$ of \cite[section 3]{Joachim2}. 
\end{Def}
The association $\mathcal{G} \mapsto \mathbb{C}^*\mathcal{G}$ is functorial for cofibrations of groupoids but not for general morphisms since it can happen that morphisms are not composable in a groupoid, but become composable after applying a functor, compare the remark \cite[page 214]{DavisLueck}. We observe that the $C^*$-algebra $\mathbb{C}^*\mathcal{G}$ is separable provided $\mathcal{G} \in \mathrm{Gpd}^\omega$. 

\begin{Lemma}\label{morita invariance}
Let $F\colon \mathcal{G}_1 \to \mathcal{G}_2$ be an acyclic cofibration of groupoids. Then the induced morphism
\[ C^*F \colon C^*\mathcal{G}_1 \to C^*\mathcal{G}_2 \]
is a $\mathrm{KK}$-equivalence.
\end{Lemma}
\begin{proof}
The $C^*$-algebra associated to a groupoid is the product of the $C^*$-algebras associated to each connected component. Thus we may assume that $\mathcal{G}_1$ (and thus $\mathcal{G}_2$) is connected.
Let $x \in \mathcal{G}$ be an object. We let $G_1 = \mathrm{End}(x)$ and $G_2 = \mathrm{End}(Fx)$ be the endomorphism groups and notice the fact that $F$ is an equivalence implies that $F$ induces an isomorphism $G_1 \cong G_2$.
Then we consider the diagram
\begin{tikzeq*}
  \matrix[diagram]
  {
    |(1c)| C^*\mathcal{G}_1 & |(2c)| C^*\mathcal{G}_2 \\
    |(1)|  C^*G_1  & |(2)|  C^*G_2  \\
  };

  \draw[->] (1c) to node[above] {$C^*F$} (2c);
  \draw[->] (1)  to node[below] {$\cong$} (2);

  \draw[->] (1) to (1c);
  \draw[->] (2) to (2c);
\end{tikzeq*}
in which the lower horizontal arrow is an isomorphism. Thus to show the lemma it suffices to prove the lemma in the special case where $F$ is the inclusion of the endomorphisms of an object $x$ of a connected groupoid $\mathcal{G}$.

This can be done using in the abstract setting of corner algebras. For this suppose $A$ is a $C^*$-algebra and $p \in A$ is a projection. It is called full if $ApA$ is dense in $A$. The algebra $pAp$ is called the corner algebra of $p$ in $A$. It is called a full corner if $p$ is a full projection. We write $i_p$ for the inclusion $pAp \subset A$. Given a projection $p$ the module $pA$ is an imprimitivity $pAp-\overline{ApA}$ bimodule, see e.g. \cite[Example 3.6]{Raeburn}. Thus if $p$ is full, then $pA$ gives rise to an invertible element $[pA,i_p,0]= \mathcal{F}(p) \in \mathrm{KK}(pAp,A)$.  In this KK-group we have an equality
\begin{align*} \mathcal{F}(p) & = [\,pA,i_p,0] + [(1-p)A,0,0] \\ & = [\,pA\oplus(1-p)A,i_p,0] \\ &= [A,i_p,0] = [i_p] ,
\end{align*}
in other words, the inclusion $pAp \to A$ of a corner algebra associated to a full projection is a KK-equivalence. 

To come back to our situation let us suppose $\mathcal{G}$ is a groupoid, $x \in \mathcal{G}$ is an object and let us denote its endomorphism group by $G = \mathrm{End}(x)$. We can consider the element $p = \mathrm{id}_x \in C^*\mathcal{G}$ which is clearly a projection. Its corner algebra is given by
\[ p\cdot C^*\mathcal{G} \cdot p \cong C^*G.\]
If $\mathcal{G}$ is connected it follows that every morphism in $\mathcal{G}$ may be factored through $\mathrm{id}_x$ and thus $p$ is full if $\mathcal{G}$ is connected. Hence it follows that the inclusion $C^*G \to C^*\mathcal{G}$ is an embedding of a full corner algebra. Thus by the general theory this inclusion is a KK-equivalence which proves the lemma.
\end{proof}

Let us denote by $\mathrm{KK}_\infty$ the $\infty$-category given by the localization of the category $\mathrm{C^*Alg}$ of separable $C^*$-algebras at the KK-equivalences, see e.g. \cite[Definition 3.2]{LandNikolaus}. In formulas we have $\mathrm{KK}_\infty := \mathrm{N}\mathrm{C^*Alg}[w^{-1}]$ where $w$ denotes the class of KK-equivalences. The homotopy category of $\mathrm{KK}_\infty$ is Kasparov's KK-category of $C^*$-algebras.

\begin{Cor}\label{groupoids2}
There exists a functor
\[ \mathrm{Gpd}_2^\omega \to \mathrm{KK}_\infty \]
which on objects sends a groupoid $\mathcal{G}$ to the full groupoid $C^*$-algebra $C^*\mathcal{G}$.
\end{Cor}
\begin{Rmk}
We notice that the $(2,1)$-category $\mathrm{Orb}^\omega$ consisting of (countable) groups, group homomorphisms, and conjugations is the full subcategory of the $(2,1)$-category of (countable) groupoids on connected groupoids and hence along this inclusion we also obtain a functor
\[ \mathrm{Orb}^\omega \to \mathrm{KK}_\infty \]
which on objects sends a group to its full group $C^*$-algebra. This will be used in \cite{LandNikolaus} to compare the $L$-theoretic Farrell-Jones conjecture and the Baum-Connes conjecture. 
\end{Rmk}
\begin{proof}[Proof of \cref{groupoids2}]
By \cref{groupoids1} and the remark after \cref{groupoidscor2}, we have an equivalence
\[ \mathrm{Fun}^w(\mathrm{N} c\:\!\mathrm{Gpd}^\omega,\mathrm{KK}_\infty) \simeq \mathrm{Fun}(\mathrm{Gpd}_2^\omega,\mathrm{KK}_\infty) \]
and thus it suffices to construct a functor
\[ c\:\!\mathrm{Gpd}^\omega \to \mathrm{C^*Alg} \]
which has the \emph{property} that it sends equivalences of groupoids to $\mathrm{KK}$-equivalences.
We have established in \cref{morita invariance} that the functor of \cref{groupoid algebra} satisfies this property.
\end{proof}

\begin{Rmk}
In \cite[Proposition 3.7]{LandNikolaus} it is shown that the topological $K$-theory functor 
\[ K\colon \mathrm{N}\mathrm{C^*Alg} \to \mathrm{Sp} \]
factors over $\mathrm{KK}_\infty$, in fact becomes corepresentable there. It thus follows from \cref{groupoids2} that there is a functor sending a groupoid to the topological $K$-theory spectrum of its $C^*$-algebra.
\end{Rmk}


\section*{The proof of \cref{main theorem}}

In this section we will prove \cref{main theorem}.
Recall that we consider a cofibration category $(\c,w\c,c\:\!\c)$ and
aim to compare the $\infty$-categories associated to
the relative categories $(\c,w\c)$ and $(c\:\!\c,wc\:\!\c)$.
As our model of the homotopy theory of $(\infty,1)$-categories we will use
\emph{complete Segal spaces} of Rezk, see \cite{Rezk}.
This homotopy theory is modelled by the Rezk model structure on the category of
bisimplicial sets in which fibrant objects are the complete Segal spaces.
The model structure is constructed as a Bousfield localization of
the Reedy model structure and hence every levelwise weak equivalence of
bisimplicial sets is a Rezk equivalence, i.e.\ an equivalence of $\infty$-categories.

The $\infty$-category associated to a relative category $(\mathscr{D},w\mathscr{D})$ is modelled by
the \emph{classification diagram} $\mathrm{N}^\mathrm{R}\mathscr{D}$ of Rezk which is given by
\[ (\mathrm{N}^\mathrm{R}\mathscr{D})_k \mapsto \mathrm{N} w(\mathscr{D}^{[k]}),\]
where the weak equivalences in $\mathscr{D}^{[k]}$ are levelwise weak equivalences, 
compare \cite[section 3.3]{Rezk} and \cite[Theorem 3.8]{Mazel-Gee}. See also the MathOverflow post \cite{Cisinksi2}.
The classification diagram is not fibrant in the Rezk model structure,
but it is levelwise equivalent to a fibrant object if $\mathscr{D}$ is a cofibration category.


Recall that we stated \cref{main theorem} under the following assumption on the cofibration category $\c$.
\begin{Def}\label{good-cylinders}
  A cofibration category $\c$ has \emph{good cylinders} if
  it has a cylinder functor $I$ such that for every cofibration $X \rightarrowtail Y$
  the induced morphism $I X \sqcup_{X \sqcup X} (Y \sqcup Y) \to I Y$
  is a cofibration.
\end{Def}

For example any cofibration category arising from a monoidal model category
(or a model category enriched over a monoidal model category)
has good cylinders, since
they are given by tensoring with a chosen interval object.

\begin{Thm}\label{cC-C}
  If $\c$ has good cylinders, then
  the inclusion $c\:\!\c \to \c$ induces a levelwise weak equivalence of
  the classification diagrams $\mathrm{N}^\mathrm{R} c\:\!\c \to \mathrm{N}^\mathrm{R}\c$.
\end{Thm}

For the proof we will need a series of auxiliary definitions and lemmas.
Let us first fix some notation.
If $J$ is a category, then $\hat{J}$ denotes $J$ considered as
a relative category with all morphisms as weak equivalences.
If $J$ is any relative category, then $\c^J$ stands for
the cofibration category of all relative diagrams $J \to \c$ with
levelwise weak equivalences and cofibrations.
If $J$ is any relative direct category, then $\c^J_\mathrm{R}$ stands for
the cofibration category of
all relative Reedy cofibrant diagrams $J \to \c$ with
levelwise weak equivalences and Reedy cofibrations.
See \cite[Theorem 9.3.8]{Radulescu-Banu}
for the construction of these cofibration categories.

\begin{Def}
  A subcategory $g\c$ of a cofibration category $\c$ is said to be \emph{good} if
  \begin{itemize}
  \item all cofibrations are in $g\c$;
  \item the morphisms of $g\c$ are
    stable under pushouts along cofibrations;
  \item $\c$ has functorial factorizations that preserve $g\c$
    in the sense that if
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(A0)| A_0 & |(B0)| B_0 \\
        |(A1)| A_1 & |(B1)| B_1 \\
      };

      \draw[->] (A0) to (B0);
      \draw[->] (A1) to (B1);

      \draw[->] (A0) to (A1);
      \draw[->] (B0) to (B1);
    \end{tikzeq*}
    is a square in $\c$ such that both vertical morphisms are in $g\c$
    and
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(A0)| A_0 & |(tB0)| \tilde{B}_0 & |(B0)| B_0 \\
        |(A1)| A_1 & |(tB1)| \tilde{B}_1 & |(B1)| B_1 \\
      };

      \draw[cof] (A0) to (tB0);
      \draw[cof] (A1) to (tB1);

      \draw[->] (tB0) to node[above] {$\mathrel\sim$} (B0);
      \draw[->] (tB1) to node[below] {$\mathrel\sim$} (B1);

      \draw[->] (A0) to (A1);
      \draw[->] (tB0) to (tB1);
      \draw[->] (B0) to (B1);
    \end{tikzeq*}
    is the resulting factorization, then the induced morphism
    $A_1 \sqcup_{A_0} \tilde{B}_0 \to \tilde{B}_1$ is also in $g\c$.
    (In particular, so is $\tilde{B}_0 \to \tilde{B}_1$
    by the second condition.)
  \end{itemize}
\end{Def}

Now suppose that $\c$ is cofibration category with a good subcategory $g\c$.
We let $W\c$ be the bisimplicial set whose $(m,n)$-bisimplices are
all diagrams in $\c$ of the form
\begin{tikzeq*}
  \matrix[diagram]
  {
    |(00)| X_{0,0} & |(01)| X_{0,1} & |(0l)| \ldots & |(0n)| X_{0,n} \\
    |(10)| X_{1,0} & |(11)| X_{1,1} & |(1l)| \ldots & |(1n)| X_{1,n} \\
    |(l0)| \vdots  & |(l1)| \vdots  &               & |(ln)| \vdots  \\
    |(m0)| X_{m,0} & |(m1)| X_{m,1} & |(ml)| \ldots & |(mn)| X_{m,n}
    \text{,} \\
  };

  \draw[cof] (00) to node[above] {$\mathrel\sim$} (01);
  \draw[cof] (01) to node[above] {$\mathrel\sim$} (0l);
  \draw[cof] (0l) to node[above] {$\mathrel\sim$} (0n);

  \draw[cof] (10) to node[above] {$\mathrel\sim$} (11);
  \draw[cof] (11) to node[above] {$\mathrel\sim$} (1l);
  \draw[cof] (1l) to node[above] {$\mathrel\sim$} (1n);

  \draw[cof] (m0) to node[below] {$\mathrel\sim$} (m1);
  \draw[cof] (m1) to node[below] {$\mathrel\sim$} (ml);
  \draw[cof] (ml) to node[below] {$\mathrel\sim$} (mn);

  \draw[->] (00) to node[left] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (10);
  \draw[->] (10) to node[left] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (l0);
  \draw[->] (l0) to node[left] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (m0);

  \draw[->] (01) to node[left] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (11);
  \draw[->] (11) to node[left] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (l1);
  \draw[->] (l1) to node[left] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (m1);

  \draw[->] (0n) to node[right] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (1n);
  \draw[->] (1n) to node[right] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (ln);
  \draw[->] (ln) to node[right] {$\mathrel\sim$} node[below right = 0.25 cm and 0.02 cm] {\tiny$g$} (mn);
\end{tikzeq*}
i.e.\ diagrams $\hat{[m]} \times \hat{[n]} \to \c$ where
all horizontal morphisms are cofibrations and
all vertical morphisms are in $g\c$.
In other words $W\c$ is the nerve of a double category with
the same objects as $\c$, whose
horizontal morphisms are acyclic cofibrations,
vertical morphisms are weak equivalences in $g\c$,
and double morphisms are just commutative squares.

\begin{Lemma}
  The bisimplicial set $W\c$ is vertically homotopically constant,
  i.e.\ every simplicial operator $[n] \to [n']$ induces
  a weak homotopy equivalence $(W\c)_{*,n'} \to (W\c)_{*,n}$.
\end{Lemma}

\begin{proof}
  Note that $(W\c)_{*,n} = \mathrm{N} \tilde{\c}_n$ where
  $\tilde{\c}_n$ is a category whose
  objects are diagrams $\hat{[n]} \to c\:\!\c$ and
  whose morphisms are weak equivalences with all components in $g\c$.
  It is enough to consider the case $n' = 0$,
  i.e.\ to show that the constant functor
  $\operatorname{const} \colon \tilde{\c}_0 \to \tilde{\c}_n$
  is a homotopy equivalence.
  The evaluation at $n$ functor
  $\operatorname{ev}_n \colon \tilde{\c}_n \to \tilde{\c}_0$
  satisfies $\operatorname{ev}_n \operatorname{const} = \mathrm{id}_{\tilde{\c}_0}$.
  Moreover, the structure maps of
  every diagram $X \in \tilde{\c}_n$ form
  a natural weak equivalence $X \to \operatorname{const} \operatorname{ev}_n X$
  since every cofibration is in $g\c$.
\end{proof}

\begin{Lemma}\label{W-horizontal}
  The bisimplicial set $W\c$ is horizontally homotopically constant,
  i.e.\ every simplicial operator $[m] \to [m']$ induces
  a weak homotopy equivalence $(W\c)_{m',*} \to (W\c)_{m,*}$.
\end{Lemma}

\begin{proof}    
  Note that $(W\c)_{m,*} = \mathrm{N} \bar{\c}_m$ where
  $\bar{\c}_m$ is a category whose
  objects are diagrams $\hat{[m]} \to g\c$ and
  whose morphisms are acyclic levelwise cofibrations.
  Again, it is enough to consider the case $m' = 0$
  and to show that the constant functor
  $\operatorname{const} \colon \bar{\c}_0 \to \bar{\c}_m$
  and the evaluation at $m$ functor
  $\operatorname{ev}_m \colon \bar{\c}_n \to \bar{\c}_0$
  form a homotopy equivalence.

  We have $\operatorname{ev}_m \operatorname{const} = \mathrm{id}_{\bar{\c}_0}$.
  Moreover, given any object $X \in \bar{\c}_m$
  and $i \in [m]$ we consider the composite weak equivalence $X_i \stackrel{\we}{\to} X_m$.
  We combine it with the identity $X_m \to X_m$ and
  factor functorially the resulting morphism $X_i \sqcup X_m \to X_m$ as
  $X_i \sqcup X_m \rightarrowtail \tilde{X}_i \stackrel{\we}{\to} X_m$.
  In the square
  \begin{tikzeq*}
    \matrix[diagram]
    {
      |(mi)| X_m \sqcup X_i     & |(i)| X_m \\
      |(m1)| X_m \sqcup X_{i+1} & |(1)| X_m \\
    };

    \draw[->] (mi) to (i);
    \draw[->] (m1) to (1);
    \draw[->] (i)  to (1);
    \draw[->] (mi) to (m1);
  \end{tikzeq*}
  both vertical morphisms are in $g\c$
  (since $g\c$ is closed under pushouts).
  Thus the induced morphism $\tilde{X}_i \to \tilde{X}_{i+1}$
  is in $g\c$.
  Moreover, we obtain acyclic cofibrations
  $X_i \stackrel{\we}{\cto} \tilde{X}_i$ and $X_m \stackrel{\we}{\cto} \tilde{X}_i$ that
  constitute a zig-zag of natural weak equivalences connecting
  $\operatorname{const} \operatorname{ev}_m$ and $\mathrm{id}_{\bar{\c}_m}$.
\end{proof}

\begin{Lemma}\label{W-diagonal}
  The inclusion $\mathrm{N} wc\:\!\c \to \mathrm{N} wg\c$ is a weak homotopy equivalence.
\end{Lemma}

\begin{proof}
  Observe that the $0$th row and the $0$th column of $W\c$ are
  $\mathrm{N} wg\c$ and $\mathrm{N} wc\:\!\c$ respectively.
  Since $W\c$ is homotopically constant in both directions,
  it follows from \cite[Proposition IV.1.7]{Goerss-Jardine}
  that we have weak equivalences
  \begin{tikzeq*}
    \matrix[diagram]
    {
      |(g)| \mathrm{N} wg\c & |(d)| \mathrm{diag} W\c & |(c)| \mathrm{N} wc\:\!\c \text{.} \\
    };

    \draw[->] (g) to node[above] {$\mathrel\sim$} (d);
    \draw[->] (c) to node[above] {$\mathrel\sim$} (d);
  \end{tikzeq*}
  Moreover, the restrictions along
  the diagonal inclusions $[m] \to [m] \times [m]$ induce
  a simplicial map $\mathrm{diag} W\c \to \mathrm{N} wg\c$ whose composites with
  the two maps above are the identity on $\mathrm{N} wg\c$ and
  the inclusion $\mathrm{N} wc\:\!\c \to \mathrm{N} wg\c$.
  Hence the latter is a weak equivalence by 2-out-of-3.
\end{proof}

Next we establish that under specific circumstances certain subcategories of $\c$ are good.

\begin{Lemma}\label{levelwise-good}
  Let $\c$ be a cofibration category.
  \begin{enumerate}
  \item If $\c$ has functorial factorizations,
    then $\c$ itself is a good subcategory.
  \item If $\c$ has good cylinders,
    then $c\:\!\c$ is a good subcategory of $\c$.
  \item If $c\:\!\c$ is a good subcategory of $\c$,
    then the subcategory of levelwise cofibrations is
    a good subcategory of $\c^{[k]}_\mathrm{R}$ for all $k$.
  \end{enumerate}
\end{Lemma}

\begin{proof}
  \leavevmode
  \begin{enumerate}
  \item This is vacuously true.
  \item We will show that the standard mapping cylinder factorization
    makes $c\:\!\c$ into a good subcategory.
    Let
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(A0)| A_0 & |(B0)| B_0 \\
        |(A1)| A_1 & |(B1)| B_1 \\
      };

      \draw[->] (A0) to (B0);
      \draw[->] (A1) to (B1);

      \draw[cof] (A0) to (A1);
      \draw[cof] (B0) to (B1);
    \end{tikzeq*}
    be a square were both vertical morphisms are cofibrations.
    The mapping cylinder of $A_i \to B_i$ is constructed as
    $I A_i \sqcup_{A_i \sqcup A_i} (A_i \sqcup B_i)$.
    We need to show that the morphism induced by the square
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(A0)| A_0 & |(I0)| I A_0 \sqcup_{A_0 \sqcup A_0} (A_0 \sqcup B_0) \\
        |(A1)| A_1 & |(I1)| I A_1 \sqcup_{A_1 \sqcup A_1} (A_1 \sqcup B_1) \\
      };

      \draw[->] (A0) to (I0);
      \draw[->] (A1) to (I1);

      \draw[->] (I0) to (I1);
      \draw[->] (A0) to (A1);
    \end{tikzeq*}
    is a cofibration.
    This morphism coincides with
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(0)| I A_0 \sqcup_{A_0 \sqcup A_0} (A_1 \sqcup B_0) &
        |(1)| I A_1 \sqcup_{A_1 \sqcup A_1} (A_1 \sqcup B_1) \\
      };

      \draw[->] (0) to (1);
    \end{tikzeq*}
    which factors as
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(0)| I A_0 \sqcup_{A_0 \sqcup A_0} (A_1 \sqcup B_0) &
        |(1)| I A_0 \sqcup_{A_0 \sqcup A_0} (A_1 \sqcup B_1) &
        |(2)| I A_1 \sqcup_{A_1 \sqcup A_1} (A_1 \sqcup B_1) \text{.} \\
      };

      \draw[->] (0) to (1);
      \draw[->] (1) to (2);
    \end{tikzeq*}
    The first morphism is a pushout of $A_1 \sqcup B_0 \to A_1 \sqcup B_1$
    which is a cofibration since $B_0 \to B_1$ is.
    The second morphism is a pushout of
    $I A_0 \sqcup_{A_0 \sqcup A_0} (A_1 \sqcup A_1) \to I A_1$
    which is a cofibration since $A_0 \to A_1$ is and $\c$ has good cylinders.
  \item Clearly, every Reedy cofibration is a levelwise cofibration and
    levelwise cofibrations are stable under pullbacks.
    Consider a diagram
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(A0)| A_0 & |(tB0)| \tilde{B}_0 & |(B0)| B_0 \\
        |(A1)| A_1 & |(tB1)| \tilde{B}_1 & |(B1)| B_1 \\
      };

      \draw[cof] (A0) to (tB0);
      \draw[cof] (A1) to (tB1);

      \draw[->] (tB0) to node[above] {$\mathrel\sim$} (B0);
      \draw[->] (tB1) to node[below] {$\mathrel\sim$} (B1);

      \draw[->] (A0) to (A1);
      \draw[->] (tB0) to (tB1);
      \draw[->] (B0) to (B1);
    \end{tikzeq*}
    in $\c^J_\mathrm{R}$ where $\tilde{B}_0$ and $\tilde{B}_1$
    are obtained by the standard Reedy factorization induced by
    the given functorial factorization in $\c$.
    Assuming that $A_0 \to A_1$ and $B_0 \to B_1$ are levelwise cofibrations,
    we need to check that
    $A_{1,i} \sqcup_{A_{0,i}} \tilde{B}_{0,i} \to \tilde{B}_{1,i}$
    is a cofibration for every $i \in [m]$.

    For $i = 0$, this follows directly from the assumption that
    $c\:\!\c$ is a good subcategory of $\c$.
    The Reedy factorization is constructed by induction over $[m]$,
    so assume that the conclusion is already known for $i < m$.
    The factorization at level $i+1$ arises as
    \begin{tikzeq*}
      \matrix[diagram]
      {
        |(A0)|  A_{0,i+1} \sqcup_{A_{0,i}} \tilde{B}_{0,i} &
        |(tB0)| \tilde{B}_{0,i+1} & |(B0)| B_{0,i+1} \\
        |(A1)|  A_{1,i+1} \sqcup_{A_{1,i}} \tilde{B}_{1,i} &
        |(tB1)| \tilde{B}_{1,i+1} & |(B1)| B_{1,i+1} \\
      };

      \draw[cof] (A0) to (tB0);
      \draw[cof] (A1) to (tB1);

      \draw[->] (tB0) to node[above] {$\mathrel\sim$} (B0);
      \draw[->] (tB1) to node[below] {$\mathrel\sim$} (B1);

      \draw[->] (A0) to (A1);
      \draw[->] (tB0) to (tB1);
      \draw[->] (B0) to (B1);
    \end{tikzeq*}
    where the left square comes from the diagram
    \begin{tikzeq*}
      \matrix[diagram,row sep=2em,column sep=2em]
      {
          |(A0i)| A_{0,i}   & & |(B0i)| \tilde{B}_{0,i} &[1em] \\
        & |(A01)| A_{0,i+1} & & |(P0)|  \bullet & & |(B01)| \tilde{B}_{0,i+1} \\
          |(A1i)| A_{1,i}   & & |(B1i)| \tilde{B}_{1,i} & \\
        & |(A11)| A_{1,i+1} & & |(P1)|  \bullet & & |(B11)| \tilde{B}_{1,i+1} \\
      };

      \draw[->] (B01) to (B11);
      \draw[->] (P0)  to (B01);
      \draw[->] (P1)  to (B11);

      \draw[->] (A0i) to (B0i);
      \draw[->] (A1i) to (B1i);

      \draw[->] (A0i) to (A1i);
      \draw[->] (B0i) to (B1i);

      \draw[->,over] (A01) to (P0);
      \draw[->] (A11) to (P1);

      \draw[->,over] (A01) to (A11);
      \draw[->] (P0) to (P1);

      \draw[->] (A0i) to (A01);
      \draw[->] (B0i) to (P0);
      \draw[->] (A1i) to (A11);
      \draw[->] (B1i) to (P1);
    \end{tikzeq*}
  where the bullets stand for the pushouts above.
  The conclusion we need to obtain amounts to the composite of
  the two squares in the front being a Reedy cofibration when seen as a morphism
  from left to right.
  The right square is a Reedy cofibration since
  $c\:\!\c$ is a good subcategory of $\c$ and
  so is the left one since it is a pushout of the back square
  which is a Reedy cofibration by the inductive hypothesis. \qedhere
  \end{enumerate}
\end{proof}

\begin{Lemma}\label{Reedy-levelwise}
  The inclusion $\mathrm{N} w(\c^{[k]}_\mathrm{R}) \to \mathrm{N} w(\c^{[k]})$
  is a weak homotopy equivalence.
\end{Lemma}

\begin{proof}
  Functorial factorization induces a functor in the opposite direction
  as well as natural weak equivalences
  connecting both composites with identities.
\end{proof}

\begin{proof}[Proof of \cref{cC-C}]
  Recall that we want to show that $\mathrm{N} w((c\:\!\c)^{[k]}) \to \mathrm{N} w(\c^{[k]})$ is
  a weak equivalence for all $k$.
  In the diagram
  \begin{tikzeq*}
    \matrix[diagram]
    {
      & |(wcR)| \mathrm{N} wc\:\!(\c^{[k]}_\mathrm{R})
      & |(wR)|  \mathrm{N} w(\c^{[k]}_\mathrm{R}) \\
        |(w-c)| \mathrm{N} w((c\:\!\c)^{[k]})
      & |(wc)|  \mathrm{N} wc\:\!(\c^{[k]})
      & |(w)|   \mathrm{N} w(\c^{[k]}) \\
    };

    \draw[->] (wcR) to node[above] {\ding{172}} (wR);
    \draw[->] (wc)  to node[below] {\ding{173}} (w);
    \draw[->] (w-c) to (wc);

    \draw[->] (wcR) to node[above left] {\ding{174}} (w-c);
    \draw[->] (wcR) to (wc);
    \draw[->] (wR)  to node[right] {\ding{175}} (w);
  \end{tikzeq*}
  the indicated maps are weak equivalences.
  The map \ding{172} is a weak equivalence by \cref{W-diagonal} applied to
  $\c^{[k]}_\mathrm{R}$ with itself as a good subcategory and
  so is \ding{173} by the same argument applied to $\c^{[k]}$.
  The map \ding{174} is a weak equivalence by \cref{W-diagonal} applied to
  $\c^{[k]}_\mathrm{R}$ with the good subcategory of levelwise cofibrations,
  which is indeed good by \cref{levelwise-good}.
  Finally, \ding{175} is a weak equivalence by \cref{Reedy-levelwise}.
  Hence by 2-out-of-3, the bottom composite is also a weak equivalence
  as required.
\end{proof}

