	\includegraphics[clip = true, trim = 0 0 0 0, width = \linewidth]{figures/87A_Halpha_smooth.pdf}
	\caption{The full posterior probabilty distribution for the smooth, 5-dimensional model of the SN~1987A H$\alpha$ line at 714\,d as described in Section \ref{sscn_87A_results} (model B).  The adopted priors for this model are presented in Table \ref{tb_synthetic_profiles}. The estimated best-fit values from the manual fitting of B16 are marked by the orange cross-hairs. The contours of the 2D distributions represent $0.5\sigma$, $1.0 \sigma$, $1.5 \sigma$ and $2.0 \sigma$ and the dashed, black vertical lines represent the 16$^{\rm th}$, 50$^{\rm th}$ and 84$^{\rm th}$ quantiles for the 1D marginalised probability distributions. }
	\label{fig_87a_smooth}
