	\end{center}
\end{figure}

Further using the swampland distance conjecture (\ref{e1}), we find in a unit of the Planck mass that the condition $|\Delta \chi|\lesssim {\cal O}(1)$ is satisfied for the model we are considering here. Hence using Eq.(\ref{rat}) and the relation $\Delta U=\Big(U_{\chi}/U\Big)\Delta\chi$ with $U_{\chi}\equiv \partial U/\partial\chi$, we can write
\begin{eqnarray}
\frac{\Delta\chi}{M_{P}} = \frac{4\sqrt{6} (1+ 2 \gamma)}{16 \gamma^2+16 \gamma +\sqrt{6}^2 (1-n_{s})}\frac{\Delta U}{U}\lesssim \Delta \sim 1. \label{delU0}
\end{eqnarray}
Therefore, we obtain in terms of $\alpha$:
\begin{eqnarray}
\Delta U\lesssim \frac{4 \alpha ^2-4 \alpha -3 (1-2 \alpha )^2 n_{s}+3}{2 \sqrt{6} (1-2 \alpha)}U. \label{delU}
\end{eqnarray}
