(p, p)^{7}\textmd{Li},~~~~~~~Q=~0.000 \textmd{MeV}, ~~~~~~E_{th}=0.000 \textmd{MeV}\\
(p, \alpha)\alpha, ~~~~~~~~Q=+17.348 \textmd{MeV}, ~~~~E_{th}=0.000 \textmd{MeV}\\
(p, ^3\textmd{He})^{5}\textmd{He}, ~~~Q=-4.125 \textmd{MeV}, ~~~~~E_{th}=4.7175 \textmd{MeV}\\
(p, d)^{6}\textmd{Li}, ~~~~~~~Q=-5.025 \textmd{MeV}, ~~~~~E_{th}=5.7468 \textmd{MeV}\\
(p, t)^{5}\textmd{Li}, ~~~~~~~Q=-4.434 \textmd{MeV}, ~~~~~E_{th}=5.0709 \textmd{MeV}\\
(p, 2n)^{6}\textmd{Be}, ~~~~Q=-12.320 \textmd{MeV}, ~~~~E_{th}=14.0897 \textmd{MeV}\\
(p, np)^{6}\textmd{Li}, ~~~~~~Q=-7.249 \textmd{MeV}, ~~~~E_{th}=8.2903 \textmd{MeV}\\
(p, pn)^{6}\textmd{Li}, ~~~~~~Q=-7.249 \textmd{MeV}, ~~~~E_{th}=8.2903 \textmd{MeV}\\
