(p, 2p)^{6}\textmd{He}, ~~~~~~Q=-9.974 \textmd{MeV}, ~~~~E_{th}=11.4067 \textmd{MeV}\\
(p, pt)^{4}\textmd{He}, ~~~~~~Q=-2.467 \textmd{MeV}, ~~~~E_{th}=2.8214 \textmd{MeV}\\
(p, tp)^{4}\textmd{He}, ~~~~~~Q=-2.467 \textmd{MeV}, ~~~~E_{th}=2.8214 \textmd{MeV}\\
(p, pd)^{5}\textmd{He}, ~~~~~~Q=-9.619 \textmd{MeV}, ~~~E_{th}=11.0007 \textmd{MeV}\\
