p+ ^{7}\textmd{Li}^* ~~(k_1=gs, 1, 2, ..., 10),\\
\alpha+{\alpha}^* ~~(k_1=gs, 1, 2, ..., 14),\\
^3\textmd{He}+ ^{5}\textmd{He}^* ~~(k_1=gs, 1),\\
d+ ^6\textmd{Li}^* ~~(k_1=gs, 1, 2, ..., 5),\\
