    {\centering


    \includegraphics[width=0.9\columnwidth]{figure1.eps}
    \caption{Enhanced experimental image (enlarged dots, false color) with zoomed inset.  The field of view is 32.8mm/1024 pixels square.  Number density $n_{1,2}$ and specific pressure $p_{1,2}$ show the downstream and upstream regions (subscript 1/2).}
    \label{fig:image}
