The horizon of the  black hole $y_{+}$  and the boundary of the background can be  considered as potential wells.  So we can perform
Bohr-Sommerfeld analysis for the quantization.
Then we have the following condition
\begin{equation}\label{BSconstr}
\left(n + \frac{1}{2}\right)\pi = \int^{\xi_{2}}_{\xi_{1}}d\xi \sqrt{E^2 - \left(\frac{w}{\alpha'}\right)^{2} g(\xi)^{2}}, 
\end{equation}
with the turning point $\xi_{1,2}$. 

In terms of the holographic radial coordinate $y$ (\ref{BSconstr}) takes the form
\begin{eqnarray}\label{EInt}
\left(n+\frac{1}{2}\right)\pi& =& \int^{y_{1}}_{y_{+}}\frac{E dy}{f(y)\sqrt{1+\frac{2Ma^2}{\Xi^3 y^4}}} \sqrt{1-  \frac{w^2}{\alpha'^{2}E^{2}}f(y)} \nonumber \\
 &=& E\int^{y_{1}}_{y_{+}}dy\left(\frac{1}{f(y)\sqrt{1+\frac{2Ma^{2}}{\Xi^{3}y^{4}}}} -\frac{1-\sqrt{1-\frac{1}{B^2}y^{2}f(y)}}{f(y)\sqrt{1+\frac{2Ma^2}{\Xi^3 y^4}}} \right),
\end{eqnarray}
where $B = \frac{E\alpha'}{w}$ and the function $f$ is defined in (\ref{blackFfunc}).
We are not able to calculate integrals (\ref{EInt}) exactly. However, supposing that the rotational parameter $a$ is small  we can expand in series (\ref{EInt}), then we get
\begin{eqnarray}
&&\left(n+\frac{1}{2}\right)\pi= E\int^{\tilde{y}_{1}}_{y_{H}}dy\left(\frac{ 1}{1-\frac{2M}{y^2} + \ell^2 y^2} - \frac{1- \sqrt{1-\frac{1}{B^{2}}y^2(1+\ell^2y^2 -\frac{2M}{y^2})}}{1-\frac{2M}{y^2} + \ell^2 y^2}\right)+\label{first term integral}\\
&& \int^{\tilde{y}_{1}}_{y_{H}}dy\frac{M \sqrt{1-\frac{y^2}{B^2}h(y)} (y^2h(y)(2y^2 -3B^2) - 2B^{2}(2M -3y^4 \ell^2) -y^2(2M +\ell^2 +\ell^4 y^6))}{y^6 h(y)^2 (B^2-y^2h(y))}a^{2}, \nonumber
\end{eqnarray}
where we define
\begin{equation}\label{AdSSchwF}
h(y) = 1-\frac{2M}{y^2} + \ell^2 y^2,
\end{equation}
which is nothing but the  blackenning function of the AdS-Schwarzschild black hole. The horizon $y_{H}$ is defined as  a root of the equation  $h(y)= 0$, i.e.
\begin{equation}\label{AdSSchwY}
 y_{H} = \frac{1}{\ell} \sqrt{\frac{1}{2}\Bigr(1 + \sqrt{1+8M\ell^2}\Bigr)}.
\end{equation}
 %
It is worth to note that the quantities $h(y)$ (\ref{AdSSchwF}) and $y_{H}$ (\ref{AdSSchwY})  related to the non-rotating  AdS black hole appear due to expanding around a small rotational parameter $a$.  


Integrating the first term in the integral \eqref{first term integral} we get
\begin{eqnarray}\label{EnSpectBS}
E\int^{\tilde{y}_{1}}_{y_{H}}dy\frac{ 1}{1-\frac{2M}{y^2} + \ell^2 y^2} = -E \frac{\sqrt{\sqrt{1+ 8\ell^2 M}-1}\tanh^{-1}\left(\frac{\sqrt{2}\ell y}{\sqrt{\sqrt{1+8\ell^2 M}-1}}\right)}{\ell\sqrt{2}\sqrt{1+8\ell^2 M}}\Big|^{\tilde{y}_{1}}_{y_{H}}\\
+  E\frac{2\sqrt{M} \tan^{-1}\left(\frac{\sqrt{2}\ell y}{\sqrt{\sqrt{1+8\ell^2 M}+1}}\right)}{\sqrt{1+8\ell^2 M}\sqrt{\sqrt{1+8\ell^2 M}-1}}\Big|^{\tilde{y}_{1}}_{y_{H}}.\nonumber
\end{eqnarray}
In the case of large energies $B\cdot \ell \gg 1$ eq.(\ref{EnSpectBS}) can be approximated as follows
\begin{equation}\label{EnSpectBSapp}
\int^{\tilde{y}_{1}}_{y_{H}}dy\frac{ 1}{1-\frac{2M}{y^2} + \ell^2 y^2} \approx \frac{\pi}{2}\sqrt{\frac{1}{\sqrt{2 M}\ell^3}} -\sqrt{\frac{1}{B\ell^{3}}}.
\end{equation}
The second integral \eqref{first term integral} can be calculated easily in terms of a new variable $y = r\sqrt{B/\ell}$
\begin{eqnarray}
\int^{y_{1}}_{y_{H}} dy\frac{1- \sqrt{1- \frac{1}{B^2}\left(y^2 + \ell^2 y^4 - 2M\right)}}{1+ y^2 \ell^2 - \frac{2M}{y^2}} &\rightarrow& \sqrt{\frac{1}{\ell^3B}}\int^{1}_{0}\frac{dr}{r^2}(1 -\sqrt{1-r^4}) \nonumber\\\label{EnSpectBSapp2}
&=&\sqrt{\frac{1}{\ell^3 B}}\left(-1+\frac{(2\pi)^{3/2}}{\Gamma(\frac{1}{4})^2}\right).
\end{eqnarray}
Applying the same procedure to the third integral, we get
\begin{eqnarray}
 &&\int^{y_{1}}_{y_{H}}dy\frac{M \sqrt{1-\frac{y^2}{B^2}h} (y^2 h(2y^2 -3B^2) - 2B^{2}(2M -3y^4 \ell^2) -y^2(2M +\ell^2 +\ell^4 y^6))}{y^6 h^2 (B^2-y^2h )}a^{2}\nonumber\\ &\rightarrow&
-\int^{1}_{0}dr \frac{\ell^{1/2}M(r^4-3)}{B^{3/2}r^{6}\sqrt{1- r^{4}}}a^{2} = -\frac{M\ell^{1/2}}{B^{3/2}}\left(\frac{3\sqrt{1-r^{4}}}{5r^{5}}+ \frac{4}{5r}{{\mkern 1mu} _2}{F_1}\left(-\frac{1}{4},\frac{1}{2}, \frac{3}{4},r^{4}\right)\right)a^{2}\Big|^{1}_{0} \nonumber \\\label{EnSpectBSapp3}
&&= -\frac{4M\sqrt{\pi}\ell^{1/2}\Gamma[\frac{3}{4}]}{5B^{3/2}\Gamma[\frac{1}{4}]}a^{2}+ \frac{7M\ell^{1/2}}{B^{3/2}}\frac{1}{\epsilon^{5}}a^{2}.
\end{eqnarray}
Combining together (\ref{EnSpectBSapp}), (\ref{EnSpectBSapp2}), (\ref{EnSpectBSapp3}) we get for Bohr-Sommerfeld quantisation condition (\ref{EInt})
\begin{equation}\label{EnwBS}
(n + \frac{1}{2})\pi \approx \frac{1}{\ell^{3/2}} \left(\frac{\pi}{2}\frac{E}{(\sqrt{2M})^{1/2}} - \frac{(2\pi)^{3/2}}{\Gamma(\frac{1}{4})^2} \frac{(w E)^{1/2}}{ (\alpha')^{1/2}} -\frac{4Mw^{3/2}\sqrt{\pi}\Gamma[\frac{3}{4}]}{5E^{1/2}\alpha'^{3/2}\Gamma[\frac{1}{4}]}a^{2}\right).
\end{equation}
In (\ref{EnwBS}) we can recognize the result for the energy from \cite{Alishahiha:2002fi} if one sends $a$ to $0$.

\subsection{WKB approximation}\label{Sect42}
\subsubsection{Derivation of the Hamiltonian}

As in the previous section the string dynamics is governed by the Nambu-Goto action (\ref{SNGg}) with the induced metric (\ref{indm-h}).
The first ingredient towards finding the spectrum is to make a pullback of the line element of the metric of 5d Kerr-AdS background \eqref{GLKA} to the subspace, where string dynamics takes place. 
In this section one can consider more general ansatz than \eqref{ansatz} and \eqref{equatorial}, such as
\begin{align}\label{new ansatz}
	&\Theta\equiv\,\xi_1=\xi_1(\tau)\,,\, y\equiv\,\xi_2=\xi_2(\tau)\,, \\
	&T\equiv\,X_0=x_0(\tau)+m_0\sigma,\qquad  x_0(\tau)=\kappa\tau, \qquad m_0=0\,,\\
	&\Phi\equiv\,X_1=m_1\sigma+x_1(\tau)\,, \quad \Psi\equiv\,X_2=m_2\sigma+x_2(\tau)\,.
\end{align} 
For convenience, we use the following notations of the Kerr-AdS metric \eqref{GLKA} 
\begin{multline}\label{pulsMetric}
	ds^2= G_{\Theta\Theta}d\Theta^2 + G_{yy}dy^2 +\\
	+G_{TT} dT^2+ 2G_{T\Phi}dTd\Phi  +2G_{T\Psi}dTd\Psi+ G_{\Phi\Phi}d\Phi^2 +G_{\Psi\Psi}d\Psi^2 + 2G_{\Phi\Psi}d\Phi\Psi=\\
	=\sum\limits_{i,j=1}^2 g_{ij}d\xi_i d\xi_j\,
	+\,\sum\limits_{k,p=0}^2 \hat{G}_{kp} dX_k dX_p \,,
\end{multline}
where the following quantities have been defined  
\begin{equation} 
	\left( g_{ij} \right) =
	\left(\begin{matrix}
		G_{\Theta\Theta}& 0 \\
		0 & G_{yy}
	\end{matrix}\right)\,,\qquad i,j=1,2\,,
\end{equation}
\begin{equation}
	\left(\hat{G}_{k\textcolor{violet}{h}}\right)=\left(\begin{matrix}
		G_{TT} & G_{T\Phi} & G_{T\Psi}\\
		G_{T\Phi}& G_{\Phi\Phi} & G_{\Phi\Psi}\\
		G_{T\Psi} & G_{\Phi\Psi} & G_{\Psi\Psi}
	\end{matrix}\right)\,, \qquad k,p=0,1,2\,,
\end{equation}
and the submatrix 
\begin{equation}
	\left( \hat{g}_{kp} \right)=\left(\begin{matrix}
		G_{\Phi\Phi} & G_{\Phi\Psi}\\
		G_{\Phi\Psi} & G_{\Psi\Psi}
	\end{matrix}\right)\,, \qquad k,p=1,2\,.
\end{equation}
For the inverse of $\left( \hat{g}_{kp} \right)$ matrix, we find
\begin{equation}
	\left( \hat{g}^{kp} \right)=\left(\begin{matrix}
		\frac{y^4\Xi^3+2a^2 M \cos^2\Theta}{y^2 \sin^2\Theta\,(y^4\Xi^3+2a^2 M )} & -\,\frac{2a^2 M}{y^2\,(y^4\Xi^3+2a^2 M )}\\
		-\,\frac{2a^2 M}{y^2\,(y^4\Xi^3+2a^2 M )}& \frac{y^4\Xi^3+2a^2 M \sin^2\Theta}{y^2 \cos^2\Theta\,(y^4\Xi^3+2a^2 M )} 
	\end{matrix}\right)\,, \qquad k,p=1,2\,.
\end{equation}

The components of the induced metric on the worldsheet: 
\begin{multline}\label{ws-metric}
	ds^2 _{ws}=  \left(\sum\limits_{i,j=1}^2 g_{ij}\,\dot{\xi}_i\dot{\xi}_j + \sum\limits_{k,p=0}^2\hat{G}_{kp}\,\dot{x}_k\dot{x}_p \right) d\tau^2 + \left(\sum\limits_{k,p=0}^2\hat{G}_{kp}\,m_k m_p\right)\, d\sigma^2 +\\
	+2\left(\sum\limits_{k,p=0}^2\hat{G}_{kp}\, m_k\dot{x}_p\right)\, d\tau d\sigma\,.
\end{multline}
The Nambu-Goto action \eqref{SNGg} with (\ref{indm-h}) becomes
\begin{multline} \label{NG-ws}
	S_{NG}= -\,\dfrac{1}{\alpha^\prime }\int\, d\tau\,\sqrt{ \left(\sum\limits_{k,p=1}^2\hat{G}_{kp}\, m_k\dot{x}_p  + \sum\limits_{k=1}^2 \hat{G}_{k0}\, m_k\, \kappa \right)^2+\,\,}\\ 
	\overline{\,\,-  \left\|\vec{m}\right\|^2\,\left(\sum\limits_{i,j=1}^2 g_{ij}\,\dot{\xi}_i\dot{\xi}_j + \sum\limits_{k,p=1}^2\hat{g}_{kp}\,\dot{x}_k\dot{x}_p + \hat{G}_{00}\,\kappa^2 +2\, \sum\limits_{k=1}^2\hat{G}_{0k}\,\kappa\dot{x}_k    \right)  \,\,}   \,,
\end{multline}
where $1/\alpha ^ \prime =\sqrt{\lambda}$ is the 't Hooft coupling constant and 
\begin{align}\label{A2}
	\left\|\vec{m}\right\|^2 =
	\sum\limits_{k,h=0} ^2 \hat{G}_{kh} m_k m_h =\sum\limits_{k,h=1} ^2 \hat{G}_{kh}(\xi_1,\xi_2) m_k m_h\equiv\sum\limits_{k,h=1} ^2 \hat{g}_{kh}(\xi_1,\xi_2) m_k m_h\,>\,0\,.
\end{align}
The problem reduces again to the dynamics of an effective point-particle with Lagrangian
\begin{multline} \label{NG-ws}
	L_{eff}= -\,\sqrt{\lambda}\,\sqrt{ \left(\sum\limits_{k,p=1}^2\hat{g}_{kp}\, m_k\dot{x}_p  + \sum\limits_{k=1}^2 \hat{G}_{k0}\, m_k\, \kappa \right)^2  -  \left\|\vec{m}\right\|^2\,\left(\sum\limits_{i,j=1}^2 g_{ij}\,\dot{\xi}_i\dot{\xi}_j + \,\,\right. }\\
	\overline{\left. \,\,+\sum\limits_{k,p=1}^2\hat{g}_{kp}\,\dot{x}_k\dot{x}_p + \hat{G}_{00}\,\kappa^2 +2\, \sum\limits_{k=1}^2\hat{G}_{0k}\,\kappa\dot{x}_k    \right)  \,\, }   \,.
\end{multline}
For convenience we will use the shorthand notation
\begin{multline} 
	\sqrt{ \left(\sum\limits_{k,p=1}^2\hat{g}_{kp}\, m_k\dot{x}_p  + \sum\limits_{k=1}^2 \hat{G}_{k0}\, m_k\, \kappa \right)^2  -  \left\|\vec{m}\right\|^2\,\left(\sum\limits_{i,j=1}^2 g_{ij}\,\dot{\xi}_i\dot{\xi}_j + \,\,\right. }\\
	\overline{\left. \,\,+\sum\limits_{k,p=1}^2\hat{g}_{kp}\,\dot{x}_k\dot{x}_p + \hat{G}_{00}\,\kappa^2 +2\, \sum\limits_{k=1}^2\hat{G}_{0k}\,\kappa\dot{x}_k    \right)  \,\, }\,\equiv\, \sqrt{......\,\,}   \,.
\end{multline}
As before, it is useful to consider the  Hamiltonian formulation of the problem. To this end, we have to calculate the canonical momenta
\begin{align}\label{momenta}
	\Pi_{\xi_i}&=\frac{\partial L_{eff}}{\partial \dot{\xi}_i} =\sqrt{\lambda} \,\dfrac{ \left\|\vec{m}\right\|^2 g_{ij}\,\dot{\xi}_j } {\sqrt{......\,\,}} \,, \\
	\Pi_{x_p}&=\frac{\partial L_{eff}}{\partial \dot{x}_p} =\sqrt{\lambda}\, \dfrac{ \,\left\|\vec{m}\right\|^2 \hat{g}_{pq}\, \dot{x}_q - (\hat{g}_{kq}\, m_k\dot{x}_q)\, \hat{g}_{pq}\, m_q +\left\|\vec{m}\right\|^2 \hat{G}_{p0}\,\kappa -(\hat{G}_{k0}\, m_k\kappa)\, \hat{g}_{pq}\, m_q\,}
	{\sqrt{......\,\,}}\,,
\end{align}
which also implies the constraint 
\begin{equation}\label{constraintPi}
	\sum\limits_{p=1}^2m_p\, \Pi_{x_p}=0.
\end{equation}
 Applying a Legendre transformation, it is straightforward to find the (square of) the pulsating string Hamiltonian
 %
 %
\begin{multline}\label{Ham^2}
	H^2= \kappa^2 \, \left(\sum\limits_{l,s=1}^2 \hat{G}_{0l}\,\hat{g}^{ls}\, \Pi_{x_s}\right)^2 +\\
	- \kappa^2 \,\left( \hat{G}_{00} +  \sum\limits_{l,s=1}^2 \hat{G}_{0l}\,\hat{g}^{ls}\, \hat{G}_{s0} \right) \,\left\lbrace          \sum\limits_{i,j=1}^2   \Pi_{\xi_i}\,g^{ij} \,\Pi_{\xi_j}   +   \sum\limits_{i,j=1}^2   \Pi_{x_i}\,\hat{g}^{ij} \,\Pi_{x_j} +\lambda\,\left\|\vec{m}\right\|^2 \right\rbrace \,.
\end{multline}
The explicit expressions for the terms in the brackets are
\begin{equation}
	\sum\limits_{l,s=1}^2 \hat{G}_{0l}\,\hat{g}^{ls}\, \Pi_{x_s}\,=\,-\, h_2(y)\,\left(  \Pi_{x_1}+\Pi_{x_2} \right) 
\end{equation}
and
\begin{equation}
	\hat{G}_{00} +  \sum\limits_{l,s=1}^2 \hat{G}_{0l}\,\hat{g}^{ls}\, \hat{G}_{s0} \,=\,-\,\frac{y^2 \Xi^3 -2aM\,h_1(y)\,h_2(y) }{h_1(y)\,y^2 \Xi^3}\,\equiv\,-\,K^2(y)\,,
\end{equation}\,
where
\begin{equation}
	h_1(y)\,=\,\frac{y^{2}\Xi^{3}}{-2M + y^{2}(1+\ell^{2}y^{2})\Xi^{3}}\,, \qquad h_2(y)\,=\,\frac{2aM}{2a^{2}M + y^{4}\Xi^3}\,.
\end{equation}
The expression of $H^2$ can be conveniently written 
\begin{equation}\label{Ham^2 2}
	\frac{H^2}{\kappa^2}\,=\,K^2(y)\left\lbrace   \sum\limits_{i,j=1}^2   \Pi_{\xi_i}\,g^{ij} \,\Pi_{\xi_j} + \sum\limits_{i,j=1}^2   \Pi_{x_i}\,\left[  \frac{h_2 ^2 (y)}{K^2(y)}\,\hat{\delta}^{ij} +\hat{g}^{ij} \right] \,\Pi_{x_j} +\lambda\,\left\|\vec{m}\right\|^2     \right\rbrace \,,
\end{equation}
where
\begin{equation}
\left(\hat{\delta}^{ij} \right)\,=\,\left(\begin{matrix}
	1& 1 \\
	1& 1
\end{matrix}\right)\,,\,\, i,j=1,2 	\,.
\end{equation}
It should be noted here that the above Hamiltonian \eqref{Ham^2} can be considered as the effective Hamiltonian of an effective point-particle on the Kerr-AdS background. The last term 
\begin{equation}
	-\lambda\,\kappa^2\,\left\|\vec{m}\right\|^2 \,\left( \hat{G}_{00} +  \sum\limits_{l,s=1}^2 \hat{G}_{0l}\,\hat{g}^{ls}\, \hat{G}_{s0} \right)\,\equiv\, \lambda\,\kappa^2\,\left\|\vec{m}\right\|^2 \,K^2(y)\,\equiv\,\lambda\,U(\Theta,\,y)\,,
\end{equation}
serves as an effective potential, which encodes the relevant dynamics of the strings.\\
In the context of the holographic correspondence, the potential is very small comparing to the kinetic part. Therefore, we can calculate quantum corrections to the energy by making use of the perturbation theory. 

\subsubsection{Laplace-Beltrami operator and wave function}
The standard Laplace-Beltrami operator in global coordinates for 5d Kerr-AdS \eqref{GLKA} is
\begin{multline}
	\bigtriangleup^{(5)}_{Kerr-AdS}\,=\,G^{TT}\frac{\partial^2}{\partial T^2}+2\,G^{T\Phi(\Psi)}\frac{\partial}{\partial T}\left(\frac{\partial}{\partial \Phi}+\frac{\partial}{\partial \Psi} \right) +G^{\Phi\Phi}\frac{\partial^2}{\partial \Phi^2}+2\,G^{\Phi\Psi}\frac{\partial^2}{\partial \Phi\partial\Psi}+G^{\Psi\Psi}\frac{\partial^2}{\partial \Psi^2}+\\
	+\frac{1}{\sqrt{-\det G}}\,\frac{\partial}{\partial \Theta}\left(\sqrt{-\det G\,}\,G^{\Theta\Theta}\,\frac{\partial}{\partial \Theta} \right)+ +\frac{1}{\sqrt{-\det G}}\,\frac{\partial}{\partial y}\left(\sqrt{-\det G\,}\,G^{yy}\,\frac{\partial}{\partial y} \right)\,.
\end{multline}
In the notations of Appendix A (see \eqref{inverseG} and \eqref{detG}), we have
\begin{multline}\label{Laplace}
	\bigtriangleup^{(5)}_{Kerr-AdS}\,=\,-h_1(y)\,\frac{\partial^2}{\partial T^2}-2\,h_1(y)\,h_2(y)\,\frac{\partial}{\partial T}\left(\frac{\partial}{\partial \Phi}+\frac{\partial}{\partial \Psi} \right) +\\
	-\,\frac{1}{y^2}a\,h_2(y)\,\left(\frac{\partial}{\partial \Phi}+\frac{\partial}{\partial \Psi} \right)^2 +  \frac{1}{y^2\sin^2\Theta} \,\frac{\partial^2}{\partial \Phi^2}+\frac{1}{y^2\cos^2\Theta} \,\frac{\partial^2}{\partial \Psi^2}+\\
	+\frac{1}{y^2}\,\frac{1}{\sin(2\Theta)}\frac{\partial}{\partial \Theta}\left(\sin(2\Theta)\,\frac{\partial}{\partial \Theta} \right)+ \frac{1}{\sqrt{h(y)\,}}\,\frac{\partial}{\partial y}\left(\sqrt{h(y)\,}\,G^{yy}\,\frac{\partial}{\partial y} \right)\,,
\end{multline}
where 
\begin{equation}
h_1(y)\,=\,\frac{y^{2}\Xi^{3}}{-2M + y^{2}(1+\ell^{2}y^{2})\Xi^{3}}\,, \,\,h_2(y)\,=\,\frac{2aM}{2a^{2}M + y^{4}\Xi^3}.
\end{equation}
To obtain the wave function, we have to solve the equation
\begin{equation}\label{kernel}
	\bigtriangleup^{(5)}_{Kerr-AdS}\,F(T,\,\Theta,\,y,\,\Phi,\,\Psi)\,=\,0\,,
\end{equation}
using separation of variables
\begin{equation}\label{separate}
	F(T,\,\Theta,\,y,\,\Phi,\,\Psi)\,=\,e^{-i E\, T}\, e^{i n_1\Phi}\, e^{i n_2\Psi}\, f(\Theta,\,y)\,,\qquad n_1,\,n_2\, \in\mathbb{Z}\,.
\end{equation}
Substituting \eqref{separate} in to the equation \eqref{kernel}, we find the following partial differential equation for $\, f(\Theta,\,y)\,$
\begin{multline}\label{laplaceEquation}
	E^2\,h_1(y)\,f-2h_1(y)h_2(y)\,E\,(n_1+n_2)\,f+\frac{1}{y^2}\,ah_2(y)\,(n_1+n_2)^2\,f+\\
	-\frac{1}{y^2}\,\left(  \frac{n_1^2}{\sin^2\Theta} +\frac{n_2^2}{\cos^2\Theta}\right) \,f        +\frac{1}{y^2}\,\frac{1}{\sin(2\Theta)}\frac{\partial}{\partial \Theta}\left(\sin(2\Theta)\,\frac{\partial f}{\partial \Theta} \right)+\\
	+ \frac{1}{\sqrt{h(y)\,}}\,\frac{\partial}{\partial y}\left(\sqrt{h(y)\,}\,G^{yy}\,\frac{\partial f}{\partial y} \right) \,=\,0\,.
\end{multline}
We can further separate the variables defining $\, f(\Theta,\,y)\,=\,f(\Theta)\,Y(y)\,$.
\subsubsection{Solving the Schr\"odinger equation on the reduced subspace $y=const$}

In the subsection (3.2), we obtain an explicit pulsating solution \eqref{puls solution} in the case for the string winding numbers satisfy $\,m_1^2=m_2^2\equiv\,m^2\,$ and  $\,y=const\neq\,0\,$.\\
In this case, taking into account \eqref{constraintPi}, for the first term of the Hamiltonian \eqref{Ham^2}, we have
\begin{equation}
	\left( \sum\limits_{l,s=1}^2 \hat{G}_{0l}\,\hat{g}^{ls}\, \Pi_{x_s}\right) ^2\,=\,h^2_2(y)\,\left(  \Pi_{x_1}+\Pi_{x_2} \right)^2\,=\,0\,. 
\end{equation}
Moreover, all functions of $y$ are constants and 
\begin{equation}
	\hat{G}_{00} +  \sum\limits_{l,s=1}^2 \hat{G}_{0l}\,\hat{g}^{ls}\, \hat{G}_{s0} \,=\,-\frac{y^2 \Xi^3 -2aM\,h_1(y)\,h_2(y) }{h_1(y)\,y^2 \Xi^3}\,\equiv\,-K^2 =const\,,
\end{equation}
where
\begin{equation}
	h_1\,=\,\frac{y^{2}\Xi^{3}}{-2M + y^{2}(1+\ell^{2}y^{2})\Xi^{3}}=const\,, \qquad h_2\,=\,\frac{2aM}{2a^{2}M + y^{4}\Xi^3}=const\,.
\end{equation}
Therefore, the square of the Hamiltonian \eqref{Ham^2}  has the form 
\begin{equation}\label{Ham3}
	H^2=\,\kappa^2\,K^2\,\left\lbrace   \Pi_{\Theta}\,g^{\Theta\Theta} \,\Pi_{\Theta}   +   \sum\limits_{i,j=1}^2   \Pi_{x_i}\,\hat{g}^{ij} \,\Pi_{x_j} +\lambda\,\left\|\vec{m}\right\|^2 \right\rbrace \,.
\end{equation}
We observe that $H^2$ looks like a point-particle Hamiltonian, which seems to be characteristic feature for pulsating strings in holography. The last term, 
\begin{equation}\label{potentialTheta}
	\lambda\,\kappa^2\,K^2\left\|\vec{m}\right\|^2 \,\equiv\,\lambda\,U(\Theta)
\end{equation}
serves as an effective potential, which encodes the relevant dynamics of the strings.\\
In the context of Holographic correspondence, the potential is very small compared to the kinetic part. Therefore, we can calculate quantum corrections to the energy using perturbation theory.
\paragraph{Wave functions}
The kinetic term of the Hamiltonian \eqref{Ham3} can be considered as a three dimensional Laplace-Beltrami operator of the Kerr-AdS subspace with $y=const$
\begin{equation}
	\vec{P}^2\,=\,\left\lbrace   \Pi_{\Theta}\,g^{\Theta\Theta} \,\Pi_{\Theta}   +   \sum\limits_{i,j=1}^2   \Pi_{x_i}\,\hat{g}^{ij} \,\Pi_{x_j} \right\rbrace \,\,\longrightarrow \,\, \bigtriangleup^{(3)}_{Kerr-AdS}\,,
\end{equation}
which defines the eigen-functions of the Hamiltonian, satisfying the following Schr\"odinger equation
\begin{equation}\label{Schro}
	\bigtriangleup^{(3)}_{Kerr-AdS}\,F\,=\,-\,\frac{E^2}{\kappa^2\,K^2}\,F\,.
\end{equation}
Comparing it with the equation \eqref{laplaceEquation}, we notice that it corresponds to taking $n_1=-n_2\equiv\,n\,,\,\, n\in\mathbb{Z}\,$. Thus, we can write the equation \eqref{Schro} in the form
	\footnote{In this case, the solution of the below equation can be written directly in terms of Shifted Legendre polynomials, but below we will follow the more general procedure.}
\begin{equation}\label{equation}
	\left\lbrace \frac{1}{y^2}\,\frac{1}{\sin\Theta\,\cos\Theta}\,\frac{\partial}{\partial\Theta}\left( \sin\Theta\,\cos\Theta\,\frac{\partial}{\partial\Theta}\right) -\frac{n^2}{y^2}\,\frac{1}{\sin^2\Theta\,\cos^2\Theta}+\frac{E^2}{\kappa^2\,K^2}\right\rbrace \,F(\Theta)\,=\,0\,.
\end{equation}
 Since in this case the potential $\,\lambda\,U$ is a constant, the corresponding Schr\"odinger equation can be easily solved. The eigenvalue problem for the Hamilton (square of) operator is exactly solvable.\\
The last term in the equation \eqref{equation} is shifted with a constant and can be written as
\begin{equation}\label{Legendre}
	\left\lbrace \frac{1}{\sin\theta}\,\frac{\partial}{\partial\theta}\left( \sin\theta\,\frac{\partial}{\partial\theta}\right) -\frac{n^2}{\sin^2\theta}+\frac{y^2\,(E_{full}^2 +\lambda\,U)}{4\,\kappa^2\,K^2}\right\rbrace \,F(\theta)\,=\,0\,,\qquad \theta\equiv\,2\Theta\,.
\end{equation}
As far as, we want square integrable eigenfunctions with a discrete spectrum, the solution of the above equation can be directly written in terms of Shifted Legendre polynomials
\begin{equation}
	F(\theta)\,\sim\, P_n ^k (\cos\theta)\,, \,\, -k\,\leq\,n\,\leq\,k\,,\,\,k\in\mathbb{N}\,.
\end{equation}
The discrete spectrum is determined by
\begin{equation}
	\frac{y^2\,(E_{full}^2 +\lambda\,U)}{4\,\kappa^2\,K^2}\,=\,k(k+1)\,.
\end{equation}
Below we will follow slightly more general procedure, which is also valid for non-constant potentials.\\
To this end it is convenient to define a new variable $z=\sin^2\Theta\,, \,\, 0\leq\,z\,\leq\,1\,$. Then the equation \eqref{equation} can be written as
\begin{equation}\label{eq_z}
	\left\lbrace  \frac{d^2}{dz^2} +\frac{(1-2z)}{z(1-z)} \,\frac{d}{dz} - \frac{N^2}{z^2(1-z)^2} + \frac{\hat{E}^2}{z(1-z)}  \right\rbrace \,F(z)\,=\,0\,,
\end{equation}  
where $\,N=\frac{n^2}{4}\,$ and $\,\hat{E}^2\,=\,\frac{y^2\,E^2}{\kappa^2\,K^2}\,$.\\
The general solution is the following linear combination
\begin{multline}
	F(z)=C_1\,z^N\,(1-z)^N\,{_2F_1}\left[   2N +\frac{1}{2}+\frac{1}{2}\,\sqrt{1+4\hat{E}^2}\,,\,   2N +\frac{1}{2}-\frac{1}{2}\,\sqrt{1+4\hat{E}^2}\,;\, 1+2N\,;\,z \right] + \\
	+C_2\,z^{-N}\,(1-z)^N\,{_2F_1}\left[  \frac{1}{2}+\frac{1}{2}\,\sqrt{1+4\hat{E}^2}\,,\,   \frac{1}{2}-\frac{1}{2}\,\sqrt{1+4\hat{E}^2}\,;\, 1-2N\,;\,z \right] \,.
\end{multline}
Since the second term is singular at zero, we set $\,C_2 =0\,$, and the solution satisfying the boundary conditions is 
\begin{equation}\label{solution}
	F(z)=C\,z^N\,(1-z)^N\,{_2F_1}\left[   2N +\frac{1}{2}+\frac{1}{2}\,\sqrt{1+4\hat{E}^2}\,,\,   2N +\frac{1}{2}-\frac{1}{2}\,\sqrt{1+4\hat{E}^2}\,;\, 1+2N\,;\,z \right]\,.
\end{equation}
In addition, we have to ensure that the solutions $F(\Theta)$ are square integrable with respect to the measure $\Theta$ (respectively $z$). The integrability condition leads to the following restriction on the parameters
\begin{equation}\label{quantE}
	2N +\frac{1}{2}-\frac{1}{2}\,\sqrt{1+4\hat{E}^2}\,=\,-k\,,\qquad k\in\mathbb{N}\,.
\end{equation}
This requirement imposes energy quantization:
\begin{equation}\label{E^2}
	E^2\,=\,\kappa^2\,\frac{K^2}{4y^2}\,\left[ (4N+1+k)^2 -1 \right].
\end{equation}
The condition \eqref{quantE}, converts the solution \eqref{solution} in terms of Jacobi ortogonal polynomials (in this case the solution of the equation can also be written directly in terms of Shifted Legendre polynomials)
\begin{equation}\label{Jacobi z}
	F(z)=\,C\,z^{\alpha/2}\,(1-z)^{\beta/2}\,\dfrac{k!\,\Gamma(\alpha+1)}{\Gamma(\alpha+1+k)}P^{(\alpha,\beta)}_{k}(1-2z)\,,\qquad k\in\mathbb{N}\,,
\end{equation}
where $ \,\alpha=\beta\,=\,2N\equiv\,\frac{n^2}{2} \,,\,\, n\in\mathbb{Z}\,$.
It is more convenient to work in terms of  $\,u \equiv\,1-2z\,,\,\,-1\leq\,u\,\leq\,1\,$
\begin{equation}\label{Jacobi u}
	F_{k,n}(u)=\,C\,\left(  \frac{1-u}{2} \right) ^{\alpha/2}\,\left(  \frac{1-u}{2} \right) ^{\alpha/2}\,\dfrac{k!\,\Gamma(\alpha+1)}{\Gamma(\alpha+1+k)}P^{(\alpha,\beta)}_{k}(u)\,,\,\,-1\leq\,u\,\leq\,1\,\,.
\end{equation}
We find the normalized with respect to the measure
\begin{equation}\label{measure}
	d\Omega =\,\sqrt{-\det G^{(4)}}\,d\Theta\,d\Phi\,d\Psi\,=\,-\,\sqrt{\frac{h_1\,h_2}{2 a M \Xi^3 \,y^2}}\,\,\frac{du}{4}\,d\Phi\,d\Psi
\end{equation}
 wave function to be
\begin{equation}\label{wave f}
	f_{k,n}(u)=\,\sqrt{\frac{(2\alpha+1+2k)\,k!\,\Gamma(2\alpha+1+k)}{2^{\alpha-1}\,
			\Gamma(\alpha+1+k)\,\Gamma(\alpha+1+k)}} \,(1-u)^{\alpha/2}\,(1+u)^{\alpha/2}P^{(\alpha,\alpha)}_{k}(u)\,.
\end{equation}
Then, the total free wave functions have the form
\begin{align}\label{tot wave f}
	f^{tot}_{k,n}(u,\,\Phi,\,\Psi)=\,&\sqrt{\frac{(2\alpha+1+2k)\,k!\,\Gamma(2\alpha+1+k)}{\,\omega(y)\,2^{\alpha-1}\,
			\Gamma(\alpha+1+k)\,\Gamma(\alpha+1+k)}}\,\times\nonumber\\
	&\times\,(1-u)^{\alpha/2}\,(1+u)^{\alpha/2}P^{(\alpha,\alpha)}_{k}(u)\,e^{in\Phi}\,e^{-in\Psi}\,.
\end{align}
The next step is to calculate perturbatively the corrections to the energy of the free ground states.

	\paragraph{Leading correction to the energy}

	Perurbatively, the first correction to the energy reads
	%
	\begin{equation}\label{delta-E}
		\delta E^2=\,\lambda\,\langle\,f^{tot}_{k,n}\,\vert\,U\,\vert\,f^{tot}_{k,n}\,\rangle
		=\lambda \int\limits_{\!\!\!\!\!-1}^1\!  \int\limits_0^{2\pi}\! \int\limits_0^{2\pi}\, \left| f^{tot}_{k,n}(u,\,\Phi,\,\Psi) \right|^2\,\, U(u,\,\Phi,\,\Psi)\,\, d\Omega(u,\, \Phi,\,\Psi) \,.
	\end{equation}
	%
	Let us remind the form of the potential function \eqref{potentialTheta}
	%
	\begin{equation}\label{potential}
		U(\Theta)\,=\,\kappa^2\,K^2\left\|\vec{m}\right\|^2 \,=\,\kappa^2\,K^2\,\sum\limits_{k,h=1} ^2 \hat{g}_{kh}(y,\,\Theta) m_k m_h\,.
	\end{equation}
	%
	Since for $\,y=const\,$, the value of $\,\left\|\vec{m}\right\|^2\,$ is also a constant, the potential is
	%
	\begin{equation}\label{potential costant}
		U\,=\,\kappa^2\,K^2 \,m^2\, \left( y^2 + \frac{2a^2 M}{y^2\Xi^3}\right)=const\,.
	\end{equation}
	%
	Using the scalar product \eqref{delta-E}, one can easily compute the first correction to the energy
	%
	\begin{equation}\label{delta-E value}
		\delta E^2=\,\lambda\,\langle\,f^{tot}_{k,n}\,\vert\,U\,\vert\,f^{tot}_{k,n}\,\rangle
		=\,\lambda\,U\, \langle\,f^{tot}_{k,n}\,\vert\,f^{tot}_{k,n}\,\rangle\,=\,\lambda\,U\,=\, \kappa^2\,K^2 \,m^2\, \left( y^2 + \frac{2a^2 M}{y^2\Xi^3}\right)   \,.
	\end{equation}
	%

	According to the standard holographic dictionary, the anomalous dimension of the corresponding dual operators are directly related to the corrections of the string energy.  The interpretation of results from holographic point of view is not straightforward since the dual theory is at finite temperature. Nevertheless, near or at conformal point the expressions can be thought of as the dispersion relations of stationary states.\\

	%




	\section{Conclusions} \label{Sect5}

	In this paper, we have studied a class of pulsating string solutions in a 5d Kerr-AdS black holes. 
	The holographic dual for the  Kerr-$AdS_{5}$ black hole is  $\mathcal{N}=4$ SYM on $\mathbb{S}^{1}\times \mathbb{S}^{3}$ at finite temperature (a thermal ensemble).
	 For simplicity we have focused on  the Kerr-$AdS_{5}$ background 
	with equal rotating parameters in the static-at-infinity frame.
	  To find pulsating string solutions in Kerr-$AdS_{5}$ we have adopted an appropriate pulsating ansatz
	for the circular string configuration. Considering the bosonic part of the string action in
	conformal gauge, we have found the relevant equations of motion and Virasoro constraints.
	The problem of finding periodic solutions imposes certain conditions even after the choice
	of pulsating string ansatz. The restriction of the parameters leads to several non-trivial
	cases, all of which have analytic solutions as combinations of trigonometric functions.
	An important key point of pulsating strings is that they reduce the problem to the
	(squared) Hamiltonian, which has the form of a point-particle Hamiltonian. It allows
	clearly to distinguish an effective string potential, which, being multiplied by the coupling constant $\,\lambda\,$, is used later for perturbative expansion. 
	Obtaining the effective wave function for the problem, we used perturbation theory to obtain the corrections to the energy. The latter,
	due to the AdS/CFT correspondence and under certain conditions, are related to the anomalous dimensions of operators
	in the dual gauge theory.
	In this paper we picked the asymptotically AdS black hole in five dimensions, Kerr-AdS, which possesses $SO(4)$ symmetry. If the space-time is only asymptotically anti-de Sitter it corresponds to UV conformal fixed points in the boundary theory.  Compared to AdS case  the IR behavior is expected to be quite different, with the horizon now playing the role of a thermal background.
	The holographic interpretation of the space-time conserved quantities however is not unique. It essentially depends on the choice of the conformal structure of the asymptotic metric at the  boundary. As we already mentioned in the bulk text, the notion of anomalous dimensions is well defined only in the vicinity of the conformal point.  This makes the interpretation from holographic point of view somewhat complicated and subtle. One way to make sense of the expressions is to consider two-point function, or scalar bulk-to-bulk Green's functions and see its behavior when one of the insertions is approaching the boundary. Indeed, one can see the considerations near conformal point are quite reasonable, thus the expressions can be interpreted as dispersion relations of stationary states in the gauge theory side.

	To the best of our knowledge, the obtained solutions are the first pulsating type solutions in  Kerr-$AdS_{5}$ black holes.
	 Moreover, we have computed the energy of the pulsating string the Kerr-$AdS_{5}$ background  following the Bohr-Sommerfeld analysis. We have found  corrections related to the rotation and temperature of the black hole. At zero value of the rotational parameter the relation for the energy tends to be known from \cite{Alishahiha:2002fi}.

	 There are several interesting concrete questions, which could be addressed further. First of all, it would be interesting to identify the operators on the gauge theory side whose anomalous dimension correspond to the various contributions in the energy spectrum. Finally, one should consider that the exact one-loop correction contains potential contributions from the fermionic sector. However, this contribution is fairly complicated even in the case of unbroken supersymmetry. In the case of Kerr-AdS  backgrounds, fermionic contribution is even more subtle question and remains to be done. 

	 Thinking about more general picture of the Kerr-AdS/CFT correspondence, many issues remain to be investigated and understood. In this paper we made some approximations to find the corrections to the string energy.  It will be also interesting to consider other holographic observables, i.e. thermal $n$-point correlation functions, in Kerr-$AdS_{5}$ background as it was done for non-rotating AdS black holes \cite{Kraus:2017kyl}-\cite{Karlsson:2021duj}. Particularly, to probe holographic four-point functions one needs to study a motion of a highly energetic particle in the 5d Kerr-AdS black hole \cite{Kulaxizi:2018dxo}-\cite{Kulaxizi:2019tkd}. 

	 Kerr-AdS black holes are remarkable with that its wave equation allows separation of variables. The radial and angular equations are of Fuchsian type and analyzing structure of singularities can be reduced to Heun type. Thus, it is literally calling to apply method from integrable systems and Riemann-Hilbert problem. Indeed,  the authors of \cite{Litvinov:2013sxa} have shown that the monodromy problem of the Heun equation is related to the connection problem for the Painleve VI and conformal blocks in 2d CFT, in particular Liouville field theory. Applying such an approach to scattering off black holes the authors of \cite{Novaes:2014lha}  have found that for generic charges the problem can be reduced to the Painleve VI transcendent. Moreover, the accessory parameters are expressed through the charges. 
	For the 5d case of the Kerr-AdS black holes scalar perturbations  it was shown that corrections to the extremal limit can be encoded in the monodromy parameters of the Painlevé V transcendent \cite{Amado:2017kao}-\cite{BarraganAmado:2021uyw}. 
	 Pulsating strings approach also relates dispersion relations to conserved charges, as well as field theory  characteristics.  It would be very interesting to investigate how and why all these quatities are related. Is there any relation to Alday-Gaiotto-Tachikawa conjecture? Another direction is to look at information geometry of the theory and try to see what information is accumulated in it.

	 	We hope to return to these issues in the near future.	 




