\section{Proofs of Properties 1--4}
\label{app:proofprops}

Here we report the proofs of Properties 1--4 from the main text. For convenience of the reader, we also precisely state each property before proving it. 

\begin{Prop}
The following facts hold
\begin{itemize}
\item[(i)] the eigenvalues of $\mathbb T$ (\emph{cf}. Eq.~(13) of the main text) have at most unit magnitude; 
\item[(ii)] even if $\mathbb T$ is generically not guaranteed to be diagonalisable, the algebraic and geometric multiplicites of any eigenvalue of magnitude $1$ coincide;
\end{itemize} 
\end{Prop}
\begin{proof}
Let $\ket{w}$ be an eigenvector associated with an eigenvalue with largest magnitude, then we have   
\begin{equation}
\braket{w|\mathbb O_\sigma^2|w}=\braket{w|\mathbb T^\dag\mathbb T|w}=|\lambda|^2\,.
\end{equation} 
Expanding in the eigenbasis of $\mathbb O_\sigma$ we have 
\begin{equation}
\braket{w|\mathbb O_\sigma^2|w} = \sum_n |\braket{w|n}|^2\,o_{\sigma,n}^2 \leq \sum_n |\braket{w|n}|^2   = 1\,,
\label{eq:shrink}
\end{equation}
where we used that $\ket{w}$ is normalised and the eigenvalues $o_{\sigma,n}$ of $\mathbb O_{\sigma}$ are in the interval $[0,1]$. This proves the point (i). For the point (ii) we first note that the matrix $\mathbb T$ is not normal 
\begin{equation}
\mathbb T ^\dag\mathbb T =\mathbb O_\sigma^2\,,\qquad 
\mathbb T\mathbb T^\dag =(\tilde U_{\rm KI}\otimes \tilde U_{\rm KI}^*)  \mathbb O_\sigma^2 (\tilde U_{\rm KI}\otimes \tilde U_{\rm KI}^*) ^\dag\,.
\end{equation}
There is then no general theorem ensuring that $\mathbb T$ is diagonalizable. To prove that, nonetheless, the algebraic and geometric multiplicites of any eigenvalue of magnitude $1$ coincide we use \emph{reductio ad absurdum}: let us assume that there is an eigenvalue $\lambda$ with unit magnitude corresponding to a non-trivial Jordan block 
and see that this leads to a contradiction. Let $\ket{w}$ be the eigenvector associated to $\lambda$, since the Jordan block is non-trivial we have a vector $\ket{v}$ such that  
\begin{equation}
\mathbb T \ket{v} = \lambda \ket{v}+ \alpha \ket{w}\,,\qquad \alpha \neq 0\,,
\end{equation}
and 
\begin{equation}
\braket{v|w}=0\,.
\end{equation}
This implies (noting that $\lambda^* \lambda = 1$)
\begin{equation}
\braket{v|\mathbb O_\sigma^2|v}=\braket{v|\mathbb T^\dag \mathbb T | v} = \braket{v|v}+|\alpha|^2\braket{w|w} + \lambda\alpha^* \braket{w|v} + \lambda^*\alpha \braket{v|w} =1+|\alpha|^2>1\,.
\label{eq:absurd}
\end{equation}
This result is in contradiction with \eqref{eq:shrink} concluding the proof of point (ii). 
\end{proof}

\begin{Prop}
The relations (16) of the main text imply 
\begin{align}
[A,M_\alpha] &=0\,, & &\alpha\in\{x,y,z\}\,,\label{eq:newcond1}\\
U A U^{\dag} &= e^{i \phi} A\,, & &\phi\in[0,2\pi]\,,\label{eq:newcond2}
\end{align}
where we defined 
\begin{equation}
U=\exp\left[i  \frac{\pi}{4} \sum_{j=1}^{t}\left(\sigma^z_j \sigma^z_{j+1}- \mathbbm{1}\right)\right]\,.
\end{equation}
\end{Prop}
\begin{proof}
Let us consider the operator $\tilde U_{\rm KI} M_z \tilde U_{\rm KI}^\dag$. Using Equations (16) of the main text it is immediate to see that this operator commutes with $A$
\begin{equation}
A \tilde U_{\rm KI} M_z \tilde U^\dag_{\rm KI} =  e^{-i \phi} \tilde U_{\rm KI} A M_z \tilde U^\dag_{\rm KI} = e^{-i \phi} \tilde U_{\rm KI} M_z A \tilde U^\dag_{\rm KI} = \tilde U_{\rm KI} M_z \tilde U^\dag_{\rm KI} A\,.
\end{equation}
Using the explicit form of $\tilde U_{\rm KI}$ (setting $|J|=|b|=\pi/4$) we have 
\begin{equation}
\tilde U_{\rm KI} M_z \tilde U_{\rm KI}^\dag = e^{\mp i \frac{\pi}{4} M_x} M_z e^{\pm i \frac{\pi}{4} M_x} = \sum_{j=1}^t  e^{\pm i \frac{\pi}{2} \sigma_j^x} \sigma_j^ze^{\mp i \frac{\pi}{2} \sigma_j^x}  = \mp M_y\,.
\end{equation}
So $M_y$ commutes with $A$. Since both $M_z$ and $M_y$ commute with $A$ we have that 
\begin{equation}
M_x = e^{i \frac{\pi}{4} M_z} M_y e^{-i \frac{\pi}{4} M_z}\,,
\end{equation}
also commutes with $A$: this proves \eqref{eq:newcond1}. The relation \eqref{eq:newcond2} follows from \eqref{eq:newcond1} and the first one of Eqs.~(16) of the main text. 
\end{proof}


\begin{Prop}
The case $\phi=\pi$ does not give solutions to \eqref{eq:newcond1}--\eqref{eq:newcond2} for odd $t$. 
\end{Prop}
\begin{proof}
To prove this property we consider the self-dual integrable (transverse field) kicked Ising Floquet operator 
\begin{equation}
U_{\rm TFKI}\equiv e^{-i  \frac{\pi}{4} \sum_{j=1}^{t}\sigma^z_j \sigma^z_{j+1}}e^{+i\frac{\pi}{4}  M_x }\,.
\end{equation}
The operator $U_{\rm TFKI}$ $\phi$-commutes with $A$ as a consequence of Property~2 and can be explicitly diagonalized: its diagonalization is reviewed in Section~\ref{app:integrablecase}. Writing the $\phi$-commutation in an eigenbasis of $U_{\rm TFKI}$ we have 
\begin{equation}
\braket{{n,\rm r}|A|{m,\rm r'}} (e^{i (e_{n,\rm r}-e_{m,\rm r'})}-e^{i \phi})=0\,,
\label{eq:Ainteigenvalues}
\end{equation}
where we denoted by $\ket{n,\rm r}$ the eigenstates of $U_{\rm TFKI}$. The index $\rm r\in\{\rm R, \rm NS\}$ distinguishes the two spin-flip symmetry sectors (\emph{cf}. Section~\ref{app:integrablecase}). Since $A$ is not the zero matrix, Eq.~\eqref{eq:Ainteigenvalues} implies that there exist some $n$ and $m$ such that 
\begin{equation}
e^{i (e_{n,\rm r}-e_{m,\rm r'})}-e^{i \phi}=0\,.
\end{equation}
Using the explicit expression for the quasi-energy differences in the integrable kicked Ising model at the self dual points, derived in Section~\ref{app:integrablecasediff}, we have
\begin{equation}
e_{n,\rm r}-e_{m,\rm r'} = \frac{2\pi}{t} N_{n,m}+\frac{\pi}{4 t} (\eta_{\rm r}-\eta_{\rm r'})=\phi\,, \qquad\qquad N_{n,m}\in\mathbb Z\,,\qquad\qquad\eta_{\rm R}=-\eta_{\rm NS}=-1\,,
\end{equation}
implying 
\begin{equation}
{8}N_{n,m}+(\eta_{\rm r}-\eta_{\rm r'})=\frac{4 t \phi}{\pi} \qquad\qquad N_{n,m}\in\mathbb Z\,,\qquad\qquad\eta_{\rm R}=-\eta_{\rm NS}=-1\,.
\end{equation} 
For $\phi=\pi$ the equation is solved for $t$ even by $\rm r = \rm r'$ and $N_{n,m}=t/2$. There is, however, no solution for $\phi=\pi$ and $t$ odd. 
\end{proof}

Before considering the proof of Property 4, it is useful to introduce orthogonal projectors $\{Y_k\}_{k=0,\ldots,t-1}$ on the fixed momentum eigenspaces $\{V_k\}_{k=0,\ldots,t-1}$, 
$\bigoplus_{k=0}^{t-1}V_k = {\cal H}_t$. Such operators are defined as follows 
\begin{equation}
Y_k=\frac{1}{t}\sum_{j=0}^{t-1}e^{\frac{2\pi i}{t} j k } \Pi^j\,,\qquad\qquad k\in\{0,\dots,t-1\}\,,
\end{equation}
and satisfy the orthogonality and the projection property
\begin{equation}
Y_k Y_p = \delta_{k-p}  Y_k\,.
\end{equation}
Moreover, they fulfil
\begin{equation}
R Y_k R = Y_{t-k}\,.
\end{equation}
We also introduce an additional set of operators 
\begin{equation}
Y'_k=R Y^{\phantom{\prime}}_k\,,\qquad\qquad k\in\{0,\dots,t-1\}\,.
\end{equation}
The operators $\{Y_k,Y'_k\}_{k=0,\ldots,t-1}$ form a closed multiplicative algebra, defined by 
\begin{equation}
Y^{\phantom{\prime}}_k Y^{\phantom{\prime}}_p = \delta_{k-p}  Y^{\phantom{\prime}}_k\,,\qquad Y'_k Y^{\phantom{\prime}}_p = \delta_{k-p} Y'_k,\qquad Y^{\phantom{\prime}}_k Y'_p = \delta_{k+p} Y'_p, \qquad Y'_k Y'_p = \delta_{k+p} Y^{\phantom{\prime}}_p\,.
\end{equation}
The linear mapping between $\{Y^{\phantom{\prime}}_k,Y'_k\}_{k=0,\ldots,t-1}$ and the elements of the dihedral group $\mathcal G_t$ is explicitly inverted as follows 
\begin{equation}
\sum_{k=0}^{t-1} Y_k \,e^{-\frac{2\pi i}{t} j k} = \Pi^j\,,\qquad\qquad \sum_{k=0}^{t-1} Y'_k \,e^{-\frac{2\pi i}{t} j k} = R \Pi^j\,.
\end{equation}
Since the mapping is invertible, we can restate the Property 4 as follows
\begin{Prop}
\label{prop:restatedprop4}
The number of linearly independent operators in the set $\{Y^{\phantom{\prime}}_k,Y'_k\}_{k=0,\ldots,t-1}$ is $2t$ for $t\geq6$, $2t-1$ for $t\in\{1,3,4,5\}$, and $2$ for $t=2$.
\end{Prop}
\begin{proof}
To prove this statement it is useful to distinguish the cases of $t$ even and $t$ odd. For odd $t$, all $\{Y^{\phantom{\prime}}_k,Y'_k\}_{k\neq0}$ are linearly independent. This is seen by writing these operators in the basis of momentum eigenstates and noting that each operator is non-zero only within a block of states with a given total momentum. Distinct operators are non zero on distinct, non-overlapping, blocks: this proves their linear independence. Noting that all $\{Y^{\phantom{\prime}}_k,Y'_k\}_{k\neq0}$ are zero when reduced to the zero-momentum block, we have that the only two operators which can be linearly dependent are $Y^{\phantom{\prime}}_0$ and $Y_0'$. In Lemma~\ref{Lemma1} of Section~\ref{app:proof} we prove that for $t\leq5$ they are linearly dependent, namely 
\begin{equation}
Y^{\phantom{\prime}}_0+Y_0'=0\,,
\end{equation} 
while they are independent for $t\geq 6$. In the case of even $t$ there is an additional special pair of operators, $Y_{t/2}$ and $Y_{t/2}'$, acting on the same momentum block (where all other $Y_k$ and $Y'_k$ are zero). In Lemma~\ref{Lemma2} of Section~\ref{app:evencase} we prove that $\{ Y^{\phantom{\prime}}_{t/2}, Y'_{t/2}\}$ are linearly independent for all even $t\ge 4$, while for $t=2$, $Y^{\phantom{\prime}}_{t/2}+Y'_{t/2}=0$. Putting all together we found that the set $\{Y^{\phantom{\prime}}_k,Y'_k\}_{k=0,\ldots,t-1}$ is composed of $2t-1$ linearly independent operators for $t\in\{1,3,4,5\}$ and by $2t$ linearly independent operators for $t\geq6$. In the special case $t=2$ we have just two linearly independent operators: $Y_0,Y_{t/2}=Y_1$. This concludes the proof. 
\end{proof}









\section{Proof of Theorem 1}
\label{app:proof}




Here we present the proof of Theorem 1. We start by restating it in terms of the operators $\{Y^{\phantom{\prime}}_k,Y'_k\}_{k=0,\ldots,t-1}$, introduced in the previous section 
\begin{Theorem}
\label{prop:basicconjecture}
For odd $t$, any $A$ simultaneously commuting with all the elements of $\{U,M_x,M_y,M_z\}$, is necessarily of the form
\begin{equation}
A=\sum_{k=0}^{t-1} c_{k}Y_k+\sum_{k=0}^{t-1} d_{k}Y'_k\,,\qquad\qquad\qquad  c_{k},d_k\in\mathbb C\,.
\label{eq:generalcommutingoperator}
\end{equation}
\end{Theorem}
To prove it, we reformulate it in the following equivalent way   
\begin{Theorem}
\label{prop:basicconjecture2}
Considering the representation of the algebra $\mathcal K$ generated by $\{U,M_x,M_y,M_z\}$ in a subspace $V_k\subset {\cal H}_t$ of fixed momentum $k$, the following facts hold  for odd $t$
\begin{itemize}
\item[(i)] If $k\neq0$ the representation is irreducible.
\item[(ii)] If $k=0$ the representation is irreducible for $t\leq5$ and is composed of two inequivalent irreducible representations for $t>5$. 
\item[(iii)] The representations in the two fixed momentum subspaces $V_k$ and $V_p$ are equivalent for $p= k$ or $p=t-k$ and inequivalent otherwise. 
\end{itemize}
\end{Theorem}
Let us first show that Theorem \ref{prop:basicconjecture2} is equivalent to Theorem~\ref{prop:basicconjecture}. 
\begin{proof}
Theorem \ref{prop:basicconjecture2} implies Theorem~\ref{prop:basicconjecture} as a consequence of Schur's Lemma. This is easily seen as follows. Let $A$ be a matrix commuting with the algebra $\mathcal K$ generated by $\{U,M_x,M_y,M_z\}$. Then we have 
\begin{equation}
E_k A_{k,p}= A_{k,p} E_p\,,\qquad\forall E\in \mathcal K\,,
\end{equation}
where
\begin{equation}
A_{k,p}\equiv Y_k A Y_p\,,\qquad\qquad E_k\equiv Y_k E = E Y_k\,.
\end{equation}
The facts (i), (ii), and (iii), combined with Schur's Lemma imply  
\begin{align}
&A_{k,p}=\delta_{k,p}\, c_k\, Y_{k} + \delta_{p,t-k}\, d_k\, Y'_k\,, & &k=1,\ldots,t\,,\qquad\qquad c_{k},d_k\in\mathbb C\,,\\
&A_{0,0}= c'_{0}\, Y_{0, a} + d'_{0}\, Y_{0, b}\,,  & &c'_{0},d'_0\in\mathbb C\,.
\end{align}
Here we used that $Y_k$ acts as the identity operator in the subspace $V_k$, while $Y'_k$ acts as the isomorphism between the subspaces $V_k$ and $V_{t-k}$. Moreover, we denoted by $Y_{0,a}$ and $Y_{0,b}$ the projectors on the subspaces $V_{0,a},V_{0,b}\subset V_0$ such that 
\begin{equation}
V_0=V_{0,a} \oplus V_{0,b}\,.
\end{equation}
The spaces $V_{0,a}$ and $V_{0,b}$ carry two inequivalent irreducible representations of $\mathcal K$ (for $t\leq5$ one of the two is trivial). Writing $Y_{0, a},Y_{0, b}$ in terms of $Y_{0}$ and $Y'_{0}$ we have
\begin{equation} 
A_{0,0}= c'_{0}\, Y_{0, a} + d'_{0}\, Y_{0, b}= c_{0}\, Y_{0} + d_{0}\, Y'_{0}\,,
\end{equation}
for appropriate $c_{0}, d_{0}\in\mathbb C$. Combining all together, we have 
\begin{equation}
A=\sum_{k,p=0}^{t-1} A_{k,p}=\sum_{k=0}^{t-1} c_{k}Y_k+\sum_{k=0}^{t-1} d_{k}Y'_k\,.
\end{equation}
This proves Theorem~\ref{prop:basicconjecture}. 

The reverse direction is proven by \emph{reductio ad absurdum}. If the representation of $\mathcal K$ in a fixed momentum sector were not satisfying (i), (ii) or (iii),  we could find operators commuting with the algebra $\mathcal K$ which are not of the form \eqref{eq:generalcommutingoperator}.  
\end{proof}


Let us now prove Theorem~\ref{prop:basicconjecture2}. Our strategy is to construct a basis of the momentum eigenspace $V_k$. We show that
\begin{itemize}
\item[(1)]  For $k\neq0$ all basis vectors are mapped into one another by elements of the algebra $\mathcal K$. 
\item[(2)] For $k=0$ all reflection symmetric vectors are mapped into one another by elements of the algebra $\mathcal K$. The same holds for reflection antisymmetric vectors. Moreover, we show that for $t\leq5$ the reflection anti-symmetric subspace is the zero space.  
\item[(3)] There is no invertible matrix $C$ such that  
\begin{equation}
(U)_p = C (U)_k C^{-1}\,,\qquad\qquad (M_j)_p = C (M_j)_k C^{-1},\qquad\qquad\qquad \text{for}\qquad k\not\in\{ p, t-p\}\,,
\label{eq:point3}
\end{equation}
where by $(M)_p$ we denote the matrix $M$ restricted to $V_p$. 
\end{itemize}
It is immediate to see that (1) $\Rightarrow$ (i), (2) $\Rightarrow$ (ii), and (3) $\Rightarrow$ (iii).

