\begin{proof}
To prove the statement we explicitly construct these operators using generators of $\mathcal K$. 



Let us consider 
\begin{equation}
U M_x U= \sum_{\tau=1}^{t} U \sigma_\tau^x U = \sum_{\tau=1}^{t} \sigma_\tau^x e^{i \frac{\pi}{2} (\sigma^z_{\tau-1}\sigma^z_{\tau}+\sigma^z_{\tau}\sigma^z_{\tau+1})} = - \sum_{\tau=1}^{t} \sigma_{\tau-1}^z\sigma_\tau^x \sigma_{\tau+1}^z\,.
\end{equation}
Rotating by $\pi/4$ around $x$ axis we then find 
\begin{equation}
e^{i \frac{\pi}{4} M_x}U M_x U e^{-i \frac{\pi}{4} M_x} = - \sum_{\tau=1}^{t} \sigma_{\tau-1}^y\sigma_\tau^x \sigma_{\tau+1}^y\,.
\end{equation}
Iterating the same operations $(k-1)/2$ times, for $k\leq t$ odd, we find 
\begin{equation}
\underbrace{e^{i \frac{\pi}{4} M_x}U\cdots e^{i \frac{\pi}{4} M_x}U}_{(k-1)/2} M_x \underbrace{U e^{-i \frac{\pi}{4} M_x}\cdots U e^{-i \frac{\pi}{4} M_x}}_{(k-1)/2}= - \sum_{\tau=1}^{t} \sigma_{\tau}^y\sigma_{\tau+1}^x \cdots \sigma_{\tau+t-2}^x \sigma_{\tau+k-1}^y\,.
\label{eq:opk}
\end{equation}
In particular, for $k=t$ we have 
\begin{equation}
\underbrace{e^{i \frac{\pi}{4} M_x}U\cdots e^{i \frac{\pi}{4} M_x}U}_{(t-1)/2} M_x \underbrace{U e^{-i \frac{\pi}{4} M_x}\cdots U e^{-i \frac{\pi}{4} M_x}}_{(t-1)/2}= - \sum_{\tau=1}^{t} \sigma_{\tau}^y\sigma_{\tau+1}^x \cdots \sigma_{\tau+t-2}^x \sigma_{\tau+t-1}^y\,.
\end{equation}
Multiplying by $e^{i \frac{\pi}{2} M_x}$ we find 
\begin{equation}
e^{i \frac{\pi}{2} M_x}\underbrace{e^{i \frac{\pi}{4} M_x}U\cdots e^{i \frac{\pi}{4} M_x}U}_{(t-1)/2} M_x \underbrace{U e^{-i \frac{\pi}{4} M_x}\cdots U e^{-i \frac{\pi}{4} M_x}}_{(t-1)/2}= - i^{(t-2)} \sum_{\tau=1}^{t} \sigma_{\tau}^z\sigma_{\tau+1}^z\,.
\end{equation}
The operators \eqref{eq:goaloperators1} are then obtained as follows. First we construct  
\begin{align}
&\sum_{\tau=1}^{t} \sigma_{\tau}^x\sigma_{\tau+1}^x=e^{i \frac{\pi}{4} M^y}\sum_{\tau=1}^{t} \sigma_{\tau}^z\sigma_{\tau+1}^ze^{-i \frac{\pi}{4} M^y}\,,\qquad \sum_{\tau=1}^{t} \sigma_{\tau}^y\sigma_{\tau+1}^y=e^{i \frac{\pi}{4} M^x}\sum_{\tau=1}^{t} \sigma_{\tau}^z\sigma_{\tau+1}^ze^{-i \frac{\pi}{4} M^x}\,,\\
&\sum_{\tau=1}^{t} (\sigma_{\tau}^x\sigma_{\tau+1}^y+\sigma_{\tau}^y\sigma_{\tau+1}^x)=\frac{i}{2} \left[\sum_{\tau=1}^{t} \sigma_{\tau}^x\sigma_{\tau+1}^x, M^z\right]\,.
\end{align}
Then we take the following linear combinations
\begin{equation}
\sum_{\tau=1}^{t} \sigma_{\tau}^x\sigma_{\tau+1}^x-\sum_{\tau=1}^{t} \sigma_{\tau}^y\sigma_{\tau+1}^y\pm i\sum_{\tau=1}^{t} (\sigma_{\tau}^x\sigma_{\tau+1}^y+ \sigma_{\tau}^y\sigma_{\tau+1}^x)=M^{\pm\pm}\,.
