D_n\equiv\frac{1}{n}\left(\left(\frac{i}{2}\right) \left[D_{n-1},M^z\right]+(k+2-n) D_{n-2}\right)\,,
\end{align}
and constructing the following linear combinations 
\begin{equation}
\sum_{j=0}^{t}(\pm i)^j D_j  = M^{\overbrace{\pm\!\ldots\!\pm}^{t}}\,.
\end{equation}
This concludes the proof.  
\end{proof}





\subsubsection{Proof of (1)}
We are now in a position to prove (1): we consider $k\neq0$ and show that we can map the states of the basis $\mathcal B_k$ into one another using elements of the algebra. Namely, for each pair $\ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}^{(k)}$ and $\ket{\bullet{\boldsymbol\sigma}'_{m'-2}\bullet}^{(k)}$ of states in $\mathcal B_k$ we construct an operator  $A_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}\in \mathcal K$ such that
\begin{equation}
{}^{(k)}\braket{\bullet{\boldsymbol\tau}_{m-2}\bullet|A_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}|\bullet{\boldsymbol\tau}'_{m'-2}\bullet}^{(k)} = \delta_{{\boldsymbol\tau},{\boldsymbol\sigma}}\delta_{{\boldsymbol\tau'},{\boldsymbol\sigma'}}\,,\qquad \qquad \forall  \ket{\bullet{\boldsymbol\tau}_{m-2}\bullet}^{(k)},\ket{\bullet{\boldsymbol\tau}'_{m'-2}\bullet}^{(k)}\in\mathcal B_k\,.
\label{eq:Aconn}
\end{equation} 
To construct such operator, it is useful to introduce the operator $B_{\boldsymbol\sigma}$, mapping the largest highest weight state $\ket{\bullet}^{(k)}$ to the basis vector $\ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}^{(k)}$. Namely
\begin{equation}
B_{\boldsymbol\sigma} \ket{\bullet}^{(k)}= \ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}^{(k)}\,.
\end{equation}
In terms of $B_{\boldsymbol\sigma}$, an operator $A_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}$ fulfilling \eqref{eq:Aconn} can be written as 
\begin{equation}
A_{{\boldsymbol\sigma},{\boldsymbol\sigma}'} = B_{\boldsymbol\sigma} \ket{\bullet}^{(k)(k)}\!\!\bra{{\bullet}} B_{\boldsymbol\sigma}^\dag\,,
\end{equation}
where ${(\cdot)}^\dag$ represents Hermitian conjugation. Our goal is to show that such $A_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}$ is in $\mathcal K$. It is immediate to see that the projector $\ket{\bullet}^{(k)(k)}\!\!\bra{{\bullet}}$ is in the algebra $\mathcal K$. Indeed, it can be written as  
\begin{equation}
\ket{\bullet}^{(k)}\!\!\!\!\!\!\!\!{\phantom{\ket{\bullet}}}^{(k)}\!\bra{{\bullet}} =  \frac{1}{4 \cos^2\left(\frac{2\pi k}{t}\right)}M^{\overbrace{z+\!\ldots\!+z}^{t}}M^{\overbrace{z-\!\ldots\!-z}^{t}}\,.
\end{equation} 
where $M^{\overbrace{z\pm\!\ldots\!\pm z}^{t}}$ are constructed in Lemma~\ref{lemma:additionaloperators} and the operator on the right hand side should be interpreted as an element of the representation of the algebra ${\cal K}$ in the fixed momentum subspace $V_k$. Moreover, if the operator $B_{\boldsymbol\sigma}$ is in the algebra so is its Hermitian conjugate. This is seen by noting  
\begin{equation}
U^\dag=U\,,\qquad M_x^\dag =M_x\,, \qquad M_y^\dag =M_y\,, \qquad M_z^\dag=M_z\,,
\end{equation}
implying that the Hermitian conjugate of any sum of products of $\{U,M_\alpha\}_{\alpha=x,y,z}$ is again a sum of products of $\{U,M_\alpha\}_{\alpha=x,y,z}$. 

The problem is then reduced to proving that the operator $B_{\boldsymbol\sigma}$ is in the algebra, or, in other words, that starting from $\ket{\bullet}^{(k)}$ we can access any state in $\mathcal B_k$ using elements of $\mathcal K$.



In order to proceed and avoid the problem of linear dependence in our coding of states for $m \ge (t+1)/2$, we make use of the following trick.
Consider spin chain of {\em double size} $2t$ and define analogous basis states 
\begin{eqnarray}
&&\ket{\overline{\bullet{\boldsymbol\sigma}_{m-2}\bullet}}^{(k)} \equiv \ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}_{2t}^{(2k)},\qquad \text{or}\\
&&{\ket{\overline{\bullet \underbrace{\circ\cdots\circ}_{\ell_1-1}\bullet\underbrace{\circ\cdots\circ}_{\ell_2-1}\bullet\cdots\bullet\underbrace{\circ\cdots\circ}_{\ell_a-1}\bullet}}}^{(k)}=\frac{1}{\sqrt{2t}}\sum_{j=0}^{2t-1} e^{\frac{2\pi i}{t} k j} \bar{\Pi}^j \sigma^-_{1}\sigma^-_{\ell_1+1}\sigma^-_{\ell_1+\ell_2+1}\cdots\sigma^-_{m}\ket{\underbrace{\uparrow\ldots\uparrow}_{2t}}
\label{eq:statesb}
\end{eqnarray}
spanning $V^{(2k)}_{2t}$ as defined by Eq. (\ref{eq:states}) for chain length $2t$ and momentum $2k$. Here, $\bar{\Pi}$ is a cyclic shift on $(\mathbb{C}^2)^{\otimes 2t}$.
Now, let us define the map $Q: V^{(2k)}_{2t} \to V^{(k)}_t$ completely specified by its action on the basis states
\begin{equation}
Q \ket{\overline{\bullet{\boldsymbol\sigma}_{m-2}\bullet}}^{(k)} = 
\begin{cases}
 \ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}_{t}^{(k)}, & m < t; \\
e^{\frac{2\pi i (n+1+h)k}{t}} \ket{ {\boldsymbol\sigma}''_{l}\!\bullet \underbrace{\circ\cdots \circ}_{2t-m}  \bullet {\boldsymbol\sigma}'_{n} }^{(k)}, & h > t;\\
 0, & \text{otherwise}.
\end{cases}
\label{eq:Q}
\end{equation}
Here we wrote 
\begin{equation}
{\boldsymbol\sigma}_{m-2} = \bullet {\boldsymbol\sigma}'_{n} \underbrace{\circ\cdots \circ}_h {\boldsymbol\sigma}''_{l}\bullet,
\end{equation} 
where $h$ is the largest number of contiguous holes in ${\boldsymbol\sigma}_{m-2}$ and $n+h+l=m-2$. Writing the algebra generators represented on the Hilbert space of spin chains of length $2t$ as $\bar{M}_\alpha$ and $\bar{P}_\pm=\frac{1}{2}(\mathbbm{1}\pm\bar{U})$, it is easy to check that
\begin{equation}
Q \bar{M}_\alpha = M_\alpha Q\,,\qquad Q \bar{P}_\pm = P_\pm Q\,.
\end{equation}
We shall write the corresponding linear operator algebra generated by $\bar{P}_\pm,\bar{M}_\pm$ as $\bar{\cal K}$. For example,  $\bar{M}^{\pm\pm}$ now defined as $
Q\bar{M}^{\pm\pm}=M^{\pm\pm}Q$, then read consistently
\begin{equation}
\bar{M}^{\pm\pm} = \sum_{\tau=1}^{2t} \sigma^\pm_\tau \sigma^\pm_{\tau+1},\quad{\text{with}}\quad 2t+1\equiv 1\,.
\end{equation}

Below we shall show that $\ket{\overline{\bullet}}^{(k)}$ can be connected to any $\ket{\overline{\bullet{\boldsymbol\sigma}_{m-2}\bullet}}^{(k)}$, for $m < t$, by the action of some element from $\bar{\cal K}$. It then follows trivially that $\ket{\bullet}^{(k)}$ connects to $\ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}^{(k)}$ by the corresponding element of ${\cal K}$ (just replacing generators
$\bar{M}^\pm,\bar{P}_\pm$ by $M^\pm,P_\pm$ in the generator representation of an element of $\bar{\cal K}$ or ${\cal K}$).

We start by noting 
\begin{equation}
\bar P_- \bar M^+ \ket{\overline{\underbrace{\bullet\bullet\cdots \bullet}_m}}^{(k)}= (1+e^{\frac{2\pi i}{t} k})\ket{\overline{\underbrace{\bullet\bullet\cdots \bullet}_{m-1}}}^{(k)}\qquad\qquad \bar P_- \bar M^- \ket{\overline{\underbrace{\bullet\bullet\cdots \bullet}_m}}^{(k)}= (1+e^{-\frac{2\pi i}{t} k})\ket{\overline{\underbrace{\bullet\bullet\cdots \bullet}_{m+1}}}^{(k)}\,.
\label{eq:mapamongblocks}
\end{equation}
where the right hand sides are never zero for $t$ odd. Moreover
\begin{equation}
\bar P_+ \bar M^{+}\ket{\overline{\bullet\bullet\bullet}}^{(k)} = \ket{\overline{\bullet\circ\bullet}}^{(k)}\,.
\label{eq:m3connection}
\end{equation}
From these relations it follows that we can map $\ket{\overline\bullet}^{(k)}$ into any state of length $m\leq3$ and to any block state \eqref{eq:blockstates}.

We now proceed using an inductive argument. Assuming that we can access every state $\ket{\overline{\bullet \,{\boldsymbol\sigma}^s_{n-2}\bullet}}^{(k)}$ of length $n<m$ and every state $\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-2}^{r}\bullet}}^{(k)}$ of length $m$ and $r<s$ holes we shall prove that we can access every state of length $m\geq4$ and $s\leq m-2$ holes
\begin{equation}
\ket{\overline{\bullet \,{\boldsymbol\sigma}^s_{m-2}\bullet}}^{(k)}\,.
\label{eq:goalstates}
\end{equation}
We first show that the unique state with $s=m-2$ holes is directly obtained from the block state of length $m$ as follows. First we note that  
\begin{equation}
(\bar P_- \bar M^+)^{m-3} \bar P_+ \bar M^+ \ket{\overline{\underbrace{\bullet\bullet\cdots \bullet}_m}}^{(k)} = \ket{\overline{\bullet\underbrace{\circ\cdots \circ}_{m-2} \bullet}}^{(k)} + A \ket{\overline{\bullet}}^{(k)}\,.
\end{equation}
Here $A \ket{\overline \bullet}^{(k)}$ represents a combination of states of length strictly smaller than $m$, which by inductive assumption can be obtained from $\ket{\overline \bullet}^{(k)}$ by applying an appropriate element of the algebra, $A\in \bar{\mathcal K}$. Since $ \ket{\overline{\underbrace{\bullet\bullet\cdots \bullet}_m}}^{(k)}$ is connected to $ \ket{\overline \bullet}^{(k)}$ by elements of the algebra we have 
\begin{equation}
A \ket{\overline \bullet}^{(k)} = B  \ket{\overline{\underbrace{\bullet\bullet\cdots \bullet}_m}}^{(k)}\qquad \text{for some}\qquad B\in \bar{\mathcal K}\,.
\end{equation}
Then, defining 
\begin{equation}
\left((\bar P_- \bar M^+)^{m-3}\bar P_+ \bar M^+\right)_{\rm red}  = (\bar P_- \bar M^+)^{m-3}\bar P_+ \bar M^+  - B \qquad\qquad \left((\bar P_- \bar M^+)^{m-3}\bar P_+ \bar M^+\right)_{\rm red}\in \bar{\mathcal K}\,,
\end{equation}
we have 
\begin{equation}
\left((\bar P_- \bar M^+)^{m-3}\bar P_+ \bar M^+\right)_{\rm red} \ket{\overline {\underbrace{\bullet\bullet\cdots \bullet}_m}}^{(k)} = \ket{\bullet\underbrace{\circ\cdots \circ}_{m-2} \bullet}^{(k)} \,.
\end{equation}
Consequently, in the following we can restrict to $s<m-2$.  

Considering any state $\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)}$ of length $m-1$ we have 
\begin{equation}
\bar P_\sigma \bar M^- \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)} = e^{-\frac{2\pi i k}{t}} \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)}+ \ket{ \overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet \bullet}}^{(k)} + \sum''_p\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3,p}\bullet}}^{(k)}  \,,
\end{equation} 
where $\sigma$ is chosen equal to $+$ or $-$ in order to maintain the number of ``disconnected islands'' of bullets when adding the new one and the last term on the r.h.s. is a sum of states obtained from  $\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)}$ by adding a bullet in position $1<p<m-1$. The allowed values of $p$ are the positions of the holes ${\boldsymbol\sigma}_{m-3}$ restricted by $\bar P_\sigma$. By the inductive assumption, the states $\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3,p}\bullet}}^{(k)}$ can be accessed from $\ket{\overline \bullet}^{(k)}$ with an appropriate element of the algebra $\bar{\mathcal K}$. Since $\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)}$ is connected to $\ket{\overline\bullet}^{(k)}$ by elements of the algebra we can represent the last term on the r.h.s. as follows 
\begin{equation}
\sum_p  \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3,p}\bullet}}^{(k)}={C}\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)}\,,
\end{equation}
for an appropriate $C\in\bar{\mathcal K}$. Defining then 
\begin{equation}
(\bar P_\sigma \bar M^-)_{\rm red}\equiv \bar P_\sigma \bar M^- -C\,,\qquad \qquad (\bar P_\sigma \bar M^-)_{\rm red}\in \bar{\mathcal K}\,,
\end{equation}
we have 
\begin{equation}
(\bar P_\sigma \bar M^-)_{\rm red} \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)} = e^{-\frac{2\pi i k}{t}} \ket{\overline {\bullet \bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(k)}+ \ket{ \overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet \bullet}}^{(k)}\,.
\label{eq:indcondgeneric}
\end{equation} 
Note that this relation alone is not sufficient to fix all the states of length $m$ given those of length $m-1$. It gives $2^{m-3}$ independent conditions while the total number of states is $2^{m-2}$. 

Restricting \eqref{eq:indcondgeneric} to states with $s$ holes we have 
\begin{equation}
(\bar P_\sigma \bar M^-)_{\rm red} \ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{m-3}\bullet}}^{(k)} = e^{-\frac{2\pi i k}{t}} \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}^{s}_{m-3}\bullet}}^{(k)}+ \ket{ \overline{\bullet \,{\boldsymbol\sigma}^{s}_{m-3}\bullet \bullet}}^{(k)}\,.
\label{eq:indcondsholes1}
\end{equation} 


An additional condition is found by using more of our inductive data: the states of length $m$ and $s-1$ holes. Applying $\bar M^+$ we find   
\begin{equation}
(\bar M^+)_{\rm red} \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\bullet}}^{(k)} =\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-3}^{s-1}\bullet}}^{(k)} +  \sum'_{p}\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}^{s}_{m-3,p}\bullet}}^{(k)}\,,
\label{eq:indcondsholes2p1}
\end{equation}
where $(\bar M^+)_{\rm red}\in\bar{\mathcal K}$ is defined as $\bar M^+-B$ for an appropriate $B\in\bar{\mathcal K}$, this allows us to remove lower length states from the r.h.s.. The string ${\boldsymbol\sigma}^{s}_{m-3,p}$ is obtained by removing one of the bullets from ${\boldsymbol\sigma}^{s-1}_{m-3}$ and the sum over $p$ in the r.h.s. of \eqref{eq:indcondsholes2} is restricted to the positions of the bullets in ${\boldsymbol\sigma}^{s-1}_{m-3}$. Analogously we find 
\begin{equation}
(\bar M^+)_{\rm red} \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\bullet\bullet}}^{(k)} =\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\circ \bullet}}^{(k)} +  \sum'_{p}\ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{m-3,p}\bullet \bullet}}^{(k)}\,.
\label{eq:indcondsholes2p2}
\end{equation}
Combining these equations we find 
\begin{align}
e^{-\frac{2\pi i k}{t}} (\bar M^+)_{\rm red} \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\bullet\bullet}}^{(k)}+(\bar M^+)_{\rm red} \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\bullet\bullet}}^{(k)} &= e^{-\frac{2\pi i k}{t}}\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-3}^{s-1} \bullet}}^{(k)}+\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\circ \bullet}}^{(k)}\notag\\
&+\sum'_{p}\left[e^{-\frac{2\pi i k}{t}} \ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{m-3,p}\bullet \bullet}}^{(k)}+\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}^{s}_{m-3,p} \bullet}}^{(k)} \right]\,.
\label{eq:indcondsholes2p3}
\end{align}
The sum on the r.h.s. can be cancelled by summing \eqref{eq:indcondsholes1} for a number of appropriate ${\boldsymbol\sigma}^{s}_{m-3}$, so we have 
\begin{align}
&e^{-\frac{2\pi i k}{t}} (\bar M^+)_{\rm red} \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\bullet\bullet}}^{(k)}+(\bar M^+)_{\rm red} \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\bullet}}^{(k)} -\sum'_{p}(\bar P_\sigma \bar M^-)_{\rm red} \ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{m-3,p}\bullet}}^{(k)} \notag\\
& = e^{-\frac{2\pi i k}{t}}\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-3}^{s-1} \bullet}}^{(k)}+\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\circ \bullet}}^{(k)}\,.\label{eq:indcondsholes2}
\end{align}
At this point it is useful to separate two cases: (a) $s=m-3$ and (b) $s<m-3$. In the case (b) we can find additional conditions by considering 
\begin{equation}
\left[(\bar P_\sigma (\bar M^{--}))_{\rm red} -((\bar P_\sigma \bar M^-)^2)_{\rm red}\right]  \ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{m-4}\bullet}}^{(k)}=-2e^{-\frac{2\pi i k}{t}} \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s}\bullet\bullet}}^{(k)}\,,
\label{eq:indcondsholes3}
\end{equation}
where we again defined $(\bar P_\sigma (\bar M^{--}))_{\rm red}$ {(\emph{cf}. Lemma~\ref{lemma:additionaloperators})} by appropriately subtracting operators in $\bar{\mathcal K}$ generating terms with smaller $m$ and $s$. Using this condition we also get 
\begin{align}
D\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s-1}\bullet\bullet}}^{(k)}&\equiv(\bar M^+)_{\rm red} \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s-1}\bullet\bullet}}^{(k)}+\frac{1}{2}e^{\frac{2\pi i k}{t}}\sum'_{p}\left[(\bar P_\sigma (\bar M^{--}))_{\rm red} - (\bar P_\sigma \bar M^-)^2)_{\rm red}\right]  \ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{m-4,p}\bullet}}^{(k)} \notag\\
& =  \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s-1}\circ\bullet}}^{(k)}+\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-4}^{s-1}\bullet\bullet}}^{(k)} \,\label{eq:indcondsholes4}
\end{align}
and 
\begin{align}
&(\bar M^+)_{\rm red} \left(\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s-2}\circ\bullet}}^{(k)}+\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-4}^{s-2}\bullet \bullet}}^{(k)}\right)-\sum'_p D\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4,p}^{s-1}\bullet\bullet}}^{(k)}\notag\\
& =  \ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-4}^{s-2}\circ\bullet}}^{(k)}\,,\label{eq:indcondsholes5}
\end{align}
for some $D\in \bar{\cal K}$.
To conclude the inductive step we show that in the case (b) the conditions \eqref{eq:indcondsholes1}, \eqref{eq:indcondsholes2}, \eqref{eq:indcondsholes3}, \eqref{eq:indcondsholes4} and \eqref{eq:indcondsholes5} give a complete set of vectors in the sub-space spanned by \eqref{eq:goalstates}, while in the case (a) a complete set of vectors is given by \eqref{eq:indcondsholes1}, \eqref{eq:indcondsholes2} and say \eqref{eq:indcondsholes2p1}. 
Let us start considering the case (a) and prove that the only vector in the subspace orthogonal to all vector expressions of Eqs. \eqref{eq:indcondsholes1}, \eqref{eq:indcondsholes2p1}, and \eqref{eq:indcondsholes2} is the zero vector, meaning that these equations give a complete set. We write a generic vector in the subspace as 
\begin{equation}
\ket{g}=\sum_{{\boldsymbol\sigma}\in\mathcal S^{s}_{m-2}} a_{{\boldsymbol \sigma}}\ket{\overline{\bullet\, {\boldsymbol\sigma} \, \bullet}}^{(k)}\,.
\label{eq:genericvector}
\end{equation}
where we denoted by $\mathcal S^{s}_{m}$ the set of all strings of $\bullet$ and $\circ$ with length $m$ and $s$ holes. Requiring \eqref{eq:genericvector} to be orthogonal to \eqref{eq:indcondsholes1}, \eqref{eq:indcondsholes2p1}, and \eqref{eq:indcondsholes2} we find the following conditions 
\begin{align}
&a_{{\boldsymbol\sigma}\bullet}  e^{-\frac{2\pi i k}{t}} + a_{\bullet {\boldsymbol\sigma}} =0\,,  & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-3}_{m-3}\,, \label{eq:conda1}\\
&a_{{\boldsymbol\sigma}\circ}  e^{-\frac{2\pi i k}{t}} + a_{\circ {\boldsymbol\sigma}} =0\,,  & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-4}_{m-3}\,,\label{eq:conda2}\\
&a_{\circ {\boldsymbol\sigma}} + a_{\bullet  \underbrace{\circ\dots\circ}_{m-3}} =0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-4}_{m-3}\,.\label{eq:conda3}
\end{align}
Considering $\boldsymbol\sigma=\circ\bullet\overbrace{\circ\ldots\circ}^{m-4}$ in \eqref{eq:conda3} (note that since $m\geq4$ we can always consider such a string) and using \eqref{eq:conda2} we find  
\begin{equation}
(1-e^{-\frac{2\pi i k}{t}})a_{\bullet \circ\dots\circ} =0
\label{eq:trueforkneq0}
\end{equation}
which for odd $t$ gives 
\begin{equation}
a_{\bullet \circ\dots\circ} =0\qquad \forall\, m\geq 4\,.
\end{equation}
Then, using \eqref{eq:conda1} and \eqref{eq:conda2} we have that for some $n\in\mathbb N$
\begin{equation}
a_{\boldsymbol \sigma} =e^{-\frac{2\pi i k n}{t}} a_{\bullet \circ\dots\circ} =0 \qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{m-3}_{m-2}\,.
\end{equation}
Let us now consider the case (b), $s < m-3$. In this case the orthogonality conditions read as 
\begin{align}
&a_{{\boldsymbol\sigma}\bullet}  e^{-\frac{2\pi i k}{t}} + a_{\bullet {\boldsymbol\sigma}} =0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{s}_{m-3}\,, \label{eq:condb1}\\
&a_{{\boldsymbol\sigma}\circ}  e^{-\frac{2\pi i k}{t}} + a_{\circ {\boldsymbol\sigma}} =0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{s-1}_{m-3}\,,\label{eq:condb2}\\
& a_{\bullet \boldsymbol \sigma \bullet} =0\,, &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{s}_{m-4}\,,\label{eq:condb3}\\
& a_{\circ \boldsymbol \sigma \bullet} +a_{\bullet \boldsymbol \sigma \circ} =0\,, &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{s-1}_{m-4}\,,\label{eq:condb4}\\
& a_{\circ \boldsymbol \sigma \circ} =0\,, &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{s-2}_{m-4}\,.\label{eq:condb5}
\end{align}
Using \eqref{eq:condb1}, \eqref{eq:condb2}, \eqref{eq:condb3}, and \eqref{eq:condb5} we see that if the string $\boldsymbol \sigma$ contains two subsequent $\bullet$ or two subsequent $\circ$ we immediately have 
\begin{equation}
a_{\boldsymbol \sigma}=0\,.
\end{equation}
So the only non zero coefficient is found for even $m$ and $s=m/2$; the associated strings have the form ${\circ\!\bullet\!\circ\dots\bullet\!\circ\bullet}$ or ${\bullet\!\circ\!\bullet\dots\circ\!\bullet\circ}$. Using \eqref{eq:condb4} we then have 
\begin{equation}
a_{ \bullet \circ\bullet\circ\dots\bullet\circ\bullet\circ} =- a_{\bullet \bullet \circ\bullet\dots\circ\bullet\circ\circ} =0 \qquad\qquad a_{ \circ\bullet\circ\bullet\dots\circ\bullet\circ\bullet} =- a_{\bullet \bullet \circ\bullet\dots\circ\bullet\circ\circ} =0\,.
\end{equation}
This proves the completeness of the conditions and concludes the inductive step. 



\subsubsection{Proof of (2)}
Let us now move to consider the zero momentum sector $k=0$. First we note that the representation of the algebra $\mathcal K$ in this sector is not generically irreducible. Indeed, since $R$ commutes with all elements of ${\cal K}$ we have 
\begin{align}
&{}^{(0)}\braket{\bullet \,{\boldsymbol\sigma}'_{m'-2}\bullet|S_+ A S_- |\bullet \,{\boldsymbol\sigma}_{m-2}\bullet}^{(0)}=\notag\\
&={}^{(0)}\braket{\bullet \,{\boldsymbol\sigma}'_{m'-2}\bullet|S_+  S_- A |\bullet \,{\boldsymbol\sigma}_{m-2}\bullet}^{(0)}=0\qquad\qquad\qquad A\in\mathcal K\,,\quad m,m'\geq3\,, \forall {\boldsymbol\sigma}'_{m'-2},{\boldsymbol\sigma}_{m-2}\,.
\end{align}
In other words, elements of $\mathcal K$ cannot connect the two reflection symmetry sectors. Note that in the proof of the previous section this is reflected by the fact that for $k=0$ and $m=4$,  Eq.~ \eqref{eq:trueforkneq0} becomes trivial and does not fix anymore the coefficient $a_{\bullet \circ}$. 

This fact means that the representation of $\mathcal K$ can be irreducible only if one of the two reflection symmetry sectors becomes the zero space. The latter situation arises for small enough chain lengths as described by the following lemma
\begin{Lemma}
\label{Lemma1}
For $1<t \leq 5$ the are no vectors odd under reflection symmetry. In other words the projector $S_-$ ({cf}.~\eqref{eq:Sproj}), restricted to $V_0$, is the zero matrix. Instead, for  $t > 5$ both $S_-$ and $S_+$ are non-trivial. 
\end{Lemma}
\begin{proof}
 We note that the non-reflection symmetric vectors $\ket{\bullet \,{\boldsymbol\sigma}_{m-2}\bullet}^{(0)}$ with lowest $m$ are given by 
\begin{align}
&m=4& &\left\{\ket{\bullet \bullet \circ\, \bullet}^{(0)}\,,\qquad \ket{\bullet \circ \bullet\, \bullet}^{(0)}\right\}\,,\notag\\
&m=5& &\left\{\ket{ \bullet \circ \bullet \bullet \bullet}^{(0)}\,,\qquad \ket{\bullet \bullet \bullet \circ \bullet}^{(0)}\right\}\,.
\label{eq:nonrefsym}
\end{align}
These vectors are mapped into one another by $R$
\begin{equation}
R\ket{ \bullet \circ \bullet\, \bullet}^{(0)} =  \ket{ \bullet \bullet \circ\, \bullet}^{(0)}\,,\qquad R\ket{ \bullet \circ \bullet \bullet \bullet}^{(0)} =  \ket{\bullet \bullet \bullet \circ \bullet}^{(0)}\,.
\end{equation}
To define such states we need at least $t \geq 4$, so for $1<t \leq 3$ our claim is obvious. The fact that no reflection anti-symmetric state is present also for $t=5$ follows from the observation that for $t<6$ the states \eqref{eq:nonrefsym} with the same length are equivalent (they correspond to the same vector in $\mathcal B_0$) and are then reflection symmetric. 
\end{proof}

Our strategy in the following is to show that
\begin{itemize}
\item[(i)] Any pair of vectors even under reflection symmetry are mapped into one another by operators in $\mathcal K$.
\item[(ii)] Any pair of vectors odd under reflection symmetry are mapped into one another by operators in $\mathcal K$.
\end{itemize}
This proves that the momentum $k=0$ representation of $\mathcal K$ is irreducible for $t\leq5$, while it is split in two irreducible components for $t>5$. Note that these representations are inequivalent, moreover they are both inequivalent to all the representations in the non-zero momentum eigenspaces. This is seen by noting that the parity symmetric sector contains a representation of SU(2), generated by $M^\pm,M_z$, with spin $t/2$ while the highest weight representation of SU(2) in the antisymmetric sector has spin $t/2-3$. 

Let us start with (i) and proceed as in the previous subsection. The operator $A^+_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}$, mapping the states $S_+  \ket{{\bullet \,{\boldsymbol\sigma}_{m-2}\bullet}}^{(0)}$ and $S_+  \ket{{\bullet \,{\boldsymbol\sigma}'_{m-2}\bullet}}^{(0)}$ into one another, can be written as 
\begin{equation}
A^+_{{\boldsymbol\sigma},{\boldsymbol\sigma}'} = B^+_{\boldsymbol\sigma} \ket{\emptyset}\bra{\emptyset} ({B_{\boldsymbol\sigma}^+})^\dag\,.
\end{equation} 
Here $\ket{\emptyset}$ is the ferromagnetic state with all spins down, $(\cdot)^\dag$ is the Hermitian conjugation, and $B^+_{\boldsymbol\sigma}$ is the operator mapping  $\ket{\emptyset}$ to the state $S_+  \ket{{\bullet \,{\boldsymbol\sigma}_{m-2}\bullet}}^{(0)}$. Namely
\begin{equation}
B^+_{\boldsymbol\sigma} \ket{\emptyset}= S_+  \ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}^{(0)}\,.
\end{equation}
As before we have to prove that $A^+_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}\in\mathcal K$. It is easy to prove that the projector $\ket{\emptyset}\bra{\emptyset}$ is in the algebra, as it can be written as 
\begin{equation}
\ket{\emptyset}\bra{\emptyset} = M^{\overbrace{+\!\ldots\!+}^{t}}M^{\overbrace{-\!\ldots\!-}^{t}}\,,
\end{equation}
where the operator on the right hand side should be interpreted as an element of the representation of the algebra ${\cal K}$ in the 0-momentum positive-parity subspace $S_+V_0$. To prove that $A^+_{{\boldsymbol\sigma},{\boldsymbol\sigma}'} \in\mathcal K$ we then need to prove that the operator $B^+_{\boldsymbol\sigma}$ (and so also $({B^+_{\boldsymbol\sigma}})^\dag$) is in the algebra. In other words, we have to prove that we can map $\ket{\overline{\emptyset}}$ to any state in the symmetric sector by using elements of the algebra. Again, to prove this statement we consider the basis (\ref{eq:statesb}) of the double sized ($2t$) chain, including also the ferromagnetic states $\ket{\overline{\emptyset}}$ and $\ket{\overline{{\bullet\ldots\bullet}}}$ in the basis. 

First we note that Eqs.~\eqref{eq:mapamongblocks} and \eqref{eq:m3connection} imply that we can map $\ket{\overline \emptyset}$ into any state of the form $\bar S_+  \ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}\bullet}}^{(0)}$ with length $m\leq3$ and into any block state \eqref{eq:blockstates} (which are even under reflection).

Let us now prove that acting with operators in $\bar{\mathcal K}$ on the state $\ket{\overline \emptyset}$ we can access every state of the form  
\begin{equation}
\bar S_+  \ket{\overline{\bullet \,{\boldsymbol\sigma}^s_{m-2}\bullet}}^{(0)}\,,\qquad s=0,\ldots,m-2\,,\qquad m=3,\ldots, t\,,
\label{eq:goalstatesS+}
\end{equation}
assuming that we can access every state $\bar S_+\ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{n-3}\bullet}}^{(0)}$ of length $n<m$ and every state $\bar S_+\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-2}^{r}\bullet}}^{(0)}$ with $r<s$. Using the relations \eqref{eq:indcondsholes1}, \eqref{eq:indcondsholes2p1}, and \eqref{eq:indcondsholes2} we have 
\begin{align}
& A \ket{\overline\emptyset} = \bar S_+\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-3}^{s} \bullet}}^{(0)}+\bar S_+\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s}\bullet \bullet}}^{(0)}\,,  \label{eq:S+indcondsholes1}\\
& B \ket{\overline\emptyset} =\bar S_+\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-3}^{s-1} \bullet}}^{(0)}+\bar S_+\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{s-1}\circ \bullet}}^{(0)}\,, \label{eq:S+indcondsholes2}\\
&C \ket{\overline\emptyset} =  \bar S_+\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}^{s-1}_{m-3}\bullet}}^{(0)}+ \sum'_p   \bar S_+\ket{\overline{\bullet\bullet \,{\boldsymbol\sigma}^s_{m-3,p}\bullet}}^{(0)}  \,,\qquad\qquad A,B,C\in \bar{\mathcal K}\,.\label{eq:S+indcondsholes3}
\end{align} 
As we did before we distinguish two cases: (a) $s=m-3$ and (b) $s<m-3$. Let us prove that in the case (a) Eqs.~\eqref{eq:S+indcondsholes1},  \eqref{eq:S+indcondsholes2} and \eqref{eq:S+indcondsholes3} form a complete set of vectors in the sub-space spanned by \eqref{eq:goalstatesS+}. To do that we show that a generic linear combination of the vectors \eqref{eq:goalstatesS+} is orthogonal to all \eqref{eq:S+indcondsholes1},  \eqref{eq:S+indcondsholes2}, and \eqref{eq:S+indcondsholes3} only if is the zero vector. The most general linear combination of states \eqref{eq:goalstatesS+} can be written as 
\begin{align}
\ket{g}_{\rm sym}=  &\sum'_{{\boldsymbol\sigma}\in\mathcal S^{s}_{m-2}} a_{{\boldsymbol\sigma}} \ket{\overline{ \bullet \, {\boldsymbol\sigma} \bullet}}^{(0)}\,,
\label{eq:genericvectorS+}
\end{align}
where $a_{\boldsymbol \sigma}$ is subject to the constraint 
\begin{equation}
a_{{\boldsymbol\sigma}}=a_{{\boldsymbol\sigma}^R}\,,
\label{eq:constraint}
\end{equation}
and $\cdot^R$ denotes the reflection operation (reversal) of the string of bullets and holes. The orthogonality conditions read
\begin{align}
&a_{{\boldsymbol\sigma}\bullet}  + a_{\bullet {\boldsymbol\sigma}} =0\,, \qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{m-3}_{m-3}\,, \label{eq:conda1S+}\\
&a_{{\boldsymbol\sigma}\circ} + a_{\circ {\boldsymbol\sigma}} =0\,, \qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{m-4}_{m-3}\,.\label{eq:conda2S+}\\
&a_{\circ {\boldsymbol\sigma}} + a_{\bullet \underbrace{\circ\dots\circ}_{m-3}}  =0\,, \qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{m-4}_{m-3}\,.\label{eq:conda3S+}
\end{align}
We see that now the case $m=4$ is fixed by either \eqref{eq:conda1S+} or \eqref{eq:conda3S+}, indeed using \eqref{eq:constraint} we have 
\begin{equation}
a_{\circ\bullet}+a_{\bullet\circ}=2a_{\circ\bullet}=2a_{\bullet\circ}=0\,.
\end{equation}
For $m>4$ we choose $\boldsymbol\sigma=\circ\circ\bullet\overbrace{\circ\ldots\circ}^{m-5}$ in \eqref{eq:conda3S+}, and using \eqref{eq:conda2S+} two times we find  
\begin{equation}
a_{\bullet \circ \ldots\circ} = 0 \,.
\end{equation}
Then, using \eqref{eq:conda1S+} and \eqref{eq:conda2S+} we have 
\begin{equation}
a_{\boldsymbol \sigma} = a_{\bullet \circ\dots\circ} =0 \qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{m-3}_{m-2}\,.
\end{equation}
The case (b) is treated by considering the additional conditions originating from \eqref{eq:indcondsholes3}, \eqref{eq:indcondsholes4} and \eqref{eq:indcondsholes5}, namely
\begin{align}
&D \ket{\bar{\emptyset}} = \bar S_+ \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s}\bullet\bullet}}^{(0)}\,,
\label{eq:S+indcondsholes3}\\
& E \ket{\bar{\emptyset}} = \bar  S_+\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s-1}\circ\bullet}}^{(0)}+\bar S_+ \ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-4}^{s-1}\bullet\bullet}}^{(0)} \,\label{eq:S+indcondsholes4}\\
& F \ket{\bar{\emptyset}} = \bar S_+ \ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-4}^{s-2}\circ\bullet}}^{(0)}\,,\qquad\qquad\qquad\qquad\qquad\qquad D,E,F\in\bar{\mathcal K}\,.\label{eq:S+indcondsholes5}
\end{align}
The orthogonality conditions read as 
\begin{align}
&a_{{\boldsymbol\sigma}\bullet}+ a_{\bullet {\boldsymbol\sigma}} =0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{s}_{m-3}\,, \label{eq:condb1S+}\\
&a_{{\boldsymbol\sigma}\circ}   + a_{\circ {\boldsymbol\sigma}} =0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{s-1}_{m-3}\,,\label{eq:condb2S+}\\
& a_{\bullet \boldsymbol \sigma \bullet} =0\,, &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{s}_{m-4}\,,\label{eq:condb3S+}\\
& a_{\circ \boldsymbol \sigma \bullet} +a_{\bullet \boldsymbol \sigma \circ} =0\,, &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{s-1}_{m-4}\,,\label{eq:condb4S+}\\
& a_{\circ \boldsymbol \sigma \circ} =0\,, &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{s-2}_{m-4}\,.\label{eq:condb5S+}
\end{align}
and are solved as in the above section giving 
\begin{equation}
a_{\boldsymbol \sigma} =0 \qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{s}_{m-2}\,, \qquad \forall\,s<m-2.
\end{equation}
Let us now consider the point (ii).  In this case, the operator $A^-_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}$, mapping the states $S_-  \ket{{\bullet \,{\boldsymbol\sigma}_{m-2}\bullet}}^{(0)}$ and $S_-  \ket{{\bullet \,{\boldsymbol\sigma}'_{m-2}\bullet}}^{(0)}$ into one another, can be written as 
\begin{equation}
A^-_{{\boldsymbol\sigma},{\boldsymbol\sigma}'} = B^-_{\boldsymbol\sigma} S_- \ket{{\bullet \circ \bullet\, \bullet}}^{(0)(0)}\!\bra{{\bullet \circ \bullet\, \bullet}}S_- ({B_{\boldsymbol\sigma}^-})^\dag\,.
\end{equation} 
Here $S_-\ket{{\bullet \circ \bullet\, \bullet}}^{(0)}$ is the parity-odd state with minimal length and $B^-_{\boldsymbol\sigma}$ is the operator mapping $S_-\ket{{\bullet \circ \bullet\, \bullet}}^{(0)}$ to the state $S_-  \ket{{\bullet \,{\boldsymbol\sigma}_{m-2}\bullet}}^{(0)}$. Namely
\begin{equation}
B^-_{\boldsymbol\sigma} S_-\ket{{\bullet \circ \bullet\, \bullet}}^{(0)} = S_-  \ket{\bullet{\boldsymbol\sigma}_{m-2}\bullet}^{(0)}\,.
\end{equation}
Once again, we need to prove that $A^-_{{\boldsymbol\sigma},{\boldsymbol\sigma}'}\in\mathcal K$. The projector $S_- \ket{{\bullet \circ \bullet\, \bullet}}^{(0)(0)}\bra{{\bullet \circ \bullet\, \bullet}}S_-$ can be written as 
\begin{equation}
S_- \ket{{\bullet \circ \bullet\, \bullet}}^{(0)(0)}\bra{{\bullet \circ \bullet\, \bullet}}S_-=  e^{i \frac{\pi}{2} (M^x-t)} M^{\overbrace{z\!-\!\ldots\!-\!z}^{t-4}} e^{i \frac{\pi}{2} (M^x-t)} P_- M^{\overbrace{z\!-\!\ldots\!-\!z}^{t-4}}\,,
\end{equation}
and it is then an element of the algebra as a consequence of Lemma~\ref{lemma:additionaloperators}. The operator on the right hand side should be interpreted as an element of the representation of the algebra ${\cal K}$ in the 0-momentum negative-parity subspace $S_-V_0$. So, as before, to show that $A^-_{{\boldsymbol\sigma},{\boldsymbol\sigma}'} \in  \mathcal K$ we need to show that $B^-_{\boldsymbol\sigma}$ (and so also $(B^-_{\boldsymbol\sigma})^\dag$) is in the algebra, \emph{i.e.}, that acting with operators of $\mathcal K$ on $S_- \ket{{\bullet \circ \bullet\, \bullet}}^{(0)}$ we can access every state in the odd parity sector. Such states have the form  
\begin{equation}
S_-  \ket{\bullet \,{\boldsymbol\sigma}^s_{m-2}\bullet}^{(0)}\,,\qquad s=1,\ldots,m-3\,,\qquad m=3,\ldots, t\, ,
\label{eq:goalstatesS-}
\end{equation}
where we considered values of $s$ giving non-vanishing states.

We proceed once again by induction and consider the corresponding basis states (\ref{eq:statesb}) of the double sized ($2t$) chain and finally use the projector $Q$ (\ref{eq:Q}) to obtain all the required mappings. Let us start by constructing the basis for our inductive construction. Applying $ \bar P_+ \bar M^-$ on $\ket{ \overline{\bullet \circ \bullet\, \bullet}}^{(0)}$ we have  
\begin{equation}
\bar P_+ \bar M^- \bar S_- \ket{\overline{\bullet \circ \bullet\, \bullet}}^{(0)} = \bar S_- \ket{\overline{\bullet \circ \bullet \bullet \bullet}}^{(0)}\,,
\end{equation}
which is the only antisymmetric state of length $5$ with one hole. We also have 
\begin{equation}
\left((\bar P_+ \bar M^- \bar P_+ \bar M^+) -\mathbbm{1} \right)\bar S_- \ket{\overline{\bullet \circ \bullet \,\bullet}}^{(0)} = \bar S_- \ket{\overline{\bullet \circ \circ \bullet \bullet}}^{(0)} \,,
\end{equation}
which is the only antisymmetric state of length $5$ and two holes. So we explicitly constructed any antisymmetric state  \eqref{eq:goalstatesS-} of length $m\leq 5$. 

Let us now show that if we can access every state $\bar S_-\ket{\overline{\bullet \,{\boldsymbol\sigma}^{s}_{n-3}\bullet}}^{(0)}$ of length $n<m$ and every state $\bar S_-\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-2}^{r}\bullet}}^{(0)}$ with $r<s$ then we can access all the states \eqref{eq:goalstatesS-} for $m\geq6$. 
To do this we need to distinguish three cases: (a) $s=1$; (b) $1<s<m-3$; (c) $s=m-3$. Let us start form the case (c): if we can get all the states $\bar S_-\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-2}^{1}\bullet}}^{(0)}$ then we consider 
\begin{equation}
(\bar P_+ \bar M^+)^{m-4} \bar S_-\ket{\overline{\bullet \circ \underbrace{\bullet \ldots \bullet}_{m-2}}}^{(0)} - \bar S_-\ket{\overline{\bullet \circ \bullet\, \bullet}}^{(0)} = \bar S_-\ket{\overline{\bullet \underbrace{\circ \ldots \circ}_{m-3} \bullet\, \bullet}}^{(0)}\,,
\end{equation}
giving a vector with length $m$ and $m-3$ holes. The other conditions are found by projecting \eqref{eq:indcondsholes2} on the parity odd space 
\begin{equation}
A \bar S_- \ket{\overline{ \bullet \circ \bullet\, \bullet}}^{(0)} = \bar S_-\ket{\overline{\bullet \circ \,{\boldsymbol\sigma}_{m-3}^{m-4} \bullet}}^{(0)}+\bar S_-\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{m-4}\circ \bullet}}^{(0)}\,,\qquad A\in \bar{\mathcal K}\,.\\
\end{equation}
Let us show that these conditions give a complete set of vectors in the parity odd subspace. Once again we will prove that by showing that only the zero vector is orthogonal to all of the vectors expressing the conditions. Considering a generic vector of length $m$ and $s$ holes in the parity odd subspace with we have 
\begin{align}
\ket{g}_{\rm antisym}=  &\sum''_{{\boldsymbol\sigma}\in\mathcal S^{s}_{m-2}} a_{{\boldsymbol\sigma}} \ket{ \overline{\bullet \, {\boldsymbol\sigma} \bullet}}^{(0)}\,,
\label{eq:genericvectorS-}
\end{align} 
where the coefficients are subject to the constraint 
\begin{equation}
a_{{\boldsymbol\sigma}}=-a_{{\boldsymbol\sigma}^R}\,.
\label{eq:constraintS-}
\end{equation}
The orthogonality conditions read as 
\begin{align}
&a_{{\boldsymbol\sigma}\circ}+ a_{\circ {\boldsymbol\sigma}} =0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-4}_{m-3}\,, \label{eq:condc1S-}\\
&a_{\underbrace{\circ \ldots \circ}_{m-3} \bullet}=0\,. \label{eq:condc2S-}
\end{align}
Since using \eqref{eq:condc1S-} we can always bring $a_{{\boldsymbol\sigma}}$ in the form \eqref{eq:condc2S-} we have 
\begin{equation}
a_{{\boldsymbol\sigma}}=0\,,\qquad\qquad\qquad\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-3}_{m-2}\,.
\end{equation}
Let us now consider the case (a). Here we cannot use conditions from the states with $s-1$ holes since there are none. We then use 
\begin{align}
& A \bar S_- \ket{\overline{\bullet \circ \bullet\, \bullet}}^{(0)} = \bar S_-\ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-3}^{1} \bullet}}^{(0)}+\bar S_-\ket{\overline{\bullet \,{\boldsymbol\sigma}_{m-3}^{1}\bullet \bullet}}^{(0)}\,, \label{eq:S-indcondsholes1}\\
&B \bar S_- \ket{\overline{\bullet \circ \bullet\, \bullet}}^{(0)} = \bar S_- \ket{\overline{\bullet \bullet \,{\boldsymbol\sigma}_{m-4}^{s}\bullet\bullet}}^{(0)}\,,\qquad\qquad\qquad\qquad\qquad A,B\in\bar{\mathcal K}\,.
\label{eq:S-indcondsholes3}
\end{align} 
The orthogonality condition then reads as 
\begin{align}
&a_{{\boldsymbol\sigma}\bullet}+ a_{\bullet {\boldsymbol\sigma}} =0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{1}_{m-3}\,, \label{eq:condb1S-}\\
&a_{\bullet {\boldsymbol\sigma}\bullet}=0\,, & &\forall\, {\boldsymbol\sigma}\in\mathcal S^{1}_{m-4}\,. \label{eq:condb1S-}
\end{align}
with the constraint \eqref{eq:constraintS-}. These conditions immediately fix
\begin{equation}
a_{{\boldsymbol\sigma}} =0\,, \qquad\qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{1}_{m-2}\,.
\end{equation}
Finally, let us consider the case (b). It is convenient to subdivide it in two additional cases: (b1) $1<s<m-4$; (b2) $s=m-4$. The case (b1) is treated exactly as in the previous sections. Let us consider the case (b2). In this case we have the following orthogonality conditions 
\begin{align}
&a_{{\boldsymbol\sigma}\bullet}  + a_{\bullet {\boldsymbol\sigma}} =0\,,  &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-4}_{m-3}\,, \label{eq:condb21S-}\\
&a_{{\boldsymbol\sigma}\circ} + a_{\circ {\boldsymbol\sigma}} =0\,,  &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-5}_{m-3}\,.\label{eq:condb22S-}\\
&a_{\circ {\boldsymbol\sigma}} + \sum_p a_{\bullet {\boldsymbol\sigma}_p}  =0\,, &&\forall\, {\boldsymbol\sigma}\in\mathcal S^{m-5}_{m-3}\,.\label{eq:condb23S-}
\end{align}
together with the constraint \eqref{eq:constraintS-}. We remind the reader that the sum in \eqref{eq:condb23S-} is over the positions of the two bullets in $\boldsymbol \sigma$ and $\boldsymbol \sigma_p$ is the string obtained from $\boldsymbol \sigma$ by replacing the bullet at position $p$ with a hole. 

A generic coefficient $a_{\boldsymbol\sigma}$ with $\boldsymbol\sigma$ in ${\cal S}^{m-4}_{m-2}$ can be written as 
\begin{equation}
a_{\boldsymbol\sigma} = a_{\underbrace{\circ\ldots\circ}_{\ell_1}\bullet\underbrace{\circ\ldots\circ}_{\ell_2}\bullet\underbrace{\circ\dots\circ}_{\ell_3}}
\end{equation} 
Using the relations \eqref{eq:condb21S-}, \eqref{eq:condb22S-} and the constraint \eqref{eq:constraintS-} we see that it can be non zero only if $\ell_1+\ell_3$ and $\ell_2$ are both odd. In this case, however, we consider \eqref{eq:condb23S-} with $\boldsymbol\sigma=\underbrace{\circ\ldots\circ}_{\ell_1-1}\bullet\underbrace{\circ\ldots\circ}_{\ell_2}\bullet\underbrace{\circ\dots\circ}_{\ell_3}$. This gives 
\begin{equation}
0=a_{\underbrace{\circ\ldots\circ}_{\ell_1}\bullet\underbrace{\circ\ldots\circ}_{\ell_2}\bullet\underbrace{\circ\dots\circ}_{\ell_3}} +a_{\bullet \underbrace{\circ\ldots\circ}_{\ell_1+\ell_2-1}\bullet\underbrace{\circ\dots\circ}_{\ell_3}}+a_{\bullet\underbrace{\circ\ldots\circ}_{\ell_1-1}\bullet\underbrace{\circ\ldots\circ}_{\ell_2+\ell_3}} =a_{\underbrace{\circ\ldots\circ}_{\ell_1}\bullet\underbrace{\circ\ldots\circ}_{\ell_2}\bullet\underbrace{\circ\dots\circ}_{\ell_3}}\,.
\end{equation}
where we used that if $\ell_1+\ell_3$ and $\ell_2$ are odd, both the sets $\{\ell_1-1,\ell_2+\ell_3\}$ and $\{\ell_1+\ell_2-1,\ell_3\}$ contain an even number. We then have 
\begin{equation}
a_{{\boldsymbol\sigma}} =0\,, \qquad\qquad \forall\, {\boldsymbol\sigma}\in\mathcal S^{m-4}_{m-2}\,,
\end{equation}
concluding the proof of (2). 

\subsubsection{Proof of (3)}
To prove the point (3) we show that  
\begin{equation}
{}^{(k)}\braket{\bullet|M^+|\bullet\!\bullet}^{(k)}
\label{eq:relevantmatrixelement}
\end{equation}
has different absolute value for different values of momentum $k\in\{1,2,\ldots (t-1)/2\}$. This is enough because the states $\ket{\bullet}^{(k)}$ and $\ket{\bullet \bullet}^{(k)}$ are unique up to a phase. Namely they are the only states in the representation such that 
\begin{equation}
M_z\ket{\bullet}^{(k)}= (t-2)\ket{\bullet}^{(k)}\,, \qquad\qquad\qquad U\ket{\bullet}^{(k)} =-\ket{\bullet}^{(k)} \,.
\end{equation}
\begin{equation}
M_z\ket{\bullet \bullet}^{(k)}= (t-4)\ket{\bullet \bullet}^{(k)}\,, \qquad\qquad\qquad U\ket{\bullet \bullet}^{(k)} =-\ket{\bullet\bullet}^{(k)} \,.
\end{equation}
This means that if \eqref{eq:relevantmatrixelement} has different absolute value for two representations with momenta $k$ and $p$, there cannot be any transformation $C$ fulfilling \eqref{eq:point3}. Bringing $(M^+)_k$ and $(M^+)_p$ to the same form either makes different the form of  $(M_z)_k$ and $(M_z)_p$ or that of $(U)_k$ and $(U)_p$. A direct calculation gives 
\begin{equation}
{}^{(k)}\braket{\bullet|M^+|\bullet\!\bullet}^{(k)}=1+ e^{\frac{2\pi i k}{t}}\,.
\end{equation}
So we have that ${}^{(k)}\braket{\bullet|M^+|\bullet\!\bullet}^{(k)}$ and ${}^{(p)}\braket{\bullet|M^+|\bullet\!\bullet}^{(p)}$ have the same absolute value if 
\begin{equation}
|\cos\frac{\pi k}{t}|=|\cos\frac{\pi p}{t}|\,,\qquad\qquad k,p=1,...,t-1\,,
\end{equation}
which is fulfilled only for $p=k$ and $p=t-k$. This concludes the proof. }

\section{Results in the even $t$ case}
\label{app:evencase}

Here we state a few properties and observations relevant for the case of {\em even} times $t$. We start by showing the following simple Lemma (supplementing Lemma~\ref{Lemma1} of the previous section)

\begin{Lemma}
\label{Lemma2}

For even $t$ and $t \ge 4$ both projectors $S_\pm$ ({cf}.~\eqref{eq:Sproj}), restricted to momentum $k=t/2$ subspace $V_{t/2}$,  
are non-trivial (non-zero matrices). For $t=2$, $V_1$ is one-dimensional and the projector $S_+$ is non-trivial (with rank 1), while the
projector $S_-$ is a zero matrix.
\end{Lemma}
\begin{proof}
For $t\ge 4$, examples of non-vanishing elements of $S_\pm V_{t/2}$ are $S_\pm \ket{\bullet \circ \bullet\, \bullet}^{(t/2)}$. For $t=2$, we have a single basis element of $V_1$, namely $v=\ket{\bullet\,\circ}^{(1)}$, for which $S_+ v = v$, $S_- v=0$.
\end{proof}
As a consequence, $Y_{t/2}$ and $Y'_{t/2}$ are linearly independent for all even $t\ge 4$, and $Y_1+Y'_1=0$ for $t=2$.
\\\\
Let us now state a few observations concerning eigenvectors of $\mathbb T$ of eigenvalues $\pm1$ for even $t$.

\subsubsection{Additional eigenvectors with eigenvalue 1}
We start by enumerating eigenvectors of eigenvalue $1$, or equivalently, linearly independent operators $A$ simultaneously commuting with $\{M_x,M_y,M_z,U\}$.
Besides to the set of $2t$ operators $\{ Y_k,Y_k';k=0,1,\ldots,t-1\}$, all having ranks which grow exponentially with $t$ (typically as 
$\sim \frac{1}{2t} 2^t$) we generally have an additional rank one operator
\begin{equation}
Z=\ket{\psi}\bra{\psi}
\label{eq:Z}
\end{equation}
such that $Z^2 = Z$. Here the normalized state $\ket{\psi}$, is a particular scrambled fermi sea
\begin{equation}
\ket{\psi}=\frac{1}{2^t} \prod_{\tau =1}^{t/2} \left(1-P_{\tau,\tau+t/2}\right)\ket{\underbrace{\downarrow,\ldots,\downarrow}_{t/2},\underbrace{\uparrow,\ldots,\uparrow}_{t/2}}\,.
\label{eq:psi}
\end{equation}
It is straightforward to chek that this state is a spin singlet $M_\alpha \ket{\psi}=0$. Moreover, it is an eigenvector of $U,\Pi,R$
satisfying ${U\ket{\psi}=-\ket{\psi}}$, $\Pi \ket{\psi}=-\ket{\psi}$, $R\ket{\psi}=(-1)^{t/2} \ket{\psi}$. Thus, $Z$ satisfies Property 2 with $\phi=0$, i.e. it commutes with $\{U,M_x,M_y,M_z\}$, and is orthogonal to (hence linearly independent from) all other general solutions 
\begin{equation}
Z Y_k = Y_k Z = Z Y'_k = Y'_k Z = 0,\quad \forall k.
\end{equation}
The states $Z$, for all even $t$, have momentum $k=t/2$ and are odd under reflection in the sense, $Z \Pi = \Pi Z = -Z$, $Z R = R Z = - Z$. This operator is generically the only additional operator that we identify. For $t=8$ and $t=10$, however, we find a further additional solution in the zero momentum sector.
\\\\
For $t=8$, the additional solution is a rank-3 projector
\begin{equation}
Z' = \sum_{\beta=-1}^1 \ket{\psi_\beta}\bra{\psi_\beta},
\end{equation}
where $\{\psi_\beta\}$ is a triplet of states
\begin{eqnarray}
\ket{\psi_1} &=& \sqrt{2} Y_0 \left( \ket{\uparrow\ua\downarrow\uparrow\downarrow\da\downarrow\da}-\ket{\uparrow\ua\downarrow\da\uparrow\downarrow\da\downarrow}+\ket{\uparrow\ua\downarrow\da\downarrow\uparrow\downarrow\da}-\ket{\uparrow\ua\downarrow\da\downarrow\da\uparrow\downarrow}\right), \nonumber \\
\ket{\psi_0} &=& 2 Y_0 \left( \ket{\uparrow\ua\downarrow\uparrow\downarrow\uparrow\downarrow\da} - \ket{\uparrow\ua\downarrow\da\uparrow\downarrow\uparrow\downarrow} \right), \\
\ket{\psi_{-1}} &=& \sqrt{2} Y_0 \left( \ket{\downarrow\da\uparrow\downarrow\uparrow\ua\uparrow\ua}-\ket{\downarrow\da\uparrow\ua\downarrow\uparrow\ua\uparrow}+\ket{\downarrow\da\uparrow\ua\uparrow\downarrow\uparrow\ua}-\ket{\downarrow\da\uparrow\ua\uparrow\ua\downarrow\uparrow}\right). \nonumber
\end{eqnarray}
One can check straightforwardly that $M_z \ket{\psi_\beta} = -2 \beta \ket{\psi_\beta}$,
$(M_x^2+M_y^2+M_z^2)\ket{\psi_\beta} = 8 \ket{\psi_\beta}$, meaning that $\ket{\psi_\beta}$ indeed form a spin-1 triplet, and $U$ acts as a parity
\begin{equation}
U\ket{\psi_\beta} = -(-1)^\beta \ket{\psi_\beta}.
\end{equation}
This solution, again normalized such that $Z'^2 = Z'$, is independent from all the other solutions 
\begin{equation}
ZZ'=Z'Z=Z' Y_k = Y_k Z' = Z' Y'_k = Y'_k Z' = 0,\quad \forall k,
\end{equation}
and satisfies $\Pi Z' = Z' \Pi  = Z'$, $R Z' = Z' R = -Z'$.
\\\\
For $t=10$, the additional solution is again a rank-1 projector,
\begin{equation}
Z'' = \ket{\chi}\bra{\chi}
\end{equation}
normalized as $Z''^2 = Z''$, with
\begin{equation}
\ket{\chi}=\frac{1}{\sqrt{30}}S_- Y_0\bigl(\ket{\uparrow\ua\uparrow\ua\downarrow\uparrow\downarrow\da\downarrow\da}-\ket{\uparrow\ua\uparrow\ua\downarrow\uparrow\downarrow\da\downarrow\da}-\ket{\uparrow\ua\uparrow\downarrow\uparrow\ua\downarrow\da\downarrow\da}  + 
\ket{\uparrow\ua\uparrow\downarrow\da\uparrow\ua\downarrow\da\downarrow}-\ket{\uparrow\ua\downarrow\uparrow\downarrow\uparrow\downarrow\uparrow\downarrow\da}-\ket{\uparrow\ua\downarrow\uparrow\downarrow\uparrow\downarrow\da\uparrow\downarrow}\bigr),
\label{eq:chi}
\end{equation}
again being a spin singlet $M_\alpha\ket{\chi}=0$, and an eigenvector of $U,\Pi,R$, satisfying $U\ket{\chi}=\ket{\chi}$, $\Pi\ket{\chi} = \ket{\chi}$, $R\ket{\chi} = -\ket{\chi}$.
As in the above cases, it is easy to check the linear independence (orthogonality) with respect to the other solutions
\begin{equation}
ZZ''=Z''Z=Z'' Y_k = Y_k Z'' = Z'' Y'_k = Y'_k Z'' = 0,\quad \forall k.
\end{equation}
For higher even $t$ we have found no additional solutions besides (\ref{eq:Z}), hence we conjecture that for $t\ge 11$ we have exactly $2t+1$ independent eigenvectors of $\mathbb T$ with eigenvalue $1$.

\subsubsection{Eigenvectors with eigenvalue -1}

As we have shown, eigenvectors of $\mathbb T$ of eigenvalue -1 are only possible for even $t$. Here, however, we argue that also for even $t$ eigenvalues -1 are exceptional and can appear only in finitely many cases. For example, a linearly independent pair of operators $A_\pm$ satisfying Property 2 with $\phi=\pi$ can be obtained with the ansatz
\begin{equation}
A_+ = \ket{\psi_+}\bra{\psi_-},\qquad
A_- = \ket{\psi_-}\bra{\psi_+},
\end{equation}
where vectors $\ket{\psi_\pm}$ are both spin singlets $M_\alpha \ket{\psi_\pm}=0$, and have opposite eigenvalues of $U$, $U\ket{\psi_\pm} = \pm \ket{\psi_\pm}$.

This happens in two cases
\begin{itemize}
\item[(i)] $t=6$; where the projector $S_- Y_0$ has rank one so it can be written as $S_- Y_0 = \ket{\psi_+}\bra{\psi_+}$, while the second state in the pair, $\ket{\psi_-}$, is given by (\ref{eq:psi}).
\item[(ii)] $t=10$; where the first state $\ket{\psi_+}=\ket{\chi}$ is given by (\ref{eq:chi}), while the second state in the pair, $\ket{\psi_-}$, is again given by (\ref{eq:psi}).
\end{itemize}
For higher even $t$ up to $t=16$, we have found no other rank-1 operators commuting with $\{M_x,M_y,M_z,U\}$, besides (\ref{eq:Z}), so no other eigenvalue $-1$ eigenoperators can be constructed. Thus we conjecture that there are no other eigenvectors of eigenvalue $-1$.

Note that the explicit cases discussed above, together with Property 4, completely explain the empirical Table~I reported in the main text. 

\section{Diagonalization of the Integrable (transverse field) Kicked Ising Model}
\label{app:integrablecase}

In this section we consider a non-trivial integrable limit of the Floquet operator (3), namely the case $\boldsymbol h=0$. In this case this operator can be written in terms of a free fermionic Hamiltonian. One defines the fermionic operators through a Jordan-Wigner transformation as follows 
\begin{equation}
c_l^\dag = \prod_{j=1}^{l-1} \sigma_j^x \sigma_l^-\,,\qquad\qquad\qquad c_l = \prod_{j=1}^{l-1} \sigma_j^x \sigma_l^+\,.
\end{equation}
Here we introduced
\begin{equation}
\sigma_j^-=\frac{1}{2}(\sigma_j^z-i\sigma_j^y)\,,\qquad\qquad\qquad\sigma_j^+=\frac{1}{2}(\sigma_j^z+i\sigma_j^y)\,.
\end{equation}
In terms of these fermions the Floquet operator can be written as  
\begin{equation}
U_{\rm KI}[0]= e^{i H_{\rm eff}(J,b)}\,,
\end{equation}
with 
\begin{equation}
H_{\rm eff}(J,b)=\frac{e^{i \pi N}+1}{2}H^{\rm e}(J,b) \frac{e^{i \pi N}+1}{2} + \frac{e^{i \pi N}-1}{2}H^{\rm o}(J,b) \frac{e^{i \pi N}-1}{2}\,,\qquad\qquad N=\sum_{i=1}^L c^\dag_ic_i\,.
\label{eq:Heff}
\end{equation}
Here $({e^{i \pi N}\pm1})/{2}$ respectively projects on the sectors with even and odd number of particles. Note that in terms of the spin operators $\{\sigma_i^\alpha\}$ we have 
\begin{equation}
e^{i \pi N}=\prod_{j=1}^L  (1-2 c^\dag_jc_j)=\prod_{j=1}^L  \sigma_j^x\,,
\end{equation}
so $e^{i \pi N}$ corresponds to a spin-flip transformation. The Hamiltonians $H^{\rm e}(J,b), H^{\rm o}(J,b) $ can be diagonalised by a Bogoliubov transformation: the final result reads as
\begin{equation}
H^{\rm e(o)}(J,b) =\sum_{k\in\rm NS(R)} \epsilon(k) \left(b^\dag_kb^{\phantom{\dag}}_k-\frac{1}{2}\right)\,,
\end{equation}
with $\rm NS(R)$ representing Neveu-Schwartz (Ramond) sectors
\begin{align}
k\in{\rm R}\qquad &\Rightarrow\qquad k=\frac{2\pi}{L}n\,,& &n \in\mathbb{Z}\cap[0,L[\,,\\
k\in{\rm NS}\qquad &\Rightarrow\qquad k=\frac{2\pi}{L}\left(n+\frac{1}{2}\right)\,,& &n \in\mathbb{Z}\cap[0,L[\,,
\end{align}
 and 
\begin{equation}
\epsilon(k)\equiv -\cos^{-1}(\cos(2b)\cos(2J)+\cos(k)\sin(2J)\sin(2b))\!\!\!\!\mod 2\pi \,.
\end{equation}
A complete basis of the Hilbert space is constructed by defining two states 
\begin{equation}
\ket{0}_{\rm NS},\quad\ket{0}_{\rm R}\,,
\end{equation} 
such that 
\begin{equation}
b_k \ket{0}_{\rm R}=0\quad\textrm{if}\quad k\in{\rm R},\qquad\qquad\qquad\qquad b_k \ket{0}_{\rm NS}=0\quad\textrm{if}\quad k\in{\rm NS}\,.
\end{equation}
For $L$ odd we have 
\begin{align}
e^{i \pi N} \ket{0}_{\rm NS}&=\text{sign}(b+J)\ket{0}_{\rm NS}\,, & e^{i \pi N} \ket{0}_{\rm R}&=\text{sign}(b-J)\ket{0}_{\rm R}\,,\\
\Pi_L \ket{0}_{\rm NS}&=(-1)^{\theta(-b-J)}\ket{0}_{\rm NS}\,, & \Pi_L \ket{0}_{\rm R}&= \ket{0}_{\rm R}\,,
\end{align}
where $\Pi_L$ is the shift operator (\emph{cf}. Eq. (21) of the main text) on a chain of $L$ sites and $\theta(x)$ is the step function. The basis is constructed acting with the operators $b^\dag_k$ on $\ket{0}_{\rm NS},\ket{0}_{\rm R}$ keeping only the vectors in the R sector with negative eigenvalue of $e^{i \pi N}$ and those in the NS sector with positive eigenvalue of $e^{i \pi N}$. In the case $b <-|J|$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n+1}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n+1} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,,\quad n,m\in\mathbb{N}\cap[0,L/2]\,, 
\end{equation}
In the case $-J<b < J$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,,\quad n,m\in\mathbb{N}\cap[0,L/2]\,, 
\end{equation}
In the case $J<b < -J$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n+1}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n+1} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m+1}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m+1} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,, \quad n,m\in\mathbb{N}\cap[0,L/2]\,,
\end{equation}
Finally for $b >|J|$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m+1}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m+1} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,, \quad n,m\in\mathbb{N}\cap[0,L/2]\,.
\end{equation}
For $L$ even we have 
\begin{align}
e^{i \pi N} \ket{0}_{\rm NS}&=\ket{0}_{\rm NS}\,, & e^{i \pi N} \ket{0}_{\rm R}&=\text{sign}(b+J)\text{sign}(b-J)\ket{0}_{\rm R}\,,\\
\Pi_L \ket{0}_{\rm NS}&=\ket{0}_{\rm NS}\,, & \Pi_L \ket{0}_{\rm R}&= (-1)^{\theta(-b-J)}\ket{0}_{\rm R}\,.
\end{align}
In the case $b <-|J|$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m+1}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m+1} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,,\quad n,m\in\mathbb{N}\cap[0,L/2]\,, 
\end{equation}
In the case $-J<b < J$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,,\quad n,m\in\mathbb{N}\cap[0,L/2]\,, 
\end{equation}
In the case $J<b < -J$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,, \quad n,m\in\mathbb{N}\cap[0,L/2]\,,
\end{equation}
Finally for $b >|J|$ we find 
\begin{equation}
\ket{k_1, \ldots, k_{2n}}_{\rm NS} = \prod_{\substack{i=1\\ \\  k_i \in \rm NS}}^{2n} b^{\dagger}_{k_i}\ket{0}_{\rm NS}\,,\quad \ket{k_1, \ldots, k_{2m+1}}_{\rm R} = \prod_{\substack{i=1\\ \\  k_i \in \rm R}}^{2m+1} b^{\dagger}_{k_i}\ket{0}_{\rm R}\,, \quad n,m\in\mathbb{N}\cap[0,L/2]\,.
\end{equation}

\subsection{Spectrum at the self dual points}
\label{app:integrablecasediff}
Let us consider the self dual points $J=s \pi/4$ and $b=r \pi/4$ where $r,s\in\{\pm 1\}$. For these points the dispersion relation drastically simplifies 
\begin{equation}
\epsilon(k)= -\cos^{-1}(r s \cos(k))\!\!\!\!\mod 2\pi =\left(rs|\pi-k|-\pi \frac{(rs+1)}{2}\right)\!\!\!\!\mod 2\pi\,.
\label{eq:simpledispersion}
\end{equation}
Writing the quantisation conditions explicitly we have 
\begin{equation}
\epsilon(k_n)=\frac{2\pi}{L}\left(rs\left|\frac{L}{2}-n-\frac{\sigma}{2}\right|-\frac{L}{2} \frac{(rs+1)}{2}\right)\!\!\!\!\mod 2\pi\,,
\end{equation}
where $\sigma=1$ in the NS sector and $\sigma=0$ in the R sector. This form implies 
\begin{equation}
\epsilon(k_n)=\frac{2\pi}{L} \left(m+\frac{\sigma}{2}+ (L\!\!\!\!\!\mod2)  \frac{(rs-1)}{4}\right)\,, \qquad m\in\mathbb{N}\cap[0,L[\,.
\end{equation}
In words, depending on the sector, on the parity of $L$, and on the sign of $rs$ the rescaled dispersion ${L}\epsilon(k_n)/{2\pi}$ is either an integer or a semi-integer number in $[0,L]$. Using this expression and the basis constructed above we can explicitly find the eigenvalues of the Floquet operator (3), it reads as 
\begin{equation}
\varphi_{m,\rm r}= e^{- i e_{m,\rm r}}\,,\qquad\qquad{\rm r} \in\{{\rm NS}, {\rm R}\}\,,\qquad\qquad m\in\{1,\ldots,2^{L-1}\}\,.
\end{equation}
Here we defined the quasi-energy
\begin{equation}
e_{m,\rm r}=\frac{2\pi}{L} n_m + E_{\rm r} +\begin{cases}
0 & L\quad\text{even} \\
\frac{\pi (rs-1)}{4 L}  - \frac{\pi (rs-1)}{4 L } \eta_{\rm r}& L\quad\text{odd}\\
\end{cases}\,,\qquad n_m\in\mathbb{N}\cap[0,L[\,.
\end{equation}
where we introduced the variable $\eta_{\rm r}$ such that $\eta_{\rm R}=-1$ and $\eta_{\rm NS}=1$. Moreover, we introduced the ground state energies $E_{\rm R},E_{\rm NS}$ in the two sectors, defined by 
\begin{equation}
E_{\rm r}=-\frac{1}{2}\sum_{\substack{k\in {\rm r}}} \epsilon(k)\,.
\end{equation} 
These expressions are explicitly evaluated using the form \eqref{eq:simpledispersion} of the dispersion relation, the result reads as 
\begin{equation}
E_{\rm r}=\frac{\pi L}{4}+
\begin{cases}
0 & L\quad\text{even} \\
\frac{rs\pi}{4L} \eta_{\rm r}& L\quad\text{odd}\\
\end{cases}\,.
\end{equation}
Putting all together we have 
\begin{equation}
e_{m,\rm r}=\frac{2\pi}{L} n_m + \frac{\pi L}{4} +\begin{cases}
0 & L\quad\text{even} \\
\frac{\pi (rs-1)}{4 L}  + \frac{\pi}{4 L } \eta_{\rm r}& L\quad\text{odd}\\
\end{cases}\,,\qquad n_m\in\mathbb{N}\cap[0,L[\,.
\label{eq:explicit}
\end{equation}
A direct consequence of \eqref{eq:explicit} is that quasi-energy differences are given by  
\begin{equation}
e_{m,\rm r}-e_{m',\rm r'} = \frac{2\pi}{L} (n_m-n_{m'})+ \begin{cases}
0 & L\quad\text{even} \\
\frac{\pi}{4 L } (\eta_{\rm r}-\eta_{\rm r'})& L\quad\text{odd}\\
\end{cases}\,.
\label{eq:energydifference}
\end{equation}


\section{Numerical methods}
\label{app:numerics}

Figure 2 is produced using direct time propagation of all basis states, namely we computed   
\begin{equation}
\braket{{\boldsymbol{s}}|U_{\rm KI}^t |{\boldsymbol{s}}} = \braket{{\boldsymbol{s}}|(U_{\rm K}U_{\rm I})^t |{\boldsymbol{s}}}\,,
\label{eq:xx}
\end{equation}
for each element $\ket{\boldsymbol{s}}$ of the ``computational basis'' composed of joint eigenstates of $\{\sigma^z_j\}$. $U_{\rm I}$ is diagonal in the computational basis, 
so its entries are stored in a $2^L$-sized register and used to multiply vectors repeatedly. The kick part $U_{\rm K}$ can be expressed as a simple tensor product of $2\times 2$ matrices
\begin{equation}
 U_{\rm K}=\prod_j e^{i b \sigma^x_j}\equiv (\mathbbm{1}\cos b + i \sigma^x \sin b)^{\otimes L},
\end{equation}
where for $b=\pi/4$  
\begin{align}
U_{\rm K}=2^{-L/2} 
\begin{bmatrix} 
1& i \\
i & 1
\end{bmatrix}^{\otimes L} .
\end{align}
The matrix element (\ref{eq:xx}) can thus be computed in ${\cal O}(t L 2^L)$ operations, and the entire trace (spectral form factor) in ${\cal O}(t L 4^L)$ operations, which is advantageous to full diagonalization for $t\ll 2^L$. Using this algorithm we compute 
\begin{equation}
K(t)=\sum_{\{s_j\in\{\pm1\}\}} \braket{{\boldsymbol s}|U_{\rm KI}^t[\boldsymbol{h}] |{\boldsymbol{s}}}\,,
\end{equation} 
for specific realizations of disorder $\boldsymbol{h}=(h_1,\ldots,h_L)$, and then average over many realizations of disorder.

Table~I is produced by starting with a few random vectors of dimension $4^t$ and acting on them repeatedly with the transfer matrix $\mathbb T$, as in the ``power method''. The action of the transfer matrix can again be implemented efficiently as a multiplication by the eigenvalues of the diagonal part and kicks. After enough iterations the vectors are projected to the subspaces with the eigenvalues $\pm 1$. We extend this method to compute the gap shown in Fig. 3. We start with the random vector, make it orthogonal to $\pm 1$ sectors and look how the norm of this vector shrinks. After $n$ iterations, for large enough $n$, the norm changes by a factor of $|\lambda|^n$, where $\lambda$ is the second largest eigenvalue.



