\section{Renormalized $r^{\an}$-potential}
\subsection{Definition
Suppose $\a\le0$ and $x\in\interior\Om$. 
Fix a positive constant $R$ with $R<\textrm{dist}(x,\partial\Om)$. 
If we denote an $\n$-ball with center $x$ and radius $r>0$ by $B_r(x)$, we have 
\setlength\arraycolsep{1pt}
\[\begin{array}{rcl}
\displaystyle \int_{B_R(x)\setminus {B}_\e(x)}{|x-y|}^{\an}\,d\mu(y)
&=&\displaystyle \left\{
\begin{array}{ll}
\displaystyle A(S^{\n-1})\log\frac{R}{\e} & \hspace{0.5cm}\mbox{\rm if }\>\a=0\,,\\[1mm]
\displaystyle \frac{A(S^{\n-1})}{\a}\left(R^{\a}-\e^{\a}\right)& \hspace{0.5cm}\mbox{\rm if }\>\a<0\,,
\end{array}
\right.
\end{array}\]
where $A(S^{\n-1})$ is the volume of the $(n-1)$-dimensional unit sphere $S^{\n-1}$: 
\[
\displaystyle A(S^{\n-1})=\frac{2\pi^{\frac{\n}{2}}}{\varGamma(\frac{\n}2)}
=\left\{
\begin{array}{ll}
\displaystyle \frac{2\pi^{k+1}}{k!} & \hspace{0.5cm}\mbox{\rm if }\>\n-1=2k+1\,,\\
\displaystyle \frac{2^{k+1}\pi^{k}}{(2k-1)(2k-3)\cdots1} & \hspace{0.5cm}\mbox{\rm if }\>\n-1=2k\,.
\end{array}
\right.
\]
As $\Om\setminus {B}_\e(x)=(\Om\setminus B_R(x))\,\cup\, (B_R(x)\setminus {B}_\e(x))$ and $\Om\setminus B_R(x)$ is independent of $\e$, if we expand $\int_{\Om\setminus {B}_\e(x)}{|x-y|}^{\an}\,d\mu(y)$ in a series in $\frac1\e$, we have only one divergent term which does not depend on the point $x$ and the set $\Om$. 
Thus we are lead to the following defintion: 
\begin{definition}\label{def_renormalization_Riesz} \rm 
A compact set which is a closure of its interior is called a {\em body} (\cite{Ga}). 
We always assume that $\Om$ is a body with a piecewise $C^1$ boundary $\partial\Om$ in what follows. 

(1) Let $\Om$ be a body in $\RR^\n$ with a piecewise $C^1$ boundary. 
Define $V^{(\a)}_\Om
by the following. 

\begin{enumerate}
\item[(i)] When $\a\le0$ and $x\in\interior\Om$, define $V^{(\a)}_\Om(x)$ by 
\begin{equation}\label{def_V_a}
\begin{array}{rcl}
V^{(\a)}_\Om(x
&=&\displaystyle \lim_{\e\to+0}\left(\int_{\Om\setminus B_\e(x)}{|x-y|}^\an\,d\mu(y)-\frac{A(S^{\n-1})}{-\a}\cdot\frac1{\e^{-\a}}\right)
\end{array}
\end{equation}
for $\a<0$, and 
\begin{equation}\label{def_V_0}
\begin{array}{rcl}
V^{(0)}_\Om(x
&=&\displaystyle \lim_{\e\to+0}\left(\int_{\Om\setminus B_\e(x)}{|x-y|}^{-\n}\,d\mu(y)-A(S^{\n-1})\log\frac1\e\right)
\end{array}
\end{equation}
for $\a=0$, 
and call them the {\em renormalization of $r^\an$-potential of $\Om$}. 

\item [(ii)] When $\a>0$ or $x$ is not in $\Om$ we put 
$$V^{(\a)}_\Om(x)=\int_{\Om}{|x-y|}^\an\,d\mu(y)\,.$$
\end{enumerate}

(2) Let $-\Om$ denote the same space $\Om$ with the reversed orientation. 
Define $V^{(\a)}_{-\Om}(x)=-V^{(\a)}_\Om(x)$. 

Let $\Om_j$ $(1\le j \le k)$ be a body with a piecewise $C^1$ boundary 
so that $\interior\Om_i\cap\interior\Om_j=\emptyset$ $(i\ne j)$. 
Then define $V^{(\a)}_{\cup_j\Om_j}(x)=\sum_jV^{(\a)}_{\Om_j}(x)$. 
\end{definition}

\begin{remark}\label{remark_log}\rm
In our study, if we put $\frac1ar^a=\log r$ $(r>0)$ when $a=0$ in our formulae for general cases, we obtain those for special cases, although $\log r=\lim_{a\to0}\frac1a(r^a-1)$ in fact. 
Such examples can be found in  
\eqref{def_V_a} and \eqref{def_V_0}, \eqref{f_Va_epsilon} and \eqref{f_V0_epsilon}, \eqref{f_V_ball}, \eqref{V_alpha_boundary} and \eqref{V0_boundary}, \eqref{V_alpha_\n=2_contour} and \eqref{V0_\n=2_contour}, \eqref{eq_div_V_alpha_boundary} and \eqref{eq_div_V_0_boundary}, \eqref{V^a_int_S^m-1} and \eqref{V^0_int_S^m-1},
and Theorem \ref{thm_radial_general}. 
\end{remark}

The renormalization in the case when $m=2$ and $\a=-2$ was given by Auckly and Sadun with more generality in \cite{AS}, where they studied surface energy. 

We remark that when $\a=\n$ we have $V^{(\n)}_{\Om}(x)=\textrm{Vol}(\Om)$ for any $x$. But when we are concerned with $r^{\an}$-centers, it is natural to use the log potential for $V^{(\n)}_{\Om}$. 

\subsection{Basic properties}

\begin{proposition}
\begin{enumerate}
\item The map $V_{\Om}^{(\a)}$ inherits symmetry from $\Om$, i.e. if $g$ is an isometry of $\RR^\n$ then $V_{g\cdot\Om}^{(\a)}(g\cdot x)=V_{\Om}^{(\a)}(x)$. 
\item Under a homothety $\RR^\n\ni x\mapsto k x\in \RR^\n$ $(k>0)$, 
\[
V_{k\Om}^{(\a)}(kx)=\left\{
\begin{array}{ll}
\displaystyle k^{\a}V_{\Om}^{(\a)}(x) & \hspace{0.3cm}\mbox{if $\a\ne0$},\\%,\n
\displaystyle V_{\Om}^{(0)}(x)+A(S^{\n-1})\log k& \hspace{0.3cm}\mbox{if $\a=0$ and $x\in\interior\Om$,}\\[1mm]
\displaystyle V_{\Om}^{(0)}(x)& \hspace{0.3cm}\mbox{if $\a=0$ and $x\not\in\Om$.}
\end{array}
\right.
\]
\end{enumerate}
\end{proposition}

\begin{proof} 
(2) follows directly from the definition, or from Theorem \ref{prop_boundary_integral_formula}. \end{proof}
\begin{lemma}\label{lemma_X-Y}
Let $X$ and $Y$ be subsets of $\RR^\n$. 
Define 
$$X-Y=(X\setminus(X\cap Y))\cup-(Y\setminus(X\cap Y)),$$
where the second term is equipped with the reverse orientation (figure \ref{X-Y}). 

If $x\in\interior{\Om}_1\cap\interior{\Om}_2$ or $x\in\Om_1^{\>c}\cap\Om_2^{\>c}$ then 
\[V^{(\a)}_{\Om_1-\Om_2}(x)=V^{(\a)}_{\Om_1}(x)-V^{(\a)}_{\Om_2}(x)\]
for any $\a$. 
\end{lemma}
\begin{figure}[htbp]
\begin{center}
\includegraphics[width=.35\linewidth]{X-Y.ps}
\caption{$X-Y$. The dark (light) part with positive (resp. negative) orientation.}
\label{X-Y}
\end{center}
\end{figure}
\begin{proof}
This is because
\[
\Om_1-\Om_2=(\Om_1\setminus B_\e(x))-(\Om_2\setminus B_\e(x))
\]
for sufficiently small $\e$ when $x\in\interior{\Om}_1\cap\interior{\Om}_2$. 
\end{proof}

We give elementary statements on the renormalization process of $V^{(\a)}_\Om$. 
\begin{proposition}
Suppose $x\in\interior\Om$. 
\begin{enumerate}
\item We have 
\begin{eqnarray}
V^{(\a)}_\Om(x)&=&\displaystyle \int_{\Om- B_\e(x)}{|x-y|}^\an\,d\mu(y)-\frac{A(S^{\n-1})}{-\a}\cdot\frac1{\e^{-\a}} \hspace{0.5cm}(\a\ne0),\label{f_Va_epsilon} \\
V^{(0)}_\Om(x)&=&\displaystyle \int_{\Om- B_\e(x)}{|x-y|}^{-\n}\,d\mu(y)-A(S^{\n-1})\log\frac1\e \hspace{0.86cm}(\a=0)\, \label{f_V0_epsilon}
\end{eqnarray}
for any $\e>0$. 
In particular, \eqref{def_V_a} and \eqref{def_V_0} hold even without taking the limit if $\e<\textrm{\rm dist}(x,\partial\Om)$.
\item If $\a<0$ we have 
\begin{equation}
V^{(\a)}_\Om(x)= -\int_{\Om^{c}}{|x-y|}^{\an}\,d\mu(y) \hspace{1cm}(\a<0) \label{f_Va_complement}
\end{equation}
Thus the renormalization can be obtained by taking the complement of the domain when $\a<0$. 
\end{enumerate}
\end{proposition}

We remark that \eqref{f_V0_epsilon} is equivalent to 
\begin{equation}\label{f_V0_R}
V^{(0)}_\Om(x)=A(S^{\n-1})\log R-\int_{B_R(x)-\Om}{|x-y|}^{-\n}\,d\mu(y) 
\end{equation}
for any $R>0$. 
\begin{proof}
First note that the (renormalized) potential of a ball at the center is given by 
\begin{equation}\label{f_V_ball}
V^{(\a)}_{B_r(x)}(x)=\left\{
\begin{array}{ll}
\displaystyle \frac{A(S^{\n-1})}{\a}\cdot r^{\a} &\hspace{0.5cm} (\a\ne0),\\[3mm]
\displaystyle A(S^{\n-1})\log r &\hspace{0.5cm} (\a=0).
\end{array}\right.
\end{equation}

(1) By Lemma \ref{lemma_X-Y} we have 
$$
V^{(\a)}_\Om(x)=V^{(\a)}_{\Om-B_\e(x)}(x)+V^{(\a)}_{B_\e(x)}(x),
$$
which implies \eqref{f_Va_epsilon} and \eqref{f_V0_epsilon}. 

(2) Suppose $\a<0$ and $x\in\interior\Om$. Direct calculation shows 
$$
\int_{\RR^\n\setminus {B}_\e(x)}{|x-y|}^\an\,d\mu(y)
=-\frac{A(S^{\n-1})}{\a}\cdot{\e^{\a}}
=-V^{(\a)}_{B_\e(x)}(x),
$$
and therefore we have 
\[\begin{array}{rcl}
V^{(\a)}_\Om(x)&=&\displaystyle \int_{\Om- B_\e(x)}{|x-y|}^\an\,d\mu(y)-\int_{\RR^\n- {B}_\e(x)}{|x-y|}^\an\,d\mu(y) \\[4mm]
&=&\displaystyle -\int_{\Om^{c}}{|x-y|}^{\an}\,d\mu(y)\,.
\end{array}\]
\end{proof}
\begin{corollary}\label{cor_Omega_1_subset_Omega_2}
Suppose $\Om_1\subset\Om_2$. 
If $\a>0$ or $x\in\interior{\Om_1}$ or $x\in\Om_2^c$ then $V_{\Om_1}^{(\a)}(x)\le V_{\Om_2}^{(\a)}(x)$. 
\end{corollary}

\begin{lemma}\label{lem_boundary} 
Let $V_{\Om}^{(\a)}\big|_{\interior\Om}$ and $V_{\Om}^{(\a)}\big|_{\Om^{c}}$ denote the restrictions of $V_{\Om}^{(\a)}$ to the interior and the complement of $\Om$ respectively. 
\begin{enumerate}
\item If $\a>0$ then $V_{\Om}^{(\a)}>0$ on $\RR^\n$. 
\item $V_{\Om}^{(\a)}\big|_{\Om^{c}}>0$ for any $\a$. 
If $\a<\n$ then $\displaystyle \lim_{|x|\to+\infty}V_{\Om}^{(\a)}(x)=0$. 
\item If $\a<0$ then $V_{\Om}^{(\a)}\big|_{\interior\Om}<0$. 
\end{enumerate}
\end{lemma}
\begin{proof}
(3) follows from the formula \eqref{f_Va_complement}. 
\end{proof}
\subsection{Boundary integral expressions and derivatives}
\begin{theorem}\label{prop_boundary_integral_formula}
If $x\not\in\partial\Om$ 
then $V_{\Om}^{(\a)}(x)$ can be expressed by the boundary integral on $\partial\Om$ as 
\begin{eqnarray}
V_{\Om}^{(\a)}(x)&=&\displaystyle \displaystyle \frac1{\a}\int_{\partial\Om} {|x-y|}^{\an}(y-x)\cdot n\,d\sigma (y) \hspace{0.5cm} (\a\ne0),\label{V_alpha_boundary}\\[1mm]
V_{\Om}^{(0)}(x)&=&\displaystyle \displaystyle \int_{\partial\Om} \frac{\log|x-y|}{{|x-y|}^\n}\,(y-x)\cdot n\,d\sigma (y) \hspace{0.9cm} (\a=0), \label{V0_boundary}
\end{eqnarray}
where $n$ is a unit outer normal vector to $\partial\Om$ at $y$ and $\sigma$ denotes the standard Lebesgue measure of $\partial\Om$.
\end{theorem}

Especially, when $\n=2$, $V_{\Om}^{(\a)}(x)$ $(\a\ne0)$ can be expressed by the contour integral along $\partial\Om$ by 
\begin{equation}\label{V_alpha_\n=2_contour}
\begin{array}{rcl}
V_{\Om}^{(\a)}(x)&=&\displaystyle \frac1{\a^2}\oint_{\partial\Om} \left(\nabla_y{|x-y|}^\a\right)\cdot n\,ds \hspace{2.0cm} (\a\ne0)\\[4mm]
&=&\displaystyle \frac1{\a}\oint_{\partial\Om} {|x-y|}^{\a-2}\left((y_1-x_1)\,dy_2-(y_2-x_2)\,dy_1\right)\,  
\end{array}
\end{equation}
where $s$ is the arc-length of $\partial \Om$, and $V_{\Om}^{(0)}(x)$ by
\begin{equation}\label{V0_\n=2_contour}
\begin{array}{rcl}
V_{\Om}^{(0)}(x)&=&\displaystyle \oint_{\partial\Om} \log|x-y|\,(\nabla_y\log|x-y|)\cdot n\,ds \\[4mm]
&=&\displaystyle \oint_{\partial\Om} \frac{\log|x-y|}{{|x-y|}^2}\left((y_1-x_1)\,dy_2-(y_2-x_2)\,dy_1\right)\,.
\end{array}
\end{equation}

The author thanks Kazuhiro Kurata for informing him of the first formula of \eqref{V0_\n=2_contour}. 

We remark that the $1$-form in \eqref{V0_\n=2_contour} can be expressed as $-\log|x-y|\,\Im\mathfrak{m}\frac{dy}{x-y}$ if we consider $x$ and $y$ as points in $\mathbb{C}$. 
\begin{proof} Put $r=|x-y|$. 

(1-i) Suppose $\a<0$ and $x\in\interior\Om$. 
Note that 
\begin{equation}\label{eq_div_V_alpha_boundary}
\textrm{div}_y\left(\frac1{\a}r^{\an}(y-x)\right
=r^\an.
\end{equation}
Therefore, for enough small $\e>0$, 
\[\begin{array}{rcl}
\displaystyle \int_{\Om\setminus B_\e(x)}r^\an\,d\mu(y)
&=&\displaystyle \frac1{\a}\int_{\partial\Om} r^{\an}(y-x)\cdot n\,d\sigma (y)
-\frac1{\a}\int_{\partial B_\e(x)} r^{\an}(y-x)\cdot n\,d\sigma (y) \\[4mm]
&=&\displaystyle \frac1{\a}\int_{\partial\Om} r^{\an}(y-x)\cdot n\,d\sigma (y)
-\frac{A(S^{\n-1})\,\e^\a}{\a}\,.
\end{array}\]
Then the formula \eqref{f_Va_epsilon} implies \eqref{V_alpha_boundary}. 

\smallskip
(1-ii) The case when $x\not\in\Om$ or when $\a>0$
can be proved in the same way if we forget the renormalization term. 

\smallskip
(2) The case when $\a=0$ can be proved in the same way using 
\begin{equation}\label{eq_div_V_0_boundary}
\textrm{div}_y\left((r^{-\n}{\log r})(y-x)\right
=r^{-\n}
\end{equation}
and \eqref{f_V0_epsilon}
\end{proof}

\begin{proposition}\label{prop_derivative_boundary} 
{\rm (1)} 
If $x=(x_1, \ldots, x_\n)\not\in\partial\Om$
then $\displaystyle \frac{\partial V_{\Om}^{(\a)}}{\partial x_j}(x)$ can be expressed by the boundary integral on $\partial\Om$ as 
\begin{equation}\label{formula_derivative_boundary}
\frac{\partial V_{\Om}^{(\a)}}{\partial x_j}(x)=-\int_{\partial\Om}{|x-y|}^{\an}\,e_j\cdot n\,d\sigma (y)
\end{equation}
for any $j$ $(1\le j\le \n)$ and for any $\a$, 
where $n$ is a unit outer normal vector to $\partial\Om$ at $y$, $e_j$ is the $j$-th unit vector of $\RR^\n$, and $\sigma$ denotes the standard Lebesgue measure of $\partial\Om$. 

\smallskip
{\rm (2)} If $\a>1$ then \eqref{formula_derivative_boundary} holds and becomes continuous on entire $\RR^\n$. 
Therefore $V^{(\a)}_\Om$ is of class $C^1$ on $\RR^\n$ if $\a>1$.  
\end{proposition}
\begin{proof}
(1) Put $r=|x-y|$. 
Note that 
$$
\frac{\partial \, r^{\an}}{\partial x_j}=-\frac{\partial \, r^{\an}}{\partial y_j}=-\textrm{div}_y\left(r^\an \,e_j\right)
$$

(i) Assume $x\not\in\Om$. 
Then 
\[
\begin{array}{rcl}
\displaystyle \frac{\partial V_{\Om}^{(\a)}}{\partial x_j}(x)
&=&\displaystyle \int_\Om\frac{\partial \, r^{\an}}{\partial x_j}\,d\mu(y)
=-\int_\Om\textrm{div}_y\left(r^\an \,e_j\right)\,d\mu(y
=\displaystyle -\int_{\partial\Om}r^\an \,e_j\cdot n\,d\sigma (y) 
\end{array}
\]
as is required. 

\smallskip
(ii) Assume $x\in\interior\Om$. 
Put $x_0=x$ and fix it. 
Take a positive number $\e_0$ with $\e_0<\textrm{dist}(x_0,\partial\Om)$.
Suppose $x'\in B_{\frac{\e_0}2}(x_0)$. 
Then 
\[V_{\Om}^{(\a)}(x')-V_{B_{\e_0}(x_0)}^{(\a)}(x')=\int_{\Om\setminus B_{\e_0}(x_0)}|x'-y|^\an\,d\mu(y)\,.\]
Therefore, 
\[\begin{array}{rcl}
\displaystyle \frac{\partial V_{\Om}^{(\a)}}{\partial x_j}(x')-\frac{\partial V_{B_{\e_0}(x_0)}^{(\a)}}{\partial x_j}(x')
&=&\displaystyle \int_{\Om\setminus B_{\e_0}(x_0)} \frac{\partial }{\partial x_j}|x'-y|^\an\,d\mu(y)\\[4mm]
&=&\displaystyle -\int_{\Om\setminus B_{\e_0}(x_0)} \textrm{div}_y\left(|x'-y|^\an \,e_j\right)d\mu(y)\\[4mm]
&=&\displaystyle -\int_{\partial\Om}|x'-y|^\an \,e_j\cdot n\,d\sigma(y
+\int_{\partial B_{\e_0}(x_0)}|x'-y|^\an \,e_j\cdot n\,d\sigma(y)\,,
\end{array}\]
where $\sigma$ is the standard Lesbegue measure of $\partial B_{\e_0}(x_0)$. 

If we put $x'=x_0$, since 
\[
\frac{\partial V_{B_{\e_0}(x_0)}^{(\a)}}{\partial x_j}(x_0)=0\>\>\mbox{ and }\>\>
\int_{\partial B_{\e_0}(x_0)}|x_0-y|^\an \,e_j\cdot n\,d\sigma(y)=0
\]
by the symmetry, we obtain \eqref{formula_derivative_boundary}. 

\medskip
(2) Suppose $\a>1$. 
Since $\a-\n>-(\n-1)=-\dim\partial\Om$, the right hand side of \eqref{formula_derivative_boundary} is well-defined even if the point $x$ is on the boundary $\partial\Om$, and is continuous on $\RR^\n$. 
\end{proof}
\begin{remark}\label{geometric_proof}\rm 
There are two more proofs of the above proposition. 

(i) Put $\Om_{-he_j}=\{y-he_j\,|\,y\in\Om\}$. Then (see Figure \ref{Omega_-he1}) 
$$
\begin{array}{rcl}
\displaystyle \frac{\partial V_{\Om}^{(\a)}}{\partial x_j}(x)
&=&\displaystyle \lim_{h\to0}\frac{V_{\Om}^{(\a)}(x+he_j)-V_{\Om}^{(\a)}(x)}h \\[4mm]
&=&\displaystyle \lim_{h\to0}\frac{V_{\Om_{-he_j}}^{(\a)}(x)-V_{\Om}^{(\a)}(x)}h \\[4mm]
&=&\displaystyle -\lim_{h\to0}\frac1h \int_{\Om-\Om_{-he_j}}|x-y|^\an\,d\mu(y)\\[4mm]
&=&\displaystyle -\int_{\partial\Om}{|x-y|}^{\an}\,e_j\cdot n\,d\sigma (y).
\end{array}
$$

\begin{figure}[htbp]
\begin{center}
\includegraphics[width=.6\linewidth]{Omega_-he1.ps}
\caption{$\Om-\Om_{-he_1}$ $(h>0)$. The right (left) strip with positive (resp. negative) orientation. }
\label{Omega_-he1}
\end{center}
\end{figure}

\medskip
(ii) The proposition can also be proved by the boundary integral formulae in Theorem \ref{prop_boundary_integral_formula}, Stokes' theorem, and Lemma \ref{lemma_X-Y}. 
\end{remark}

\begin{corollary}\label{cor_second_partial_derivatives}
If $\a>2$
then the second derivative $\frac{\partial^2 V_{\Om}^{(\a)}}{\partial x_j{}^2}$ is given by 
\begin{eqnarray}
\displaystyle \frac{\partial^2 V_{\Om}^{(\a)}}{\partial x_j{}^2}(x)
&=&\displaystyle -(\a-\n)\int_{\partial\Om}{|x-y|}^{\an-2}(x_j-y_j)\,e_j\cdot n\,d\sigma (y)  \label{f_second_partial_derivative_boundary} \\
&=&\displaystyle (\a-\n)\int_{\Om}{|x-y|}^{\an-4}\left((\an-2)(x_j-y_j)^2+{|x-y|}^2\right)d\mu (y) \label{f_second_partial_derivative_Omega_bis}\\
&=&\displaystyle (\a-\n)\int_{\Om}{|x-y|}^{\an-4}\left((\an-1)(x_j-y_j)^2+\sum_{i\ne j}(x_i-y_i)^2\right)\!d\mu (y),\hspace{0.3cm}{\phantom{a}}
\label{f_second_partial_derivative_Omega}
\end{eqnarray}
and is continuous on $\RR^\n$. 

Furthermore, for any $\a$,  
\eqref{f_second_partial_derivative_boundary} holds on $(\partial\Om)^c$ and \eqref{f_second_partial_derivative_Omega_bis} and \eqref{f_second_partial_derivative_Omega} hold on $\Om^{\,c}$. 

\end{corollary}
\begin{proof}
Put $r=|x-y|$. 

The absolute value of the integrand of \eqref{f_second_partial_derivative_boundary} is bounded above by $r^{\an-2}\cdot r=r^{\an-1}$. 
If $\a>2$ then $\an-1>-m+1=-\dim(\partial\Om)$, and therefore the right hand side of \eqref{f_second_partial_derivative_boundary} is well-defined even if a point $x$ belongs to $\partial\Om$. 

The absolute value of the integrand of \eqref{f_second_partial_derivative_Omega} is bounded above by $(|\an-1|+1)\,r^{\an-2}$. 
If $\a>2$ then $\an-2>-\n$, and therefore \eqref{f_second_partial_derivative_Omega} is well-defined. 

The equality of the right hand side of \eqref{f_second_partial_derivative_boundary} and \eqref{f_second_partial_derivative_Omega_bis} is obvious.
\end{proof}
\subsection{Continuity and asymptotic behavior}
The same geometric argument as in Remark \ref{geometric_proof} (i) implies the continuity of $V_{\Om}^{(\a)}$. 
\begin{proposition}\label{prop_continuity_homothety} 
When $\a>0$ the map $V_{\Om}^{(\a)}:\RR^\n\to\RR$ is continuous.  
When $\a\le0$, the restrictions of $V_{\Om}^{(\a)}$ to $\interior{\Om}$ and $\Om^{\,c}$ are continuous. 
\end{proposition}

We remark that when $0<\a<\n$ the continuity is nothing but that of the Riesz potential, 
and that when $\a\le0$ it follows from the boundary integral expression in Theorem  \ref{prop_boundary_integral_formula}. 
\begin{lemma}\label{lemma_divergence_boundary}
Suppose a point $z$ on the boundary $\partial\Om$ satisfies Poincar\'e's condition outside, namely, 

\smallskip
$(\ast\ast)$ There are positive constants $\e$ and $\theta$ such that
$B_{\e}(z)\cap\Om^{\,c}$ contains a cone of revolution with vertex $z$ and cone angle $\theta$. 

\begin{enumerate}
\item If $\a\le0$ then $V_{\Om}^{(\a)}\big|_{\interior\Om}(x)$ goes to $-\infty$ uniformly as $x\in\interior\Om$ approaches $z$. 
\item Assume that $\partial\Om$ satisfies Poincar\'e's condition inside. 
If $\a\le0$ then $V_{\Om}^{(\a)}\big|_{\Om^{c}}(x)$ goes to $+\infty$ uniformly as $x\in\Om^{\,c}$ approaches $z$. 
\end{enumerate}
\end{lemma}
\begin{proof}
We only prove (1) in what follows as (2) can be proved in the same way. 

\smallskip
We may assume $\e\le\frac12$. 
Let $C$ be the volume of a subset of the unit sphere $S^{\n-1}$ which is inside a cone of revolution with center the origin and cone angle $\theta$. 
Suppose $x\in\interior\Om$ satisfies $|x-z|<\delta$, where $\delta\le\frac12$. 

(i) Assume $\a<0$. 
Since $\delta+r\le1$ if $0<r<\frac12$, the formula \eqref{f_Va_complement} implies 
\[\begin{array}{rcl}
V_{\Om}^{(\a)}(x)&\le&\displaystyle -\int_0^{\e}(\delta+r)^\an\cdot Cr^{\n-1}\,dr
\le\displaystyle -C\int_0^{\e}{(\delta+r)}^{-\n}\cdot r^{\n-1}\,dr
=-C\int_1^{1+\frac{\e}\delta} \frac{(t-1)^{\n-1}}{t^\n}\,dt,
\end{array}\]
which implies $\displaystyle \lim_{|x-z|\to+0}V_{\Om}^{(\a)}(x)=-\infty$ as $\displaystyle \lim_{R\to+\infty}\int_1^R \frac{(t-1)^{\n-1}}{t^\n}\,dt=+\infty$. 

\smallskip
(ii) Assume $\a=0$. 
Put $R=\max\{1,\diam\}$, where $\diam$ is the diameter of $\Om$. 
Then $B_R(x)$ contains both $\Om$ and the cone in $\Om^{\,c}$ of the condition $(\ast\ast)$. 
Therefore, the formula \eqref{f_V0_R} implies $\displaystyle \lim_{|x-z|\to+0}V_{\Om}^{(0)}(x)=-\infty$ by a similar argument as above. 

\smallskip
The uniformness follows from the fact that the right hand sides of the above estimates do not depend on $x$. 
\end{proof}
\begin{corollary}
If $\a\le0$ then $V_{\Om}^{(\a)}$ cannot be extended to a continuous function on $\RR^\n$. 
\end{corollary}
\begin{lemma}\label{lemma_partial_differentiability}
Suppose $\a\le1$. 
Assume $\Om$ satisfies the following condition: 

\smallskip
$(\ast\ast\ast)$ For any boundary point $z$ there is a direction $v\in S^{\n-1}$ such that $\Om$ around that point can be obtained as a space under a graph in direction $v$ of a piecewise $C^1$ function on an $(\n-1)$ dimensional hyperplane. 
\smallskip

Then the directional derivative of $V^{(\a)}_\Om$ in $v$ at a boundary point $z$ in satisfies 
\[\lim_{h\to0}\frac{\partial \,V^{(\a)}_\Om}{\partial v}(z+hv)=-\infty\,.\]

\end{lemma}
First observe that the formula \eqref{formula_derivative_boundary} implies that the lemma above holds when $\partial\Om$ contains $B_R^{\n-1}(0)\times\{0\}$ for some $R>0$ with outer normal vector $e_\n$ and the point $z$ approaches $\partial\Om$ as $z=he_\n$ $(h\to0)$. The proof of a general case is just a technicality. 

\begin{proof} 
We may assume, after a motion of $\RR^\n$, that $z=0$ and $v=e_m$, namely, there are positive constants $\rho$ and $b$ and a piecewise $C^1$ function $f$ such that 
\[\begin{array}{l}
\left(B_{\rho}^{\n-1}(0)\times(-b,b)\right)\cap\Om\\[1mm]
=\{(x_1,\ldots,x_\n)\,|\,x_\n\le f(x_1, \ldots, x_{\n-1}), \>(x_1, \ldots, x_{\n-1})\in B_{\rho}^{\n-1}(0)\}\,.
\end{array}\]

Let $C'>0$ be the minimum of $e_\n\cdot n$ on $\left(B_{\rho}^{\n-1}(0)\times[-b,b]\right)\cap\partial\Om$. 
Let $\pi:\RR^\n\to\RR^{\n-1}$ be the projection in the direction of $e_\n$. 
There is a positive constant $C$ such that for any point $y$ in $\left(B_{\rho}^{\n-1}(0)\times(-b,b)\right)\cap\partial\Om$ there holds $|y|<C|\pi(y)|$. 
For any $\e>0$ if $0<|h|<\e$ then for any $y\in\partial\Om$ with $\pi(y)\in B_{\rho}^{\n-1}(0)\setminus B_\e^{\n-1}(0)$ 
we have 
$\displaystyle \frac{|he_m-y|}{|y|}\le\frac{|h|+|y|}{|y|}<2.$
Then if $0<|h|<\e$ then 
\[\begin{array}{l}
\displaystyle \int_{\left(B_{\rho}^{\n-1}(0)\times(-b,b)\right)\cap\partial\Om}
|he_\n-y|^{\an}\,e_\n\cdot n\,d\sigma (y)\\[4mm]
\displaystyle >\int_{\left((B_{\rho}^{\n-1}(0)\setminus B_\e^{\n-1}(0))\times(-b,b)\right)\cap\partial\Om}
|he_\n-y|^{\an}\,e_\n\cdot n\,d\sigma (y)\\[4mm]
\displaystyle >2^\an\int_{\left((B_{\rho}^{\n-1}(0)\setminus B_\e^{\n-1}(0))\times(-b,b)\right)\cap\partial\Om}
|y|^{\an}\,e_\n\cdot n\,d\sigma (y)\\[4mm]
\displaystyle \ge2^\an C^\an C'\int_{B_{\rho}^{\n-1}(0)\setminus B_\e^{\n-1}(0)}|y'|^{\an}\,d\mu_{\n-1} (y')\\[4mm]
\displaystyle =2^\an C^\an C' A(S^{\n-2})\int_\e^\rho r^\an\cdot r^{\n-2}\,dr\,,
\end{array}\]
where $\mu_{\n-1}$ is the standard Lebesgue measure of $\RR^{\n-1}$. 
As $\a-2\le-1$ the right hand side above blows up to $+\infty$ as $\e$ goes down to $+0$, and therefore, 
\[\begin{array}{rcl}
\displaystyle \frac{\partial V_{\Om}^{(\a)}}{\partial x_\n}(he_\n)&=&\displaystyle -\int_{\partial\Om}|he_\n-y|^{\an}\,e_\n\cdot n\,d\sigma (y)
\end{array}\]
goes to $-\infty$ as $h$ approaches $0$. 
\end{proof}

\medskip
Let us consider the continuity of $V_{\Om}^{(\a)}(x)$ with respect to $\a$. 
\begin{proposition}\label{prop_continuity} 
Fix a compact set $\Om$ and a point $x\in\RR^\n$.
\begin{enumerate}
\item The map $\RR\ni\alpha\mapsto V_{\Om}^{(\a)}(x)\in\RR$ is continuous on $\RR_+$ for any $x$. 
It is further continuous on $\RR\setminus\{0\}$ if $x\in\interior\Om$, and on $\RR$ if $x\not\in\Om$. 
\item If $x\in\interior\Om$ then $\displaystyle \lim_{\a\to\pm0}V_{\Om}^{(\a)}(x)=\pm\infty$. 
\end{enumerate}
\end{proposition}
\begin{proof}
Put $\varPhi_{\Om}(\a)=V_{\Om}^{(\a)}(x)$. 

(1) Suppose $\a>0$. 
Let $\e$ be a positive number. 
Then \eqref{f_V_ball} implies that there is $r>0$ such that $\varPhi_{\Om\cap B_r(x)}(\a')<\e$
for any $\a'$ with $\frac\a2\le\a'$.
On the other hand, as $\Om\setminus {(\Om\cap B_r(x))}^\circ$ is compact and $\textrm{dist}(x,\Om\setminus {(\Om\cap B_r(x))}^\circ)\ge r$, where ${(\Om\cap B_r(x))}^\circ$ denotes the interior of $\Om\cap B_r(x)$, there is $\delta>0$ ($\delta\le\frac\alpha2$) such that if $|\a'-\a|<\delta$ then 
$\big|\varPhi_{\Om\setminus {(\Om\cap B_r(x))}^\circ}(\a')-\varPhi_{\Om\setminus {(\Om\cap B_r(x))}^\circ}(\a)\big|<\e$ 
and hence 
\[\begin{array}{rcl}
\displaystyle \left|\varPhi_{\Om}(\a')-\varPhi_{\Om}(\a)\right|
&\le&\displaystyle \left|\varPhi_{\Om\setminus {(\Om\cap B_r(x))}^\circ}(\a')-\varPhi_{\Om\setminus {(\Om\cap B_r(x))}^\circ}(\a)\right| + \varPhi_{B_r(x)}(\a')+\varPhi_{B_r(x)}(\a) \le3\e
\end{array}\]
which implies the first statement. 

\smallskip
The second statement follows from \eqref{V_alpha_boundary}, and the last one is obvious. 

\smallskip
(2) Suppose $x\in\interior\Om$. 
Let $r$ be a positive number with $r<\textrm{dist}(x,\partial\Om)$ and $\diam$ be the diameter of $\Om$. 
Then $B_r(x)\subset\Om\subset B_\diam(x)$. 

By Corollary \ref{cor_Omega_1_subset_Omega_2} and the formula \eqref{f_V_ball}, if $\a>0$ then 
\[V^{(\a)}_\Om(x)\ge V^{(\a)}_{B_r(x)}(x)=\frac{A(S^{\n-1})\,r^{\a}}{\a},\]
which implies $\displaystyle \lim_{\a\to+0}\varPhi_{\Om}(\a)=+\infty$, and if $\a<0$ then 
\[V^{(\a)}_\Om(x)\le V^{(\a)}_{B_\diam(x)}(x)=\frac{A(S^{\n-1})\,\diam^{\phantom{,\!}\a}}{\a},
\]
which implies $\displaystyle \lim_{\a\to-0}\varPhi_{\Om}(\a)=-\infty$.
\end{proof}

The asymptotic behavior of $V^{(\a)}_\Om$ as $\a$ goes to $\pm\infty$ will be studied in Lemma \ref{l_asympt_V}. 

\subsection{Laplacian}
\begin{theorem}
Let $\Om$ be a body in $\RR^\n$ with a piecewise $C^1$ boundary. 
If $\a>2$ or $x\not\in\partial\Om$ and $\a\ne2$ then 
\begin{equation}\label{laplacian_general}
\Delta V^{(\a)}_\Om(x)=(\a-2)(\an)V^{(\a-2)}_\Om(x).
\end{equation}
\if0 
\item Suppose $\a=2$.
If $x\in\Om^{\,c}$ then $\Delta V^{(2)}_\Om(x)=0$, and if $x\in\interior\Om$ then 
\begin{equation}\label{laplacian_alpha=2}
\Delta V^{(2)}_\Om(x)=-(\n-2)\int_{\partial B_R(0)}\frac{y-x}{|y-x|^\n}\cdot n\,d\sigma(y), 
\end{equation}
where $R>0$ is big enough so that $B_R(0)\supset\Om$. 
\end{enumerate}
\fi 
\end{theorem}
\begin{proof} 
First note that 
\begin{eqnarray}\label{laplacian_r}
\Delta_x{|x-y|}^\an=(\a-2)(\a-\n){|x-y|}^{\an-2}.
\end{eqnarray}

If $\a>2$ then \eqref{laplacian_general} follows from \eqref{f_second_partial_derivative_Omega_bis} or from \eqref{laplacian_r}. 

Suppose $x\not\in\partial\Om$. 
By formula \eqref{f_second_partial_derivative_boundary}, we have
\begin{eqnarray}
\Delta V^{(\a)}_\Om(x)&=&\displaystyle -(\a-\n)\int_{\partial\Om}{|x-y|}^{\an-2}(x-y)\cdot n\,d\sigma (y).  \label{f_laplacian_1
\end{eqnarray}

On the other hand, if $\a-2\ne0$ then by Theorem \ref{prop_boundary_integral_formula} we have 
\[V_{\Om}^{(\a-2)}(x)=\frac1{\a-2}\int_{\partial\Om} {|x-y|}^{\an-2}(y-x)\cdot n\,d\sigma (y). \]
\if0 
(2) Suppose $\a=2$.

When $x\in\Om^{\,c}$, \eqref{laplacian_r} implies $\Delta V^{(2)}_\Om(x)=0$. 

When $x\in\interior\Om$, \eqref{f_laplacian_1} implies 
\[
\Delta V^{(2)}_\Om(x)=-(\n-2)\int_{\partial\Om}{|x-y|}^{-\n}(y-x)\cdot n\,d\sigma (y)\,. 
\]
On the other hand, as $\displaystyle \textrm{div}_y\left({|x-y|}^{-\n}(y-x)\right)=0$ we have
\[\begin{array}{rcl}
0&=&\displaystyle \int_{B_R(0)\setminus\Om}\textrm{div}_y\left({|x-y|}^{-\n}(y-x)\right)\,d\mu(y)\\[4mm]
&=&\displaystyle \int_{\partial B_R(0)}{|x-y|}^{-\n}(y-x)\cdot n\,d\sigma(y)-\int_{\partial \Om}{|x-y|}^{-\n}(y-x)\cdot n\,d\sigma(y),
\end{array}\]
which completes the proof. 
\fi 
\end{proof}

We remark that when $\a=2$ and $\n\ge3$, i.e. when $V^{(\a)}_\Om$ is (a constant times) the Newton potential, we have $\Delta V^{(2)}_\Om(x)=0$ if $x\in\Om^{\,c}$ and $\Delta V^{(2)}_\Om(x)=-(\n-2)A(S^{\n-1})$ if $x\in\interior\Om$. 

\begin{corollary}
Let $\Om$ be a body in $\RR^\n$ with a piecewise $C^1$ boundary. 
\begin{enumerate}
\item If $\a>\n$ then $\Delta V^{(\a)}_\Om>0$ on $\RR^\n$. 
\item If $\a=\n$ then $\Delta V^{(\n)}_\Om=0$ on $\RR^\n$. 
\item If $2<\a<\n$ $(\n\ge3)$ then $\Delta V^{(\a)}_\Om<0$ on $\RR^\n$. 
\item If $\n\ge3$ and $\a=2$ then 
$\Delta V^{(2)}_\Om<0$ on $\interior\Om$. 
\item If $\a<2$ then $\Delta V^{(\a)}_\Om>0$ on $\Om^{\,c}$ and $\Delta V^{(\a)}_\Om<0$ on $\interior\Om$. 
\end{enumerate}
\end{corollary}

The author thanks Kazuhiro Kurata for informing him that $\Delta V^{(0)}_\Om<0$ on $\interior\Om$ when $\n=2$. 
\begin{proof}
The formula \eqref{laplacian_general} and Lemma \ref{lem_boundary} imply (1), (3), and (5). 
The statement (2) follows from $V^{(\n)}_\Om(x)=\textrm{Vol}(\Om)$ $(\forall x)$. 
The statement (4) follows from the remark above. 
\end{proof}

\subsection{Convex geometric formulae and duality by an inversion in a sphere}
Let us recall some terminologies from convex geometry. 

A set $M$ in $\RR^\n$ is called {\em star-shaped at $0$} if for any point $p$ in $M\setminus\{0\}$ the line segment $\overline{0p}$ is contained in $M$. 

Suppose $M$ is star-shaped at $0$. 
The {\em radial function} of $M$ is a map $\rhosub{M}$ from $S^{\n-1}$ to $\RR_{\ge0}$ defined by $\rhosub{M}(v)=\sup\{a\ge0\,|\,av\in M\}$ 
($\rhosub{M}(v)$ is also denoted by $\mbox{\large $\rho $}(M,v)$).
When $\interior{M}\ni0$ the {\em dual mixed volume of $M$ of order $\alpha$ $(\alpha\in\RR)$} is given by 
$$
\tilde{V}_\alpha(M)=\int_{S^{\n-1}}{(\rhosub{M}(v))}^\alpha d\sigma(v).
$$
When $\alpha=\n$, $\tilde{V}_\n(M)=\n\textrm{Vol}(M)$. 
It was originally introduced for convex bodies in \cite{Lu75,Lu88} (see also \cite{Ga}, \cite{Sch}). 

We show that $V^{(\a)}_\Om(x)$ $(\alpha\ne0, \, x\in\interior\Om)$ coincides with the dual mixed volume of $\Om_{-x}$ of order $\alpha$ up to multiplication by a constant. 
\begin{lemma}\label{prop_int_geom}
Let $\Om$ be a body in $\RR^\n$ with a piecewise $C^1$ boundary. 

Suppose $x\in\interior{\Om}$ and $\Om$ is star-shaped at $x$. 
Let $\rhosub{\Om_{-x}}$
be a radial function of $\Om_{-x}=\{y-x\,|\,y\in\Om\}$. 
Then 
\begin{eqnarray}
V^{(\a)}_\Om(x) &=&\displaystyle \frac1\a\int_{S^{\n-1}}\left(\rhosub{\Om_{-x}}(v)\right)^\a\,d\sigma(v) \hspace{1cm}(\a\ne0), \label{V^a_int_S^m-1} \\
V^{(0)}_\Om(x) &=&\displaystyle \int_{S^{\n-1}}\log\left(\rhosub{\Om_{-x}}(v)\right)\,d\sigma(v) \hspace{1cm}(\a=0). \label{V^0_int_S^m-1} 
\end{eqnarray}
\end{lemma}
\begin{proof}
Note that $\Om$ can be expressed as 
$$
\Om=\left\{x+r(v)\,v\,|\,0\le r(v)\le \rhosub{\Om_{-x}}(v)\,, \,v\in S^{\n-1}\right\}.
$$

Remark that 
$r^{\an}d\mu=r^{\a-1}dr\,d\sigma(v).$

If $\a<0$ then \eqref{f_Va_complement} implies 
$$
V^{(\a)}_\Om(x
=-\int_{S^{\n-1}}\int_{\rho _{\Om_{-x}}(v)}^\infty r^{\a-1} dr\,d\sigma(v)
=\frac1\a\int_{S^{\n-1}}\left(\mbox{\large $\rho$}_{\Om_{-x}}(v)\right)^\a d\sigma(v).
$$

If $\a=0$ then \eqref{f_V0_epsilon} implies that if
we use a sufficiently small $\e>0$ 
we have 
$$
V^{(\a)}_\Om(x)
=\displaystyle \int_{S^{\n-1}}\int_\e^{\rho_{\Om_{-x}}(v)} \frac{dr}{r}\,d\sigma(v)-A(S^{\n-1})\log\frac1\e
=\int_{S^{\n-1}}\log\left(\rhosub{\Om_{-x}}(v)\right)\,d\sigma(v).
$$

The case when $\a>0$ is obvious. 
\end{proof}
\begin{theorem}\label{thm_radial_general}
Let $\Om$ be a body in $\RR^\n$ with a piecewise $C^1$ boundary. 
Let $\ell_{x,v}$ $(x\in\RR^\n, v\in S^{\n-1})$ denote a half line $\{x+tv\,|\,t>0\}$, and $p_i$ be a point where $\ell_{x,v}$ intersects $\partial\Om$ transversally, which we denote by $p_i\in\ell_{x,v}\ti\partial\Om$. 
Define the signature at $p_i$ by $\mbox{\rm sgn}(p_i)=+1$ if $\ell_{x,v}$ cuts across $\partial\Om$ from the inside to the outside of $\Om$ as $t$ increases and $\mbox{\rm sgn}(p_i)=-1$ otherwise. Then if $\a>0$ or $x\not\in\partial\Om$ we have 
\begin{eqnarray}
V^{(\a)}_\Om(x)&=&\displaystyle \frac1\a\int_{S^{\n-1}}
\sum_{p_i\in\ell_{x,v}\ti\partial\Om}\mbox{\rm sgn}(p_i)\,{|p_i-x|}^\a
\,d\sigma(v) \hspace{0.5cm}(\a\ne0), \nonumber\\%[4mm]
V^{(0)}_\Om(x)&=&\displaystyle \int_{S^{\n-1}}
\sum_{p_i\in\ell_{x,v}\ti\partial\Om}\mbox{\rm sgn}(p_i)\log|p_i-x|
\,d\sigma(v) \hspace{0.5cm}(\a=0). \nonumber
\end{eqnarray}
\end{theorem}

This can be proved by cutting $\Om$ into several pieces so that the intersection of every piece and any half line starting from $x$ is connected (possibly empty). 
\begin{corollary}\label{thm_inversion}
Suppose $x$ is a point with $x\not\in\partial\Om$. 
Let $I_x$ be an inversion in a unit sphere with center $x$. 
Let $\Om^\star_x$ be the closure of the complement of $I_x(\Om)$: $\Om^\star_x=\overline{(I_x(\Om))^c}$. 
\begin{enumerate}
\item If $x\in\interior\Om$ then $V^{(\a)}_\Om(x)=-V^{(-\a)}_{\Om^\star_x}(x)$ for any $\a$. 
\item If $x\not\in\Om$ then $V^{(\a)}_\Om(x)=V^{(-\a)}_{I_x(\Om)}(x)$ for any $\a$. 
\end{enumerate}
\end{corollary}
When $x=0$, $\Om^\star_0$ is called the {\em star duality} of $\Om$ in \cite{M0}. 
\begin{proof}
Suppose $\ell_{x,v}\ti\partial\Om=\{p_1,\ldots,p_k\}$. Then as 
$$\begin{array}{c}
\displaystyle \ell_{x,v}\ti\partial (I_x(\Om))=\ell_{x,v}\ti\partial\Om^\star_x=\{I_x(p_1),\ldots,I_x(p_k)\}, \\[2mm]
|I_x(p_i)-x|={|p_i-x|}^{-1}, \\[2mm]
-\mbox{\rm sgn}_{I_x(\Om)}(I_x(p_i))=\mbox{\rm sgn}_{\Om^\star_x}(I_x(p_i))=\mbox{\rm sgn}(p_i),
\end{array}$$ 
corollary follows from the theorem above. 
\end{proof}
\subsection{Log potential}
In the study of $r^\an$-centers in the next section, it is natural to use the log potential 
\[
V_\Om^{\log}(x)=\int_\Om\log\frac1{|x-y|}\,d\mu(y)=-\int_\Om\log{|x-y|}\,d\mu(y)
\]
as $r^0$-potential for the case when $\a=\n$ since 
\[
\frac{\partial V_\Om^{\log}}{\partial x_j}(x)=-\int_\Om{|x-y|}^{-2}(x_j-y_j)\,d\mu(y)
\]
can be considered as 
\[
-\lim_{\a\to\n}\int_\Om{|x-y|}^{\a-\n-2}(x_j-y_j)\,d\mu(y)=-\lim_{\a\to\n}\frac1{\an}\cdot\frac{\partial V_\Om^{(\a)}}{\partial x_j}(x). 
\]

The argument so far in the paper for $V_\Om^{(\a)}$ works roughly as well for $V_\Om^{\log}$. 
It is a continuous function on $\RR^\n$. 
Since 
\[
\textrm{div}_y\left(\frac1\n\left(\log r-\frac1m\right)(y-x)\right)=\log r,
\]
the log potential can also be expressed by the boundary integral as 
\[
V_\Om^{\log}(x)=-\frac1m\int_{\partial\Om}\left(\log r-\frac1m\right)(y-x)\cdot n\,d\sigma(y).
\]
The same argument as in Proposition \ref{prop_derivative_boundary} works to obtain 
\[
\frac{\partial V_\Om^{\log}}{\partial x_j}(x)=-\int_{\partial\Om}\log\frac1{|x-y|}\,\,e_j\cdot n\,d\sigma (y). 
\]
It implies 
\[\begin{array}{rcl}
\displaystyle \frac{\partial^2 V_\Om^{\log}}{\partial {x_j}^2}(x)&=&\displaystyle \int_{\partial\Om}{|x-y|}^{-2}(x_j-y_j)e_j\cdot n\,d\sigma (y),\\[4mm]
\displaystyle \Delta V_\Om^{\log}(x)&=&\displaystyle \int_{\partial\Om}{|x-y|}^{-2}(x-y)\cdot n\,d\sigma (y),
\end{array}
\]
and so, if $\n>2$ 
\[
\Delta V_\Om^{\log}(x)=-(\n-2) V_\Om^{(\n-2)}(x)<0. 
\]
When $\n=2$, as $\Delta_x \log|x-y|=0$ ($|x-y|\ne0$),
$\Delta V_\Om^{\log}(x)=\Delta V_{D_\e(x)}^{\log}(x)=-2\pi$ if $x\in\interior\Om$ ($\e<\textrm{dist}(x,\partial\Om)$) and $\Delta V_\Om^{\log}(x)=0$ if $x\in\Om^c$. 


\section{The $\vect{r^\an}$-centers}
\subsection{Definition and examples
\begin{definition}\label{def_Mn_center} \rm 
Let $Mm^{(\a)}(\Om)$ denote the minimum value of $V_{\Om}^{(\a)}$ when $\a>\n$,
the maximum value of $V_\Om^{\log}$ when $\a=\n$, 
the maximum value of $V_{\Om}^{(\a)}$ when $0<\a<\n$, and the maximum value of $V_{\Om}^{(\a)}\big|_{\interior{\Om}}$ when $\a\le0$. 

Define the {\em ${r^{\an}}$-center} of $\Om$, denoted by $C_{\an}(\Om)$, by a point where $Mm^{(\a)}(\Om)$ is attained. 
\end{definition}

Remark that when $\a=\n$ it is meaningless to use $V_{\Om}^{(\n)}$ as it is  constantly equal to $\textrm{Vol}\,(\Om)$. 

\begin{example} \rm 
Let $x=(x_1, \ldots, x_\n)$ be an $r^2$-center of $\Om$. 
Then, as $x$ is a critical point of $V_{\Om}^{(\n+2)}$, it satisfies 
\[0=\frac{\partial }{\partial x_i} \int_{\Om}\, \sum_{k=1}^\n(x_k-y_k)^2 \,dy_1\cdots dy_\n
=2\int_{\Om}\, (x_i-y_i) \,dy_1\cdots dy_\n. \]
Therefore, $x$ is given by 
\[x_i=\frac{\displaystyle \int_{\Om}\, y_i \,dy_1\cdots dy_\n}{\displaystyle \int_{\Om}\, 1 \,dy_1\cdots dy_\n},\]
which implies that the $r^2$-center coincides with the centroid (center of mass). 
\end{example}

\begin{example} \rm 
In \cite{S} Katsuyuki Shibata introduced the {\em (planar) illuminating center} of a triangle $\Om$ by a point in $\interior\Om$ that gives the maximum value of a map
\[
\Om\setminus(\Om\cap N_{\varepsilon}(\partial\Om))\ni x\mapsto \int_{\Om\setminus B_{\varepsilon}(x)}{{|x-y|}^{-2}}\,d\mu(y)\in\RR
\]
for any sufficiently small $\e>0$, 
where $N_{\varepsilon}(\partial\Om))$ is the $\varepsilon$-tubular neighbourhood of $\partial \Om$. 
In our language, the planar illuminating center is an $r^{-2}$-center. 

Shibata gave the characterization of the planar illuminating center of a triangle as follows (\cite{S}). 
Let $L$ be the illuminating center of a triangle $\triangle ABC$. 
Let $X,Y$ and $Z$ be the intersection points of the edges $BC, CA$ and $AB$ with the line $\overline{AL}, \overline{BL}$, and $\overline{CL}$ respectively (figure \ref{illuminating_center}). 
Then there hold 
\
\displaystyle \frac{\angle ALB}{\angle ALC} = \frac{|BX|}{|CX|}, \>\, 
\frac{\angle CLA}{\angle CLB} = \frac{|AZ|}{|BZ|}, \,\>\mbox{\rm  and }\>\,
\frac{\angle BLC}{\angle BLA} = \frac{|CY|}{|AY|}.
\]
\begin{figure}[htbp]
\begin{center}
\includegraphics[width=.35\linewidth]{illuminating_center.ps}
\caption{Illuminating center of a triangle}
\label{illuminating_center}
\end{center}
\end{figure}
We remark that the last equation of the formulae above can be obtained from the former two by Ceva's theorem. 

We remark that the idea of the illuminating center can be considered as $2$-dimensional analogue of that of the radial center of order $1$ for convex bodies in $\RR^3$ explained in \cite{HMP}. 
\end{example}

\begin{example} \rm 
Let $\Om$ be a convex set with non-empty interior. 
A point $x\in\interior\Om$ is called the {\em radial center of order $\a$} $(\a\ne0)$ if it gives the extreme value of the dual mixed volume of order $\a$ of $\Om_{-x}=\{y-x\,|\,y\in\Om\}$, 
$V_\a(\Om_{-x})=\int_{S^{\n-1}}\big(\rhosub{\Om_{-x}}\big)^\a d\sigma(v)$, 
where $\rho_{\Om_{-x}}$ is the radial function of $\Om_{-x}$. 
It was introduced in \cite{M1} for $0<\a\le1$ and studied in \cite{H} for any $\a$ $(\a\ne0)$. 

The formula \eqref{V^a_int_S^m-1} in Lemma \ref{prop_int_geom} implies that if $\Om$ is convex then an $r^\an$-center $(\a\ne0)$ coincides with the radial center of order $\a$. 
\end{example}

\begin{remark}\rm 
Since $V^{(-\n)}_\Om(x)=-\textrm{\rm Vol}\left(\Om^\star_x\right)$ by Corollary \ref{thm_inversion}, where $\Om^\star_x$ is the closure of the complement of the image of $\Om$ by an inversion in a unit sphere with center $x$, the $r^{-2\n}$-center is a point so that $\Om^\star_x$ has the smallest volume. 
\end{remark}

\subsection{The minimal unfolded regions}\label{subs_min_unfold_region}
Let us introduce a region whose complement has no chance to have any ${r^{\an}}$-center. 
Let us first explain in the case when $\Om$ is a convex set in a plan. 
Let $\Om_1$ be a subset of $\Om$ cut out of $\Om$ by a line $L$. 
Fold $\Om$ like origami in $L\cap\Om$. 
Suppose $\Om_1$ can be folded upon $\Om\setminus\Om_1$ (figure \ref{origami_convex}). 
Then our centers cannot be in $\Om_1\setminus(\Om_1\cap L)$ as we will see later. 
\begin{figure}[htbp]
\begin{center}
\includegraphics[width=.32\linewidth]{origami_convex.ps}
\caption{Folding a convex set like origami}
\label{origami_convex}
\end{center}
\end{figure}

\begin{definition}\label{def_folded_core} \rm 
Let $\Om$ be a compact set in $\RR^\n$ with piecewise $C^1$ boundary. 
For a unit vector $v$ in $S^{\n-1}$ and a real number $b$, put $M_v=\sup_{x\in\Omega}x\cdot v$, $\Om_{v,b}^+=\Om\cap\{x\in\RR^\n\,|\,x\cdot v> b\}$, and $\textrm{Refl}_{v,b}$ to be a reflection of $\RR^\n$ in a hyperplane $\{x\in\RR^\n\,|\,x\cdot v=b\}$. 
Put 
$$
l_v=\inf\{a\,|\, a\le M_v, \,\textrm{Refl}_{v,b}(\Om_{v,b}^+)\subset\Om\>\>(a\le\forall b\le M_v)\}.
$$
The set $\Om_{v,l_v}^+$ is called the {\em maximal cap} in direction $v$. 
Define the {\em minimal unfolded region} of $\Om$ by 
$$Uf(\Om
=\bigcap_{v\in S^{\n-1}}\left\{x\in\RR^\n\,|\,x\cdot v\le l_v\right\}.$$
\end{definition}
Since the minimal unfolded region contains the centroid, it is a non-empty set. 
As the convex hull of $\Om$ is given by $\bigcap_{\,v\in S^{\n-1}}\{x\,|\,x\cdot v\le M_v\}$, the minimal unfolded region is contained in the convex hull. 
It is compact and convex. 
Remark that the minimal unfolded region of $\Om$ is not necessarily contained in $\Om$ (figure \ref{folded_core_non_convex}). 

\begin{example} \rm 
\begin{enumerate}
\item If $\Om$ is convex and symmetric in a $q$-dimensional hyperplane $H$ ($q<\n$) then the minimal unfolded region is included in $H$. 
Especially, the minimal unfolded region of an $\n$-ball consists of the center. 
\item The minimal unfolded region of a non-obtuse triangle is surrounded by a quadrilateral, two of the edges of which are perpendicular bisectors and the other two are angle bisectors. 
Therefore, two of the vertices of the quadrilateral coincide with the incenter $I$ and the circumcenter $C$ (figure \ref{folded_core_triangle}). 

