\begin{problem}\rm 
Suppose $\Om$ is convex. 
Is the following true: 
\[
\textrm{diam}(Uf(\Om))
\le\frac12\textrm{diam}(\Om) ?
\]
\end{problem}

\subsection{Existence of $\vect{r^\an}$-centers}
\begin{theorem}\label{thm_existence_center_folded_core} 
Any body in $\RR^\n$ with a piecewise $C^1$ boundary that satisfies 
$(\ast\ast)$ in Lemma \ref{lemma_divergence_boundary} has an ${r^{\an}}$-center in the minimal unfolded region for any $\a$. 
\end{theorem}

To be precise, the condition $(\ast\ast)$ is needed for the existence of the center when $\a\le0$. 

\begin{proof} 
(1) First we show that there exists an ${r^{\an}}$-center in the convex hull. 

(i) Suppose $\a>\n$. 
Let $\Om'$ be a convex hull of $\Om$. 
Since $V_{\Om}^{(\a)}$ is continuous on $\RR^\n$ and $\Om'$ is compact, there is a point $x_0$ where the minimum value of $V_{\Om}^{(\a)}$ in $\Om'$ is attained. 
We show that $x_0$ is an $r^\an$-center of $\Om$. 

Let $x$ be a point in $(\Om')^c$. 
Let $x'$ be a point on $\partial\Om'$ so that $\textrm{dist}(x,\partial\Om')=|x-x'|$. 
(The map $x\mapsto x'$ is called the metric projection \cite{M}.) 
Then $\Om'$ is contained in a half-space whose bounary is the hyperplane orthogonal to a line through $x$ and $x'$. 
(This hyperplane is a support hyperplane of $\Om'$ at $x'$.) 
Therefore for any point $y$ in $\Om$ we have $|x-y|>|x'-y|$ and hence $V_{\Om}^{(\a)}(x)>V_{\Om}^{(\a)}(x')\ge V_{\Om}^{(\a)}(x_0)$. 

(ii) The same argument works  for the Riesz potential $(0<\a<\n)$ and the log potential $(\a=\n)$. 

\smallskip
(iii) Suppose $\a\le0$. 
Put $b=\sup_{x\in\interior\Om}V_{\Om}^{(\a)}(x)$. 
As $V_{\Om}^{(\a)}\big|_{\interior\Om}$ is continuous by Proposition \ref{prop_continuity_homothety}, Lemma \ref{lemma_divergence_boundary} (1) implies that 
$\big(V_{\Om}^{(\a)}\big|_{\interior\Om}\big)^{-1}([b-1,b])$ is a compact set in $\RR^\n$. 
Then $b$ is attained there.

\smallskip
(2) Next we show that an ${r^{\an}}$-center cannot be in the complement of the minimal unfolded region by the moving plane method (\cite{GNN}) using the radial symmetry of partial derivatives of the potential. 
The basic idea is due to Kazuhiro Kurata (personal communication to the author). 
Let us use notation in definition \ref{def_folded_core} in what follows. 

Let $x$ be a critical point of $V_{\Om}^{(\a)}$ when $\a>0$ or $V_{\Om}^{(\a)}\big|_{\interior{\Om}}$ when $\a\le0$. 
Assume $x$ is not in the minimal unfolded region of $\Om$ is 
Then there is a direction $v\in S^{\n-1}$ so that $l_v<x\cdot v\le M_v$. 

Put $c_0=x\cdot v$, $\Om_1=\Om_{v,c_0}^+\cup I_{v,c_0}\left(\Om_{v,c_0}^+\right)$, and $\Om_2=\overline{\Om\setminus\Om_1}$. 
Then the set $\Om$ can be decomposed into two parts, $\Om=\Om_1\cup\Om_2$, 
which is ``disjoint union'' up to the boundaries (figure \ref{folding_unio}). 

\begin{figure}[htbp]
\begin{center}
\includegraphics[width=.4\linewidth]{folding_union.ps}
\caption{}
\label{folding_unio}
\end{center}
\end{figure}

Remark that the slice of $\Om$ with a hyperplane $\{z\in\RR^\n\,|\,z\cdot v=b\}$ grows as $b$ decreases from $M_v$ until $l_v$, namely, $\Om_{v,l_v}^+$ is convex in the direction of $v$. 
Therefore, $\Om_2$ has an non-empty interior as $l_v<c_0\le M_v$.

Let us first assume that either $x\not\in\partial\Om$ or $\a>1$. 
Then Proposition \ref{prop_derivative_boundary} implies that $V^{(\a)}_\Om$ is partially differentiable at $x$. 
We may assume, after a rotation of $\RR^\n$, that the direction $v$ is equal to $e_1$. 
Then 
\[
\frac{\partial V_{\Om}^{(\a)}}{\partial x_1}(x
=\frac{\partial V_{\Om_1}^{(\a)}}{\partial x_1}(x)+\frac{\partial V_{\Om_2}^{(\a)}}{\partial x_1}(x). 
\]
The first term of the right hand side vanishes because of the symmetry.  
The second term of the right hand side is given by 
$$
\frac{\partial V_{\Om_2}^{(\a)}}{\partial x_1}(x)
=\int_{\Om_2}(\an)\,{|x-y|}^{\an-2}(x_1-y_1)\,d\mu(y).
$$
The right hand side above is well-defined if $x\not\in\Om_2$ or $\a>1$ since the absolute value of the integrand is bounded above by $|\a-\n|\,{|x-y|}^{\an-1}$. 
Note that if $x\not\in\partial\Om$ then $x\not\in\Om_2$. 

Since $x_1-y_1>0$ on $\interior\Om_2$, which is a non-empty set, $\frac{\partial V_{\Om_2}^{(\a)}}{\partial x_1}(x)$, and hence $\frac{\partial V_{\Om}^{(\a)}}{\partial x_1}(x)$, cannot be equal to $0$, which is a contradiction. 

\smallskip
We are now left with the case when $0<\a\le1$ and $x\in\partial\Om$. 
Take a small neighbourhood $U$ of $x$ which is contained in $\{x'\in\RR^\n\,|\,x'\cdot v>\frac{l_v+c_0}2\}$. 
Then the above argument implies that there is a negative constant $b$ such that if $x'\in U\cap(\partial\Om)^c$ then $\frac{\partial V_{\Om_2}^{(\a)}}{\partial x_1}(x')<b$. 
Therefore, $x$ cannot be a maximum point of $V_{\Om}^{(\a)}$, which is a contradiction. 
\end{proof}
\begin{corollary}\label{cor_center_symmetry} 
\begin{enumerate}
\item The $r^\an$-center of an $\n$-ball is the center for any $\a$. 
\item If $\Om$ is a convex set in a plane and has two lines of symmetry then its $r^\an$-center is the intersection point of the two lines for any $\a$. 
\end{enumerate}
\end{corollary}


\subsection{Extremeness of balls}
We introduce two kinds of extremeness of balls, one applies for any $\a$ whereas the other for $\a>0$, i.e. the case when the renormalization is not needed, but not for any $\a$. 

Recall that $Mm^{(\a)}$ denotes $\min V_{\Om}^{(\a)}(x)$ $(\a>\n)$, $\max V_\Om^{\log}(x)$ $(\a=\n)$, $\max V_{\Om}^{(\a)}(x)$ $0(<\a<\n)$, and $\max V_{\Om}^{(\a)}\big|_{\interior{\Om}}(x)$ $(\a\le0)$. 
\begin{proposition}{\rm (Sakata)} 
Suppose $\Om$ has the same volume as a ball $B$. Then we have $Mm^{(\a)}(\Om)\ge Mm^{(\a)}(B)$ if $\a>\n$ and $Mm^{(\a)}(\Om)\le Mm^{(\a)}(B)$ if $\a\le\n$, where the equalities hold if and only if $\Om$ is a ball. 
\end{proposition}
The case when $\n=2$ and $\a>0$ is given in \cite{Sak2}. 
\begin{proof}
The idea is due to \cite{Sak} (see also \cite{GHS}). 

Assume $\a\le0$. Suppose $\Om$ is not a ball. 
By definition, the $r^\an$-center of $\Om$ lies in the interior of $\Om$. 
We may assume that the $r^\an$-centers of $\Om$ and $B$ both coincide with the origin, $\vect 0$. Put $\Om_1=\overline{\Om\setminus(\Om\cap B)}$ and $B_1=\overline{B\setminus (\Om\cap B)}$.
Lemma \ref{lemma_X-Y} implies that 
$$
Mm^{(\a)}(\Om)-Mm^{(\a)}(B)=
V^{(\a)}_\Om(\vect 0)-V^{(\a)}_B(\vect 0)=V^{(\a)}_{\Om-B}(\vect 0)=
\int_{\Om_1}r^\an d\mu(y)-\int_{B_1}r^\an d\mu(y),
$$
where $r=|y|$. 
As $|y|>|y'|$ for $y\in\interior{\Om_1}$ and $y'\in\interior{B_1}$, $\an<0$, and $\textrm{Vol}(\Om_1)=\textrm{Vol}(B_1)\ne0$, we have 
$$
\int_{\Om_1}r^\an d\mu(y)<\int_{B_1}r^\an d\mu(y),
$$
which implies $Mm^{(\a)}(\Om)< Mm^{(\a)}(B)$. 

The case when $\a>0$ can be proved in the same way. 
\end{proof} 

\smallskip
Define the {\em $r^\an$-energy} of $\Om$ by 
\begin{equation}\label{eq_E}
E^{(\a)}(\Om)=\int_\Om V^{(\a)}_\Om(x)\,d\mu(x)
=\int_{\Om\times\Om} |x-y|^\an\,d\mu(x)d\mu(y)
\end{equation}
for $\a>0$. 

Following Blaschke \cite{B}, T.~Carleman \cite{C} used Steiner's symmetrization to show that if $f(t)$ $(t>0)$ is a positive function with $f'(t)<0$ so that $f(|x-y|)$ is locally integrable in $\RR^\n\times\RR^\n$ then 
$$E_f(\Om)=\int_{\Om\times\Om} f(|x-y|)\,d\mu(x)d\mu(y)$$
attains the maximum only at balls if the volume of $\Om$ is fixed (see also \cite{Mor}). 
As a corollary it implies 
\begin{proposition}\label{prop_E}
Among bodies with the same volume, balls attain the maximum of $E^{(\a)}(\Om)$ when $0<\a<\n$ and the minimum when $\a>\n$. 
\end{proposition}
The case of gravitational potential ($\n=3, \,\a=2$) was given in \cite{C}. 
\begin{proof}
The first statement can be obtained by putting $f(t)=1/t^{\n-\a}$. 

On the other hand, the second statement can be obtained as follows. 
Suppose $\Om$ has diameter $\diam$. 
Choose a positive function $f(t)$ so that $f(t)=2\diam^\an-t^\an$ for $0<t\le d$ and $f(t)\sim t^{-(\n+1)}$ for $t\ge 2\diam$. Then it follows that $E^{(\a)}(\Om)\ge E^{(\a)}(B)$
if $B$ is a ball with the same volume as $\Om$, where the equality holds if only if $\Om$ is a ball. 
\end{proof}

\begin{remark}\rm 
The energy defined by \eqref{eq_E} diverges when $\a\le-1$ since $V^{(\a)}_\Om(x)$ ($x\in\interior\Om$, $\a<0$) can be estimated as $O\left(\left(\textrm{dist}(x,\partial\Om)\right)^\a\right)$ near $\partial\Om$.
To have a well-defined energy we need one more renormalization process explained in the introduction. Namely, we expand $\displaystyle \int_{\Om\setminus(\Om\cap N_\e(\partial\Om))}V_{\Om}^{(\a)}(x)\,d\mu(x)$ in a series in $\frac1\e$ 
and subtract the divergent terms.
The detail is studied in \cite{OS} in the case when $\n=2$ and $\a=-2$. 
This renormalized energy can be generalized to Seifert surfaces of knots; thus making a functional on the space of knots, which turns out to be invariant under M\"obius transformations, and can be considered as a renormalization of the average of the square of the linking numbers of the knot and random circles.  

We remark that the proposition above does not hold in general for $\a\le0$.
For example, when $\n=2$ and $\a=-2$, discs attain the minimum, not the maximum (\cite{OS}). 
\end{remark}

\subsection{Uniqueness of \boldmath $r^\an$-centers}
The $r^\an$-center is not necessarily unique, nor is it always continuous with respect to $\a$. 
Let us see it in a baby case when $\n=1$. 
\begin{example}\label{example_pair_of_intervals} \rm 
Let $\Om$ be a disjoint union of two intervals with the same lengths: $\Om=[-R,-1]\,\cup\,[1,R]$, where $R>1$. 
Theorem \ref{thm_existence_center_folded_core} implies that any $r^{\a-1}$-center belongs to $\big[-\frac{1+R}2,\frac{1+R}2\big]$. 
Observe that if $\a\ge1$ or if $\a<1$ and $x\ne\pm1,\pm R$ then 
$$
\frac{d}{dx}V^{(\a)}_\Om(x)=|x+R|^{\a-1}-|x+1|^{\a-1}-|x-R|^{\a-1}+|x-1|^{\a-1}\,.
$$
\begin{enumerate}
\item Suppose $\a>2$. Then $\frac{d^2}{dx^2}V^{(\a)}_\Om(x)>0$ for any $x$. Therefore the origin is the unique $r^{\a-1}$-center. 
\item Suppose $\a=2$. Then $V^{(2)}_\Om$ is constant on $[-1,1]$ and increases as $|x|$ increases if $|x|>1$. Therefore any point in $[-1,1]$ is an $r^{1}$-center. 
\item Suppose $\a=1$. As $\frac{d}{dx}V^{(1)}_\Om(x)=\log\big|\frac{(R+x)(x-1)}{(R-x)(x+1)}\big|$, which vanishes only when $x=\pm\sqrt{R}$, the $r^{0}$-centers are given by $\pm\sqrt{R}$. 
\item Suppose $\a<2$ $(\a\ne1)$. If $1<\a<2$ then $\frac{d^2}{dx^2}V^{(\a)}_\Om<0$ on $[0,1)$ and $\frac{d^2}{dx^2}V^{(\a)}_\Om>0$ on $(1,R)$. On the other hand, if $\a<1$ then $\frac{d^2}{dx^2}V^{(\a)}_\Om>0$ on $[0,1)$ and $\frac{d^2}{dx^2}V^{(\a)}_\Om<0$ on $(1,R)$. 
In both cases, there is a unique point $x_0=x_0(\a)$ in $(1,R)$ that satisfies $\frac{d}{dx}V^{(\a)}_\Om(x_0(\a))=0$. The $r^{\a-1}$-centers are given by $\pm x_0(\a)$. We remark that Theorem \ref{thm_existence_center_folded_core} implies that $x_0(\a)$ is in $\big(1,\frac{R+1}2\big)$ for any $\a$ ($\a<2, \a\ne1$). 
\end{enumerate}

Let us show that $x_0(\a)$ is a smooth function of $\a$ on $(-\infty,1)\cup(1,2)$. 
Define $f:(1,R)\times\left((-\infty,1)\cup(1,2)\right)\to\RR$ by 
$$
f(x,\a)=\frac{d}{dx}V^{(\a)}_\Om(x)=(x+R)^{\a-1}-(x+1)^{\a-1}-(R-x)^{\a-1}+(x-1)^{\a-1}.
$$
Then 
\[f_x(x,\a)=(\a-1)\left[(x+R)^{\a-2}+(R-x)^{\a-2}-(x+1)^{\a-2}+(x-1)^{\a-2}\right]\ne0\]
since $\a-1\ne0$ and $\displaystyle \frac1{(x-1)^{2-\a}}>\frac1{(x+1)^{2-\a}}$ when $x>1$ and $\a<2$. 
As $f(x,\a)$ is a smooth function of $x$ and $\a$, $x_0(\a)$ is a smooth function of $\a$. 

Note that $\displaystyle \lim_{\a\to2-0}x_0(\a)=1$ as $\displaystyle \lim_{\a\to2-0}f(x,\a)=2x-2$, $\displaystyle \lim_{\a\to1}x_0(\a)=\sqrt{R}$ as 
\[
f(x,\a)=(\a-1)\left(\log\frac{(R+x)(x-1)}{(R-x)(x+1)}+O(\a-1)\right),
\]
and $\displaystyle \lim_{\a\to-\infty}x_0(\a)=\frac{R+1}2$. 
\end{example}

We give a sufficient condition for the uniqueness of the ${r^\an}$-centers. 
\subsubsection{Concavity of \boldmath ${V_\Om^{(\a)}\big|_{\interior\Om}}$ $(\a\le1)$ for convex bodies}
\begin{lemma}\label{thm_convexity}
Let $\Om$ be a body in $\RR^\n$ with a piecewise $C^1$ boundary. 
Suppose $\Om$ is convex and $\a\le1$. 
Then $V_{\Om}^{(\a)}$ is a strictly concave function on $\interior\Om$. 
\end{lemma}
\begin{proof}
This is a consequence of Lemma \ref{prop_int_geom} and the following: 
\begin{theorem}{\rm (\cite{HMP}}
If $\phi:\RR_+\to\RR_+$ is concave and strictly increasing, then the map given by 
$$
\RR^\n\ni x\mapsto \int_{S^{\n-1}}\phi(\rhosub{\Om_{-x}}(v))\,d\sigma(v)\in\RR
$$
is strictly concave, where $\rhosub{\Om_{-x}}$ is a radial function of $\Om_{-x}=\{y-x\,|\,y\in\Om\}$. 
\end{theorem}
We can take $\phi(t)=\frac1\a t^\a$ $(\a\le1, \a\ne0)$ or $\phi(t)=\log t$ $(\a=0)$. 
\end{proof}

\begin{theorem}\label{cor_uniqueness_general}
Any body in $\RR^\n$ with a piecewise $C^1$ boundary 
has a unique $r^\an$-center in the interior if $\a\le1$. 
\end{theorem}
\begin{proof}
First remark that the conditions $(\ast\ast)$ in Lemma \ref{lemma_divergence_boundary} and $(\ast\ast\ast)$ in Lemma \ref{lemma_partial_differentiability} are satisfied if $\Om$ is convex. 
Therefore, Theorem \ref{thm_existence_center_folded_core} implies the existence of an $r^\an$-center, and Lemma \ref{lemma_partial_differentiability} implies that $r^\an$-center cannot be on $\partial\Om$ when $0<\a\le1$. 
The uniqueness of the maximum point follows from the strong concavity. 
\end{proof}
