\subsubsection{Convexity of \boldmath $V_\Om^{(\a)}$ $(\a\ge\n+1)$}

\begin{lemma}
Let $\Om$ be a body in $\RR^\n$ with a piecewise $C^1$ boundary. 
If $\a\ge \n+1$ then $\displaystyle \frac{\partial^2 V_{\Om}^{(\a)}}{\partial {x_j}^2}>0$ on $\RR^\n$ for any $j$ $(1\le j\le \n)$. 
\end{lemma}

This follows from the formula \eqref{f_second_partial_derivative_Omega} as $\n\ge2$. 

\begin{theorem}\label{cor_uniquness_alpha_big}
Any body in $\RR^\n$ with a piecewise $C^1$ boundary 
has a unique $r^\an$-center
if $\a\ge \n+1$. 
\end{theorem}

\begin{proof}
Theorem \ref{thm_existence_center_folded_core} guarantees the existence of a $r^\an$-center. 

Assume there are two $r^\an$-centers $x$ and $x'$. 
We may assume, by a rotation of $\RR^\n$, that the line through $x$ and $x'$ is parallel to the $x_1$-axis. 
As $\frac{\partial V_{\Om}^{(\a)}}{\partial {x_1}}(x)=\frac{\partial V_{\Om}^{(\a)}}{\partial {x_1}}(x')=0$, it contradicts $\frac{\partial^2 V_{\Om}^{(\a)}}{\partial {x_1}^2}>0$. 
\end{proof}

\subsection{Asymptotic behavior of \boldmath $r^\an$-centers as $\a$ goes to $\pm\infty$}
In this section we describe the asymptotic behavior of $r^\an$-centers as $\a$ goes to $\pm\infty$. It is generalization of a theorem that an $r^{\a-2}$-center of a non-obtuse triangle approaches the circumcenter as $\a$ goes to $+\infty$ and the incenter as $\a$ goes to $-\infty$, which was announced by Katsuyuki Shibata\footnote{at the 2010 Autumn Meetings of the Mathematical Society of Japan}. 

\begin{lemma}\label{l_asympt_V}
The asymptotic behavior of $V^{(\a)}_\Om(x)$ as $\a$ goes to $\pm\infty$ is given by
$$
\begin{array}{rcl}
\displaystyle \lim_{\a\to+\infty}\left(V^{(\a)}_\Om(x)\right)^{\frac1\a} &=& \displaystyle \max_{y\in\Om}|y-x|,\\[4mm]
\displaystyle \lim_{\a\to-\infty}\left(-V^{(\a)}_\Om(x)\right)^{-\frac1\a} &=& \displaystyle \frac1{\displaystyle \min_{y\in\overline{{\Om}^c}}|y-x|} \hspace{0.5cm}\big(x\in\interior\Om\big).
\end{array}
$$
\end{lemma}
\begin{proof}
This is because when $\a>0$ we have 
$$
\lim_{\a\to+\infty}\left(V^{(\a)}_\Om(x)\right)^{\frac1\a}=\lim_{\a\to+\infty}\left(\int_\Om|y-x|^\an\,d\mu(y)\right)^{\frac1\a} =  \text{ess}\sup_{\hspace{-0.6cm}y\in\Om}|y-x|=\max_{y\in\Om}|y-x|,
$$
and when $\a<0$ and $x\in\interior\Om$ the formula \eqref{f_Va_complement} implies 
$$
\lim_{\a\to-\infty}\left(-V^{(\a)}_\Om(x)\right)^{-\frac1\a}=\lim_{\a'\to\infty}\left(\int_{\Om^c}\left(\frac1{|y-x|}\right)^{\a'+\n}\,d\mu(y)\right)^{\frac1{\a'}}  =  \text{ess}\sup_{\hspace{-0.6cm}y\in\Om^c}\frac1{|y-x|}=  \frac1{\displaystyle \min_{y\in\overline{{\Om}^c}}|y-x|}.
$$
\end{proof}
\begin{definition} \rm 
(1) We call a point an {\em $r^{\infty}$-center} or a {\em min-max point of $\Om$}, denoted by $C_{\infty}$, if the infimum of the map $\mathbb R^\n\ni x\mapsto \max_{y\in\Om}|y-x|\in\RR$ is attained at the point. In other word, it is the center of a ball with the smallest radius that contains $\Om$. 

\smallskip
(2) We call a point an {\em $r^{-\infty}$-center} or a {\em max-min point of $\Om$}, denoted by $C_{-\infty}$, if the supremum of the map $\mathbb R^\n\ni x\mapsto \min_{y\in\overline{{\Om}^c}}|y-x|\in\RR$ is attained at the point.
It is a point in $\interior\Om$ where the maximum of the map $\mathbb R^\n\ni x\mapsto \min_{y\in\partial\Om}|y-x|\in\RR$ is attained. In other words, it is a center of a ball with the biggest radius that is contained in $\Om$. 

\smallskip
(3) We call a point an {\em asymptotic $r^{-\infty}$-center of $\Om$} if it is the limit of a convergent sequence of $r^{\a_i-\n}$-centers with $\a_i\to-\infty$ as $i\to+\infty$.  
\end{definition}
It is easy to see that both min-max and max-min points exist. 
Put
$$
R_
=\min_{x\in\RR^\n}\max_{y\in\Om}|y-x|, 
\>\> r_0
=\max_{x\in\RR^\n}\min_{y\in\overline{{\Om}^c}}|y-x|. 
$$

\begin{lemma}\label{lemma_unique_min-max}
A min-max point of a compact set $\Om$ is unique, whereas a max-min point is not necessarily unique. 
\end{lemma}
\begin{proof}
The first statement is obvious, and the second can be indicated by a rectangle. 
\end{proof}


\begin{proposition}
A min-max point is contained in the maximal unfolded region, and so is a max-min point if it is unique.
\end{proposition}
\begin{proof}
Put $R_x=\max_{y\in\Om}|y-x|, \>\>r_x=\min_{y\in\overline{{\Om}^c}}|y-x|$ for $x\in\RR^\n$. 

We use notation in subsection \ref{subs_min_unfold_region}. 
Let $x$ be a point in a maximal cap in direction $v$, $\Om_{v,l_v}^+$. 
Since $\textrm{Refl}_{v,l_v}(\Om_{v,l_v}^+)\subset\Om$, $R_x$ is attained by $y\in\Om\setminus\Om_{v,l_v}^+$, and since $\textrm{Refl}_{v,x\cdot v}(\Om_{v,x\cdot v}^+)\subset\Om$, $r_x$ is attained by $y'\in\partial\Om_{v,x\cdot v}^+\cap\partial\Om$. 
Suppose $x_2=x_1+\e v$ $(x_1,x_2\in\Om_{v,l_v}^+, \e>0)$. 
As an affine hyperplane $\{x\,|\,x\cdot v=l_v\}$ separates $\Om\setminus\Om_{v,l_v}^+$ and $\Om_{v,l_v}^+$, $R_{x_1}<R_{x_2}$, which means that a point in $\Om_{v,l_v}^+$ cannot be a min-max point. 
On the other hand, as $\Om_{v,l_v}^+$ is convex in the direction $v$, $r_{x_1}\ge r_{x_2}$, which means that a point in $\Om_{v,l_v}^+$ cannot be a unique max-min point. 
\end{proof}

\begin{lemma}
Put 
$$
\rhosub{\Om_{-x}}^{\sup}(v)=\sup\{a>0\,|\,x+av\in\Om\}, \>
\rhosub{\Om_{-x}}^{\inf}(v)=\inf\left\{a>0\,|\,x+av\in\overline{\Om^c}\,\right\
$$
for $x\in\RR^\n,\,v\in S^{\n-1}$ and 
$$
\mathcal{V}_{\rm max}=\{v\in S^{\n-1}\,|\,\rhosub{\Om_{-C_{\infty}}}^{\sup}(v)=R_0\}, \> 
\mathcal{V}_{\rm min}(C_{-\infty})=\{v\in S^{\n-1}\,|\,\rhosub{\Om_{-C_{-\infty}}}^{\inf}(v)=r_0\}, \> 
$$
where $C_{\infty}$ is the unique min-max point and $C_{-\infty}$ a max-min point.
Then 
$$
\bigcup_{v\in\mathcal{V}_{\rm max}}\{u\in S^{\n-1}\,|\,u\cdot v\ge0\}=
\bigcup_{v\in\mathcal{V}_{\rm min}(C_{-\infty})}\{u\in S^{\n-1}\,|\,u\cdot v\ge0\}=S^{\n-1}. 
$$
\end{lemma}

\begin{proof}
Let us show $\cup_{\stackrel{\phantom{}}{v\in\mathcal{V}_{\rm max}}}\{u\in S^{\n-1}\,|\,u\cdot v\ge0\}=S^{\n-1}$. The proof for $\mathcal{V}_{\min}(C_{-\infty})$ goes parallel. 

Let $B$ be a ball with center $C_{\infty}$ and radius $R_0$, which contains $\Om$. 
If $\partial B$ touches $\partial\Om$ only in points in a compact subset of an open hemisphere of $\partial B$, $\{C_{\infty}+R_0v\,|\,v\in S^{\n-1},\>v\cdot v_0>0\}$ for some $v_0\in S^{\n-1}$, we can move the ball $B$ a little bit in the direction of $v_0$ and make it smaller to have a new ball containing $\Om$ whose radius is smaller than $R_0$, which is a contradiction. 
\end{proof}

It follows that both $\mathcal{V}_{\rm max}$ and $\mathcal{V}_{\rm min}(C_{-\infty})$ contain at least two points each. Therefore, 

\begin{corollary}
Let $\mathcal M$ be a set of max-min points of $\Om$. 
Then it is a subset of the {medial axis}, which is the set of points $x$ in $\interior\Om$ that have at least two points on $\partial\Om$ that give the distance between $x$ and $\partial\Om$. 
\end{corollary}


\begin{lemma}
For any $\e>0$ there are real numbers $\a_\e^+$ $(\a_\e^+>\n)$ and $\a_\e^-$ $(\a_\e^-<0)$ such that if $\a>\a_\e^+$ then an $r^\an$-center is contained in $B_\e(C_{\infty})$ and that if $\a<\a_\e^-$ then an $r^\an$-center is contained in $N_\e(\mathcal M)$ which is an $\e$-neighbourhood of the set of max-min points $\mathcal M$. 
\end{lemma}

\begin{proof}
We only give the proof of the second statement, as that of the first goes parallel. 

Assume there is no such $\a_\e^-$. 
Then there is a sequence of $r^\an$-centers $\{C_{\a_i-\n}\}_{i\in\mathbb N}$ $(\a_i<0)$ in the complement of $N_\e(\mathcal M)$ with $\a_i\to-\infty$ as $i\to+\infty$. 
As $\{C_{\a_i-\n}\}_{i\in\mathbb N}$ is contained in a compact set $\Om\setminus N_\e(\mathcal M)$, there is a convergent subsequence, which we denote by the same symbol $\{C_{\a_i-\n}\}$, with the limit $C'\in \Om\setminus N_\e(\mathcal M)$. 
We have $r_{C'}<r_0$ as $C'\not\in\mathcal{M}$. 
There is a point $p$ in $\partial\Om$ with $|p-C'|=r_{C'}$. 
Put $\delta=(r_0-r_{C'})/3$ and $b=\textrm{Vol}\left(B_\delta(p)\cap\Om^c\right)$, then $b>0$. 
Suppose $x\in B_\delta(C')\cap\interior\Om$. 
Then if $y\in B_\delta(p)\cap\Om^c$, $|x-y|\le r_{C'}+2\delta=r_0-\delta$, and therefore the formula \eqref{f_Va_complement} implies that $V^{(\a)}_\Om(x)\le-(r_0-\delta)^\an b$ for $\a<0$. 
On the other hand, since $\Om\supset B_{r_0}(C_{-\infty})$, corollary \ref{cor_Omega_1_subset_Omega_2} and the formula \eqref{V^a_int_S^m-1} imply $V^{(\a)}_\Om(C_{-\infty})\ge\frac1\a r_0^\a A(S^{\n-1})$. 
Since 
$$
-\a\left(\frac{r_0}{r_0-\delta}\right)^{-\a}>\frac{(r_0-\delta)^\n A(S^{\n-1})}{b}
$$
for sufficiently small $\a$, $V^{(\a)}_\Om(x)< V^{(\a)}_\Om(C_{-\infty})$ for such $\a$, which implies that a point $x$ in $B_\delta(C')\cap\interior\Om$ cannot be an $r^\an$-center for sufficiently small $\a$. 
This contradicts the assumption that $C'$ is the limit of $r^{\a_i-\n}$-centers with $\a_i\to-\infty$ as $i\to+\infty$. 
\end{proof}

Recall that the {\sl Hausdorff distance} $d_H(X,Y)$ between subsets $X$ and $Y$ in $\RR^\n$ is given by 
$$
d_H(X,Y)=\inf\{\e>0\,|\,X\subset (Y)_\e, \, Y\subset(X)_\e\},\> (X)_\e=\bigcup_{x\in X}B_\e(x).
$$
When $X$ is a singleton, i.e. $X=\{x\}$, $d_H(\{x\},Y)=\sup_{y\in Y}|x-y|$

\begin{theorem}
\begin{enumerate}
\item The $r^\an$-center converges to the $r^\infty$-center i.e. the min-max point as $\a$ goes to $+\infty$. 

\item An asymptotic $r^{-\infty}$-center is an $r^{-\infty}$-center, i.e. the limit of any convergent sequence of $r^{\a_i-\n}$-centers with $\a_i\to-\infty$ as $i\to+\infty$ is a max-min point. 
Especially, when the max-min point is unique, the sets of $r^\an$-centers $\mathcal{C}_\an$ converges to $\{C_{-\infty}\}$ as $\a$ goes to $-\infty$ with respect to Hausdorff distance. 
\end{enumerate}
\end{theorem}

\section{Introduction}
It is widely accepted that current catalogues have a distinct deficit of young Galactic Supernova Remnants (SNRs), that is, SNRs $<$2000 years old, with only $\sim$10 confirmed out of a predicted $\sim$50 \citep{1991ARA&A..29..363V, 2003LNP...598...37C}. Of these confirmed SNRs, \mbox{{G1.9+0.3}}\ is of particular interest as it is believed to be the youngest in the Milky Way at $\la150$ years old \citep{2008ApJ...680L..41R,2008MNRAS.387L..54G}.

Originally identified as a probable SNR by \citet{1984Natur.312..527G} at 4.9~GHz using the Very Large Array (VLA), \mbox{{G1.9+0.3}}\ was described as a shell source with an approximate brightness slightly less than that of the Tycho and Kepler SNRs with a spectral index of $\sim$--0.7\footnote{Spectral index defined as $S\propto\nu^\alpha$}. Using the Molonglo Observatory Synthesis Telescope (MOST) Galactic Survey data, \citet{1994MNRAS.270..835G} confirmed the classification of \mbox{{G1.9+0.3}}\ as an SNR: the source was described as featuring a shell-like morphology in the radio with an estimated diameter of 1\farcm2.  Later \citet{2000AJ....119..207L} produced a 90-cm image of \mbox{{G1.9+0.3}}\ made with the VLA: those authors estimated the 20/90-cm spectral index of the SNR to be $-0.93\pm0.25$ and the angular  diameter to be 1\farcm1. \citet{2004AJ....128.1646N} revisited the data collected by \citet{2000AJ....119..207L} and -- through the application of superior data reduction techniques -- measured the diameter of \mbox{{G1.9+0.3}}\ to be $<$1\arcmin. Finally, \citet{2004BASI...32..335G} estimates the diameter of \mbox{{G1.9+0.3}}\ based on 1.49~GHz VLA observations made in 1985 to be of 1\farcm2. In short, multiple radio observations have confirmed that \mbox{{G1.9+0.3}}\ has the smallest angular diameter for a known Galactic SNR, indicative of its young age.

Earlier this year \citet{2008MNRAS.387L..54G} reobserved \mbox{{G1.9+0.3}}\ at 4.86~GHz using the VLA after \citet{2008ApJ...680L..41R} used recent {\it Chandra} images to show \mbox{{G1.9+0.3}}\ had expanded significantly since 1985 and it's X-ray emission appeared  to be purely synchrotron radiation. By comparing these new VLA observations with the 1985 VLA observations made at 1.49~GHz \citet{2008MNRAS.387L..54G} determined that \mbox{{G1.9+0.3}}\ had expanded by $15\%\pm2\%$ over 23 years. Most recently, \citet{2008arXiv0806.1952M} found that \mbox{{G1.9+0.3}}'s flux density at 843~MHz increased by $1.22\pm ^{0.24}_{0.16}$ \% per year over the last two decades.

In this paper we present our results of a previously unpublished 6-cm radio-continuum observation of \mbox{{G1.9+0.3}}\ made in 1993 that was found on an examination of the Australia Telescope Compact Array (ATCA) database. It must be emphasised that this radio observation has the highest angular resolution of any other radio image of \mbox{{G1.9+0.3}}\ yet presented and does not suffer from the distorted beam shapes that are inherent in observations made using the VLA when observing objects such as this, that are at low Declinations.  We report on the morphology, expansion rate, age, diameter and polarisation properties of this SNR.

\section{Observations and Data reduction}
\mbox{{G1.9+0.3}}\ was observed with the ATCA on 10 June 1993 (Project C034; PI A. Gray) at two 6-cm bands centred on 4672 and 5440~MHz with the telescope in 6A configuration. The observations were done in so-called ``snap-shot'' mode, totaling $\sim$1 hour of integration spread equally over a 12 hour period. Source 1934-638 was used for primary calibration and source 1748-253 was used for secondary calibration. The \textsc{miriad} \citep{2006miriad} and \textsc{karma} \citep{2006karma} software packages were used for reduction and analysis.

The final 6-cm image (Fig.~1) has a resolution of 4\arcsec\ and the r.m.s noise is estimated to be 0.2~mJy~beam$^{-1}$. We acknowledge that this image may suffer from missing short spacings and incomplete hour angle coverage. However, we argue that even with these shortcomings, the image is sufficient for initial morphological and comparative study. We also emphasise that this radio-continuum observation of \mbox{{G1.9+0.3}}\ is of the highest resolution currently available.

