    \centering
    \caption{Estimates of the detection thresholds for Ca, Mg and Fe for the sample of 230 white dwarfs.}
    \label{tab:thresh}
    \begin{tabular}{lccc}
        \hline
        Element & Ca & Mg & Fe \\
        \hline
        Threshold/g & $2.9\times 10^{18}$ & $1.3\times 10^{19}$ & $2.3\times 10^{19}$ \\
