\centering
\includegraphics[width=0.6\columnwidth]{Diamond_XRTS_comparison_plot3.pdf} 
\caption{ \small{The imaginary part of the inverse dielectric function for diamond at warm dense matter conditions ($p=150$ GPa, $T=6000$ K) in the optical limit. } }
\label{Diamond_wdm}
