\section{Diffusion limit for the MGCPP: Deterministic Centralization}\label{sec4}

We proved a LLN and FCLT for the MGCPP in the previous Section. And the limit theorems provide us an approximation for the mid-price modeling in the LOB. Recall the approximation in Remark \ref{aprem}, we have 
\begin{equation} \label{fcltap1}
\vec{S}_{nt}  \sim \Tilde{\sigma}^* \Lambda^{1/2} \Vec{W}(t)\sqrt{n} + \Tilde{a^*} \vec{N}_{nt},
\end{equation}
where the $\vec{S}_{nt}$ is the price process and $\vec{N}_{nt}$ is the order flow. However, in the real-world problems, equation (\ref{fcltap1}) cannot help us with the forecasting task directly because we couldn't have the order flow $\vec{N}_{nt}$ in advance. This motivates us to consider a FCLT \RomanNumeralCaps{2} for the MGCPP in this Section.

\subsection{FCLT for MGCPP: Deterministic Centralization}
\begin{theorem} \label{fclt2t} (FCLT \RomanNumeralCaps{2}: Deterministic Centralization). Let $X_{i,k}, \, i=1,2,\cdots,d$ be independent ergodic Markov chains with $n$ states $\{1,2,\cdots,n\}$ and with ergodic probabilities $\left(\pi_{i,1}^{*}, \pi_{i,2}^{*}, \ldots, \pi_{i,n}^{*}\right)$. Let $\vec{S}_{nt}$ be $d$-dimensional compound point process, we have 
	\begin{equation} \label{FCLT2}
	\frac{\vec{S}_{nt} - \Tilde{a^*}  E(\vec{N}_{nt})}{\sqrt{n}} \longrightarrow \Tilde{\sigma}^* \Lambda^{1/2} \Vec{W}_1(t) + \Tilde{a^*} \Sigma^{1/2}\Vec{W}_2(t), \, for\, all\, t>0 
	\end{equation}   
	as $n \rightarrow \infty$, where $\Vec{W}_1(t)$ and $\Vec{W}_2(t)$ are independent standard $d$-dimensional Brownian motions. Parameters $\Tilde{\sigma}^*$, $\Tilde{a^*}$, $\Lambda$, and $\Sigma$ are defined in Theorem \ref{FCLT1}.
\end{theorem}

\begin{proof}[Proof of Theorem \ref{fclt2t}]
	Recall the FCLT for MPP (assumption \ref{as2}), we have
	\begin{equation}\label{PPfclt}
	\bigg(  \frac{1}{\sqrt{n}} \vec{N}_{nt} -\frac{1}{\sqrt{n}} E(\Vec{N}_{nt}) \bigg) \longrightarrow \mathbf{\Sigma}^{1/2}\Vec{W}_t
	\end{equation}
	in law for the Skorokhod topology, as $n \rightarrow \infty$. And from theorem \ref{FCLT1}, we have the FCLT  for MGCPP
	\begin{equation} \label{fclt1r}
	\frac{\vec{S}_{nt} - \Tilde{a^*} \vec{N}_{nt}}{\sqrt{n}} \longrightarrow \Tilde{\sigma}^* \Lambda^{1/2} \Vec{W}_t, \, for\, all\, t>0 
	\end{equation}   
	as $n \rightarrow \infty$ in the weak law of Skorokhod topology. Here, we assume two multivariate Brownian motions in (\ref{PPfclt}) and (\ref{fclt1r}) are mutually independent and we refer them $\vec{W}_2(t)$ and $\vec{W}_1(t)$. Next, consider
	\begin{equation}
	\frac{\vec{S}_{nt}}{\sqrt{n}} -  \frac{\Tilde{a}^*   E(\Vec{N}_{nt})}{\sqrt{n}}  = \frac{\vec{S}_{nt} - \Tilde{a}^* \vec{N}_{nt}}{\sqrt{n}}  +  \Tilde{a}^* \bigg(  \frac{1}{\sqrt{n}} \vec{N}_{nt} -\frac{1}{\sqrt{n}}E(\Vec{N}_{nt}) \bigg).
	\end{equation}   
	With (\ref{PPfclt}) and (\ref{fclt1r}) we can derive
	\begin{equation}
	\frac{\vec{S}_{nt} - \Tilde{a}^* \vec{N}_{nt}}{\sqrt{n}}  +  \Tilde{a}^* \bigg(  \frac{1}{\sqrt{n}} \vec{N}_{nt} -\frac{1}{\sqrt{n}}E(\Vec{N}_{nt}) \bigg) \longrightarrow \Tilde{\sigma}^* \Lambda^{1/2} \Vec{W}_1(t) + \Tilde{a^*} \Sigma^{1/2}\Vec{W}_2(t)
	\end{equation} 
	as $n \rightarrow \infty$ which gives (\ref{FCLT2}).
\end{proof}


\begin{rem}
	We can also consider a special case as the FCLT \RomanNumeralCaps{1}. Let $X_{i,k}$ be a Markov chain with two dependent states $(+\delta,-\delta)$ and the ergodic probabilities are $\left(\pi_{i}^{*}, 1-\pi_{i}^{*}\right)$. Set $a_i(x) = x$ in the definition \ref{priceprocess}. Then, we can derive a similar result for FCLT \RomanNumeralCaps{2}. Parameters $\Tilde{a}^*$ and $\Tilde{\sigma}^*$ can be computed by equation (\ref{sigmastar}).
\end{rem}

\begin{rem} \label{rem3}
	For the FCLT \RomanNumeralCaps{2}, we can also consider a similar approximation as the FCLT \RomanNumeralCaps{1}. For some large enough $n$, we have
	\begin{equation} \label{FCLTap2}
	\vec{S}_{nt}  \sim \sqrt{n} \Tilde{\sigma}^* \Lambda^{1/2} \Vec{W}_1(t) + \sqrt{n} \Tilde{a^*} \Sigma^{1/2}\Vec{W}_2(t) + \Tilde{a^*}  E(\vec{N}_{nt}), \, \text{for all $t>0$}. 
	\end{equation}  
	To deal with the $E(\vec{N}_{nt})$ term, we consider the approximation derived from assumption \ref{as1} in equation (\ref{expnt}):
	\begin{equation}
	E(\Vec{N}(nt)) \sim nt\Vec{\bar{\lambda}}.
	\end{equation}	
	Rewrite equation (\ref{FCLTap2}), we have the new approximation
	\begin{equation} \label{FCLTap3}
	\vec{S}_{nt}  \sim \sqrt{n} \Tilde{\sigma}^* \Lambda^{1/2} \Vec{W}_1(t) + \sqrt{n} \Tilde{a^*} \Sigma^{1/2}\Vec{W}_2(t) + \Tilde{a^*}  nt\Vec{\bar{\lambda}}.
	\end{equation}	
\end{rem}


