\centerline{\includegraphics[width=\paperwidth]{sky_distribution_30102021.pdf}}. 
\caption{The two-dimensional projection of the positions of all planet hosts in the {\it NASA Exoplanet Archive} up to October 30$^{th}$ 2021, color-coded by the discovery technique.} \label{plotsky}
\end{figure}

