\section{Problem Statement} \label{2}
\begin{figure}[t]
\centering
    \includegraphics[width=0.5\linewidth]{GAVFC_Gains.pdf}
    \caption{Gaussian Arbitrarily-Varying Fading Channel.}
    \label{fig:GAVFC}
\end{figure}

The Gaussian arbitrarily-varying fading channel (GAVFC) in Fig. \ref{fig:GAVFC} is a point-to-point fading channel with additive Gaussian noise and an intelligent adversary who does not have any information about the transmitted signal except the code. The received signal is given by 
\begin{align}\label{eq:1}
\begin{split}
\mathbf{Y} = \mathbf{G} \circ \mathbf{x} + \mathbf{s} + \mathbf{V}
\end{split}
\end{align} 
where $\mathbf{G}$ is a random sequence of identical and independently distributed (i.i.d.) fast fading channel gains from the legitimate transmitter to the receiver drawn from continuous distribution $f_G(g)$ assumed to have positive and finite variance, $\mathbf{x}$ is the $n$-length deterministic vector representing the user's signal, $\mathbf{s}$ is the adversary signal chosen arbitrarily, and $\mathbf{V}$ is a random $n$-length noise vector distributed as a sequence of i.i.d. zero mean Gaussian random variables with variance $\sigma^2$, independent of $\mathbf{x}$, $\mathbf{G}$ and $\mathbf{s}$. Note that the receiver always knows the exact fading coefficients $\mathbf{g}$ while the transmitter and the adversary may not know the gains, know them causally, or know them non-causally. 

Define an $\left(N,n\right)$ code for the GAVFC by a message set, an encoding function and a decoding function as follows:
\begin{itemize}
  \item Message set $\mathcal{M}=[N]$,
  \item Encoding function (one of the following)
	\begin{itemize}
	\item (No knowledge) $\mathbf{x}(m):\mathcal{M}\to \mathbb{R}^n$ where $\mathbf{x} = (x_1,\ldots,x_n)$,

	\item (Causal) $x_i(m,\mathbf{g}^i)\!\!:\!\mathcal{M}\times \mathbb{R}^i \to \mathbb{R}$	where $\mathbf{g}^i\!=\!(g_1,\ldots,g_i)$ and $\mathbf{x} \!=\! (x_1,\ldots,x_n)$ for $i\in[n]$,
	\item (Non-causal) $x_i(m,\mathbf{g})\!\!:\!\mathcal{M}\times \mathbb{R}^n\!\to\! \mathbb{R}$ where $\mathbf{g}\!=\!(g_1,\ldots,g_n)$ and $\mathbf{x} \!=\! (x_1,\ldots,x_n)$~for~$i\!~\in~[n]$,
	\end{itemize}

	\item Decoding function $\Theta(\mathbf{y},\mathbf{g}):\mathbb{R}^n\times \mathbb{R}^n\to\mathcal{M}$,
\end{itemize}
where the rate of the code is $R = \frac{1}{n}\log (N)$. The message $m$ is drawn uniformly from the set $\mathcal{M}$. If the encoder does not know the channel gains, it maps the message to $\mathbf{x}(m)\in \mathbb{R}^n$. If the encoder knows the channel gains causally, then it maps the message to $x_i(m,\mathbf{g}^i)\in \mathbb{R}$, and if the encoder knows the channel gains non-causally, then it maps the message to $x_i(m,\mathbf{g})\in \mathbb{R}$ where $\mathbf{x} = (x_1,\ldots, x_n)$. Given channel gains $\mathbf{g}$ at the receiver, the signal $\mathbf{y}$ is decoded by function $\Theta(\mathbf{y},\mathbf{g})$ to the message $\hat{m}$. Moreover, we assume that if the channel gains are available at the transmitter then the transmitter's signal satisfies the expected power constraints $\mathbb{E} \left[\|\mathbf{X}(m,\mathbf{G})\|^2\right]\leq nP$ for any message $m\in \mathcal{M}$. Otherwise, the power constraint is $\|\mathbf{x}(m)\|^2\leq nP$. The same definition applies to the adversary's signal power constraint, i.e. if the adversary knows the channel gains, the constraint is $\mathbb{E} \left[\|\mathbf{S}(\mathbf{G})\|^2\right]\leq n\Lambda$; otherwise, it is $\|\mathbf{s}\|^2\leq n\Lambda$. The three parameters $P$, $\Lambda$, and $\sigma^2$ as well as the distribution of fading gains $f_G(g)$ are known to all parties.

The probability of error $e(\mathbf{s},m)$ for the message $m \in \mathcal{M}$ in the presence of adversary signal $\mathbf{s}\in \mathbb{R}^n$ is now given by the probability that $\hat{m}\neq m$. Thus, the average probability of error for a specific $\mathbf{s}\in \mathbb{R}^n$ is
\begin{align}
	\bar{e}(\mathbf{s}) = \frac{1}{N}\sum_{m=1}^N e(\mathbf{s},m).
\end{align}
If the adversary knows the channel gains non-causally then his signal is denoted by $s_i(\mathbf{g})$ for $i\in [n]$. Alternatively, if the adversary knows the gains causally, then the adversary's action is given by functions $s_i(\mathbf{g}^i)$ for $i\in [n]$ where $\mathbf{s} = (s_1,\cdots,s_n)$ and $\mathbf{g}^i = (g_1,\cdots,g_i)$. Therefore, the average probability of error for this specific $\mathbf{s}(G)\in \mathbb{R}^n$ is
\begin{align}
\bar{e} (\mathbf{s}(\cdot)) = \frac{1}{N}\sum_{m=1}^N \mathbb{E} e(\mathbf{s} (\mathbf{G}),m).
\end{align}
Finally, the overall probability of error $P_e^{(n)}$ is maximized over all possible choices of jammers' sequences $\mathbf{s}$ which satisfy either $\mathbb{E} \left[\|\mathbf{S}\|^2\right]\leq n\Lambda$ or $\|\mathbf{s}\|^2\leq n\Lambda$. Rate $R$ is \emph{achievable} if there exists a sequence of $\left(2^{nR},n\right)$ codes where $\underset{n \rightarrow \infty}{\lim}P_e^{(n)} = 0$. The capacity is the supremum of all achievable rates. We denote the capacity of the GAVFC as $C_{\alpha,\beta}$ where $\alpha$ denotes the transmitter's knowledge, and $\beta$ denotes the adversary's knowledge; $\alpha$ and $\beta$ can be U, C, or N depending on whether the transmitter or adversary does not know the gains (U $=$ unknown), knows the gains causally (C), or knows the gains non-causally (N). For example, $C_{\text{U,N}}$ is the capacity where the transmitter does not know the gains and the adversary knows the gains non-causally.



\section{Main Results}\label{3}
We present our results for the capacity of GAVFC whether the fading channel gains $\mathbf{G}$ are available causally or non-causally at the encoder and/or the adversary (the decoder always knows the gains) in the following theorems. 

\begin{theorem}\label{Thrm} The capacities of the GAVFC are given by 
\begin{align}
	&C_{\text{U,U}} = \mathbb{E}_G \left[C\left(\frac{G^2P}{\Lambda+\sigma^2}\right)\right],\label{C1Capacity}\\
&C_{\text{N,U}} = C_{\text{C,U}} = 
	\underset{\substack{\varphi(g):\mathbb{E} \varphi(G)\leq P}}{\max}\mathbb{E}_G \left[C\left(\frac{G^2\varphi(G)}{\Lambda+\sigma^2}\right)\right],\label{C2Capacity}\\
&C_{\text{U,N}} = C_{\text{U,C}} =\begin{cases}
	\underset{\psi(g):\mathbb{E} \psi(G)\leq \Lambda}{\min}\mathbb{E}_G \left[C\left(\frac{G^2P}{\psi(G)+\sigma^2}\right)\right],\! & \mathbb{E} G^2P\!>\!\Lambda\\
	0,\! & \mathbb{E} G^2P\!\le\!\Lambda
\end{cases}\label{C3Capacity}\\
	&C_{\text{N,N}} =\! C_{\text{C,C}}\! =\! C_{\text{C,N}} =\nonumber\\
	&\begin{cases}
	\underset{\substack{\varphi(g):\mathbb{E} \varphi(G)\leq P,\\ \mathbb{E} G^2\varphi(G)\geq\Lambda}}{\max} \ \  \underset{\psi(g):\mathbb{E} \psi(G)\leq \Lambda}{\min}\mathbb{E}_G \left[C\!\left(\frac{G^2\varphi(G)}{\psi(G)+\sigma^2}\right)\!\right], & \text{if}\underset{\varphi(g):\mathbb{E} \varphi(G)\leq P}{\max}\mathbb{E} G^2\varphi(G)>\Lambda \\
	0,  & \text{if} \underset{\varphi(g):\mathbb{E} \varphi(G)\leq P}{\max}\mathbb{E} G^2\varphi(G)\le \Lambda
	\end{cases}\label{C4Capacity}\\
	&C_{\text{N,C}} = 
	\underset{\substack{\varphi(g):\mathbb{E} \varphi(G)\leq P}}{\max} \ \  \underset{\psi(g):\mathbb{E} \psi(G)\leq \Lambda}{\min}\mathbb{E}_G \left[C\!\left(\frac{G^2\varphi(G)}{\psi(G)+\sigma^2}\right)\!\right].\label{C42Capacity}
\end{align}
\end{theorem}

Note that when the encoder knows the gains \eqref{C2Capacity}, \eqref{C4Capacity}, and \eqref{C42Capacity}, the capacity expression includes a maximization of the input power as a function $\varphi(\cdot)$ of the gain, similar to the result in \cite{Varaiya}. Similarly, when the jammer knows the gains \eqref{C3Capacity}--\eqref{C42Capacity}, the capacity expression includes a minimization that represents the jammer's choice of noise power as a function $\psi(\cdot)$ of the gain. Moreover, when the jammer knows the gains, with enough power it can symmetrize the channel by mimicking the legitimate signal, thus reducing the capacity to zero. However, in \eqref{C42Capacity} we have assumed that the adversary knows the gains causally and the encoder and the decoder know the gains non-causally. Thus, the encoder and decoder effectively share a secret (the channel gains at the end of the block) unknown to the adversary, so the adversary cannot symmetrize the channel. It is also worth mentioning that for the other cases (except \eqref{C42Capacity}) our proof works exactly the same whether the transmitter and/or the adversary know the gain sequence causally, non-causally, or even memorylessly (i.e., at time $i$, you only know the gain value at time $i$). 

While we have stated the theorem by writing the capacities in terms of optimization over the $\varphi$ and/or $\psi$ functions, these expressions can be computed by solving for the optimizing functions. In particular, the optimum value of $\varphi^*(g)$ in \eqref{C2Capacity} is $\left|\lambda-\frac{\Lambda+\sigma^2}{g^2}\right|^+$ where $\lambda$ is obtained by $\mathbb{E} [\varphi^*(G)]=P$, and 
the optimum value of $\psi^*(\cdot)$ in \eqref{C3Capacity} is a function of gain $g$ as follows
\begin{align}
\psi^*(g) = \left|\frac{-2\sigma^2-g^2P+\sqrt{g^4P^2+\frac{2g^2P}{\lambda}}}{2}\right|^+,\label{fi_g3}
\end{align}
and $\lambda$ is obtained by solving $\mathbb{E} \psi^*(G) = \Lambda$. Moreover, the optimum values of $\varphi^*(g)$ and $\psi^*(g)$ in \eqref{C4Capacity} are 
\begin{align}
\varphi^*(g) &= \left| \frac{1}{2(\lambda_1-g^2\lambda_3) \left(1+\frac{\lambda_1-g^2\lambda_3}{g^2\lambda_2}\right)}\right|^+\\
\psi^*(g) &= \left|\frac{g^2}{2g^2\lambda_2+2(\lambda_1-g^2\lambda_3)}-\sigma^2\right|^+,
\end{align}
where $\lambda_1$, $\lambda_2$ and $\lambda_3$ are found by solving $\mathbb{E} \varphi(G)= P$, $\mathbb{E} \psi(G)= \Lambda$ and $\mathbb{E} G^2\varphi(G)=\Lambda$, respectively.
Finally, the optimum values of $\varphi^*(g)$ and $\psi^*(g)$ in \eqref{C42Capacity} are
\begin{align}
\varphi^*(g) &= \left| \frac{1}{2\lambda_1 \left(1+\frac{\lambda_1}{g^2\lambda_2}\right)}\right|^+\\
\psi^*(g) &= \left|\frac{g^2}{2g^2\lambda_2+2\lambda_1}-\sigma^2\right|^+,
\end{align}
where $\lambda_1$ and $\lambda_2$ can be obtained by solving $\mathbb{E} \varphi(G)= P$ and $\mathbb{E} \psi(G)= \Lambda$, respectively.


In the Fig. \ref{fig:GAVFC_Simu}, the capacity of GAVFC with Rayleigh fading is shown for $P=1, \sigma^2=0.25, 0<\Lambda<5$ and the Rayleigh distribution scale parameter $\sigma_R = 1$ whether the channel gains are available at the encoder and/or the adversary. However, $C$ is the capacity of Gaussian arbitrary-varying channel with no fading. Note that when the transmitter's knowledge increases, the capacity increases, whereas when the adversary's knowledge increases, the capacity decreases. On the other hand, the knowledge of adversary about the channel gains may decrease the capacity, and in this case if the adversary's power exceeds $2$, the capacity will be zero by the symmetrizability. 


The proofs of the different capacity variants all follow a similar pattern, so we have attempted to reduce the redundancy in our presentation. We provide essentially one converse proof for each capacity expression in the theorem:
\begin{enumerate}
\item Sec. \ref{subsecV-A}: Converse for $C_{U,U}$.
\item Sec. \ref{subsecVI-A}: Converse for $C_{N,U}$. This also bounds $C_{C,U}$ which is trivially upper bounded by $C_{N,U}$.
\item Sec. \ref{subsecVII-A}: Converse for $C_{U,C}$. This also bounds $C_{U,N}$ which is trivially upper bounded by $C_{U,C}$.
\item Sec. \ref{subsecVIII-A}: Converse for $C_{C,C}$. This also bounds $C_{C,N}$ which is trivially upper bounded by $C_{C,C}$. Essentially the same proof also works for $C_{N,N}$. The case $C_{N,C}$ requires a different proof also covered in this section.
\end{enumerate}
We provide essentially three achievability proofs:
\begin{enumerate}
\item Sec. \ref{subsecVI-B}: Achievability for $C_{C,U}$. This also bounds the $C_{N,U}$, which is trivially lower bounded by $C_{C,N}$. It also provides a bound for $C_{U,U}$, because the same proof works assuming $\varphi(g)=P$ (i.e., the encoder's power is independent of the channel gain).
\item Sec. \ref{subsecVIII-B}: Achievability for $C_{C,N}$. This also bounds $C_{N,N}$ and $C_{C,C}$, which are trivially lower bounded by $C_{C,N}$. It also provides a bound for $C_{U,N}$ and $C_{U,C}$, because the same proof works again assuming $\varphi(g)=P$.
\item Sec. \ref{subsecVIII-C}: Achievability for $C_{N,C}$. This case is different from all others in that there is effectively a shared secret between encoder and decoder.
\end{enumerate}

