&\left(\frac{P_\mathrm{orb}}{{\rm day}}\right) ^{-2}
&\left(\frac{\beta R_1}{R_{\odot}}\right)^3
&\\
\nonumber
+759 \ \alpha_\mathrm{e0b,1} 
\left(8-40 \sin^2 i +35 \sin^4 i \right)
&\left(\frac{M_1}{M_{\odot}}\right)^{-5/3}
&\frac{q}{(1+q)^{5/3}}
&\left(\frac{P_\mathrm{orb}}{ {\rm day}}\right) ^{-10/3} 
&\left(\frac{\beta R_1}{R_{\odot}}\right)^5
&\\
\nonumber
+3194 \ \alpha_\mathrm{e1,1} 
\left(4 \sin i - 5 \sin^3 i \right)
&\left(\frac{M_1}{M_{\odot}}\right)^{-4/3}
&\frac{q}{(1+q)^{4/3}}
